/// Whether the builtin dispatcher serves `name` — either half of it.
///
/// A name this answers `false` for is not a builtin: it may be a user-defined
/// function, a module member, or nothing at all. Callers reasoning about safety
/// must treat `false` as *unknown*, never as *harmless*.
pub fn is_dispatched(name: &str) -> bool {
    BUILTIN_LOOKUP.contains_key(name)
        || FALLBACK_BUILTINS
            .binary_search_by_key(&name, |(n, _)| n)
            .is_ok()
}

/// Names that reach the same implementation, grouped — across both halves of
/// the dispatcher.
///
/// `BUILTIN_LOOKUP` aliases share a dispatch index (`ls` and `list` are both 8);
/// fallback aliases share an arm. Dispatch is by implementation while
/// `safety::effect_of` classifies by *name*, so wherever a group's spellings are
/// classified differently, the weakest one is the one an agent will reach for.
/// This is what lets `safety` close that gap without a second hand-written list.
///
/// Groups of one are omitted: they cannot disagree with anything.
pub fn alias_groups() -> Vec<Vec<&'static str>> {
    let mut by_impl: HashMap<String, Vec<&'static str>> = HashMap::new();
    for (name, idx) in BUILTIN_LOOKUP.iter() {
        by_impl.entry(format!("#{idx}")).or_default().push(name);
    }
    for (name, callee) in FALLBACK_BUILTINS {
        // A name the fast table also serves is dispatched there, so it belongs
        // with that implementation, not with the arm it shadows.
        if BUILTIN_LOOKUP.contains_key(name) {
            continue;
        }
        by_impl.entry((*callee).to_string()).or_default().push(name);
    }
    let mut out: Vec<Vec<&'static str>> = by_impl
        .into_values()
        .filter(|names| names.len() > 1)
        .map(|mut names| {
            names.sort_unstable();
            names.dedup();
            names
        })
        .filter(|names| names.len() > 1)
        .collect();
    out.sort();
    out
}

fn call_with_input_inner(
    name: &str,
    args: Vec<Value>,
    input: Option<Value>,
    env: &mut Env,
) -> Result<Value> {
    // Enforce policy before the builtin runs. `effect_of` only ever *described*
    // an operation's danger; this is where the description starts to constrain.
    // Builtins that guard themselves are skipped so one action is not admitted
    // twice.
    crate::safety::guard_dispatch(name, &args)?;

    // Capture what a mutating call is about to overwrite, so the session can be
    // rewound. This is the one place every builtin passes through, which is why
    // it is here rather than at ~300 call sites — the same reason this function
    // is already the single boundary for error structuring.
    //
    // Agent surface only, and a no-op for every non-mutating effect, so the
    // common path costs one `matches!`.
    let journal_mark = crate::journal::mark();
    crate::journal::record_before(name, crate::safety::effect_of(name), &args);

    // Try fast lookup first
    if let Some(result) = fast_builtin_lookup(name, args.clone(), input.clone(), env) {
        // A call that failed changed nothing, so it must leave nothing behind to
        // undo. Without this a write refused by the workspace jail still left an
        // entry, and `undo()` answered `complete: false` about an operation that
        // never ran.
        if result.is_err() {
            crate::journal::rollback_to(journal_mark);
        }
        return result;
    }

    // Fall back to the comprehensive match for functions not in fast lookup
    match name {
        // PowerShell-style cmdlets (not in fast lookup)
        "Get-Files" | "get-files" => bi_get_files(args, input),
        "Get-Content" | "get-content" => bi_get_content(args, input),
        "Select-Object" | "select-object" | "select" => bi_select_object(args, input),
        "Where-Object" | "where-object" => bi_where_object(args, input, env),
        "ForEach-Object" | "foreach-object" | "foreach" => bi_foreach_object(args, input, env),
        "Sort-Object" | "sort-object" => bi_sort_object(args, input),
        "Group-Object" | "group-object" | "group" | "group_by" => bi_group_object(args, input),
        "Measure-Object" | "measure-object" | "measure" => bi_measure_object(args, input),

        // Nushell-style data commands (not in fast lookup)
        "from-json" | "from_json" => bi_from_json(args, input),
        "to-json" | "to_json" => bi_to_json(args, input),
        "from-csv" | "from_csv" => bi_from_csv(args, input),
        "to-csv" | "to_csv" => bi_to_csv(args, input),
        "from-yaml" | "from_yaml" => bi_from_yaml(args, input),
        "to-yaml" | "to_yaml" => bi_to_yaml(args, input),
        "columns" => bi_columns(args, input),
        "describe" => bi_describe(args, input),

        // AI-enhanced commands (not in fast lookup)
        "ai" => bi_ai(args, input, env),
        "ai-suggest" | "suggest" => bi_ai_suggest(args, input, env),
        "ai-explain" | "explain" => bi_ai_explain(args, input, env),
        "ai-complete" | "complete" => bi_ai_complete(args, input, env),
        "ai-fix" | "fix" => bi_ai_fix(args, input, env),

        // AI/Agents (not in fast lookup)
        "agent" => bi_agent(args, input, env),
        "swarm" => bi_swarm(args, input, env),

        // AI Backend Detection (not in fast lookup)
        "ai_backends" | "ai-backends" => bi_ai_backends(args, input),
        "ai_detect" | "ai-detect" => bi_ai_detect(args, input),

        // AI Cost Tracking
        "ai_usage" | "ai-usage" => bi_ai_usage(),
        "ai_cost" | "ai-cost" => bi_ai_cost(),
        "ai_reset_usage" | "ai-reset-usage" => bi_ai_reset_usage(),

        // GPU Memory Management
        "ai_gpu_memory" | "ai-gpu-memory" => bi_ai_gpu_memory(),
        "ai_model_fits" | "ai-model-fits" => bi_ai_model_fits(args),

        // Provider Routing & Registry
        "ai_providers" | "ai-providers" => bi_ai_providers(),
        "ai_routes" | "ai-routes" => bi_ai_routes(),
        "ai_add_route" | "ai-add-route" => bi_ai_add_route(args),
        "ai_set_default" | "ai-set-default" => bi_ai_set_default(args),
        "ai_registry_stats" | "ai-registry-stats" => bi_ai_registry_stats(),
        "ai_set_load_balancing" | "ai-set-load-balancing" => bi_ai_set_load_balancing(args),
        "ai_load_balancing" | "ai-load-balancing" => bi_ai_load_balancing(),

        // Model Format Conversion
        "ai_convert_model" | "ai-convert-model" => bi_ai_convert_model(args),
        "ai_supported_conversions" | "ai-supported-conversions" => bi_ai_supported_conversions(),
        "ai_detect_format" | "ai-detect-format" => bi_ai_detect_format(args),

        // The NERVOSYS stack: routing, inference, model store
        "ai_gateway" | "ai-gateway" | "irongate" => bi_ai_gateway(),
        "vault_models" | "vault-models" => bi_vault_models(),
        "vault_conversions" | "vault-conversions" => bi_vault_conversions(),
        "vault_convert" | "vault-convert" => bi_vault_convert(args),

        // Local Inference
        "ai_local_backends" | "ai-local-backends" => bi_ai_local_backends(),
        "ai_local_load" | "ai-local-load" => bi_ai_local_load(args),
        "ai_local_generate" | "ai-local-generate" => bi_ai_local_generate(args),
        "ai_local_embed" | "ai-local-embed" => bi_ai_local_embed(args),
        "ai_local_unload" | "ai-local-unload" => bi_ai_local_unload(args),

        // Runtime Type Introspection
        "str" | "to_string" => bi_str(args, input),
        "typeof" | "type_of" => bi_typeof(args, input),
        "type_name" => bi_type_name(args, input),
        "type_fields" => bi_type_fields(args, input),
        "type_schema" => bi_type_schema(args, input),
        "is_type" => bi_is_type(args),

        // Ontology Export
        "ontology_json" => bi_ontology_json(),
        "ontology_jsonld" => bi_ontology_jsonld(),
        "ontology_owl" => bi_ontology_owl(),
        "ontology_shacl" => bi_ontology_shacl(),

        // Result handles (§ see crate::handles). Registered here rather than in
        // BUILTIN_LOOKUP because that table is index-coupled to BUILTIN_DISPATCH;
        // reachability is identical and the handle summary carries its own usage
        // hint, so discovery does not depend on the ontology listing.
        "handle" => bi_handle(args),
        "handles" => bi_handles(),
        "handle_drop" => bi_handle_drop(args),

        // Reversible sessions (see crate::journal).
        "undo" | "rewind" => bi_undo(args),
        "journal" => bi_journal(),
        "journal_clear" => bi_journal_clear(),

        _ => Err(crate::safety::unknown_builtin(name, did_you_mean(name))),
    }
}

// --------------- Helpers: type extraction ---------------

fn expect_array<'a>(name: &str, v: &'a Value) -> Result<&'a [Value]> {
    if let Value::Array(a) = v {
        Ok(a.as_slice())
    } else {
        Err(crate::safety::bad_arg(name, "an array", v.type_name()))
    }
}

fn expect_int(name: &str, v: &Value) -> Result<i64> {
    match v {
        Value::Int(n) => Ok(*n),
        Value::Float(f) if f.fract() == 0.0 => Ok(*f as i64),
        _ => Err(crate::safety::bad_arg(name, "an integer", v.type_name())),
    }
}

fn expect_string<'a>(name: &str, v: &'a Value) -> Result<&'a str> {
    if let Value::Str(s) = v {
        Ok(s.as_str())
    } else {
        Err(crate::safety::bad_arg(name, "a string", v.type_name()))
    }
}

fn need_lambda<'a>(v: &'a Value, name: &str) -> Result<&'a Lambda> {
    if let Value::Lambda(l) = v {
        Ok(l)
    } else {
        Err(crate::safety::bad_arg(name, "a lambda", v.type_name()))
    }
}

/// Fetch a required positional argument, or return a structured `E_BAD_ARG`
/// naming what was expected when it is missing — the arity counterpart to the
/// `expect_*` type helpers. Lets a builtin surface a catchable, branchable
/// missing-argument error instead of ad-hoc prose (or an index panic).
#[allow(dead_code)]
fn arg<'a>(builtin: &str, args: &'a [Value], idx: usize, expected: &str) -> Result<&'a Value> {
    args.get(idx)
        .ok_or_else(|| crate::safety::bad_arg(builtin, expected, "nothing"))
}

/// Extract the lowercased host from a URL, ignoring scheme, userinfo, port, and
/// path. Returns `None` if no authority is present.
fn url_host(url: &str) -> Option<String> {
    let after_scheme = url.split("://").nth(1)?;
    let authority = after_scheme.split(['/', '?', '#']).next()?;
    let host_port = authority.rsplit('@').next()?; // drop any userinfo@
    let host = host_port.split(':').next()?; // drop :port
    if host.is_empty() {
        None
    } else {
        Some(host.to_ascii_lowercase())
    }
}

/// Egress allowlist decision (pure). When `allow` is empty the allowlist is not
/// configured and egress is unchanged (returns `true`). Otherwise the URL's host
/// must equal an allowed entry or be a subdomain of one (`api.x.com` matches
/// `x.com`). A URL whose host can't be determined is denied under an allowlist.
fn egress_allowed(url: &str, allow: &str) -> bool {
    let allow = allow.trim();
    if allow.is_empty() {
        return true;
    }
    let host = match url_host(url) {
        Some(h) => h,
        None => return false,
    };
    allow
        .split(';')
        .map(|s| s.trim().to_ascii_lowercase())
        .filter(|s| !s.is_empty())
        .any(|entry| host == entry || host.ends_with(&format!(".{entry}")))
}

/// Gate a network-egress builtin through the safety guard with the `Network`
/// effect, so the resource governor (`AETHER_MAX_NET`) bounds egress and the
/// audit log records the request. `Network` is policy-`allow` in agent mode, so
/// this meters and audits rather than prompting.
///
/// Egress containment: when `AETHER_NET_ALLOW` is set (a `;`-separated host
/// allowlist), only those hosts and their subdomains may be reached — a control
/// against data exfiltration over an otherwise-open network channel. Unset → the
/// allowlist is inactive and behavior is unchanged.
fn guard_network(builtin: &str, url: &str) -> Result<()> {
    // Every one of these builtins hands the URL to `curl` or `wget` in a
    // positional slot, so a leading `-` is read as an option rather than an
    // address — and `curl -K<file>` reads a config file that can set `output`
    // and `url`, which turns a fetch into an arbitrary write. Checking it here
    // rather than at each of the fourteen call sites is the point: this is the
    // one door every network builtin already goes through, so a site added
    // later inherits the check instead of having to remember it. No legitimate
    // URL begins with `-`.
    crate::safety::reject_option_like(builtin, &[url.to_string()])?;

    let allow = std::env::var("AETHER_NET_ALLOW").unwrap_or_default();
    if !egress_allowed(url, &allow) {
        return Err(anyhow!(
            "E_EGRESS_DENIED: {} target host is not in the AETHER_NET_ALLOW egress allowlist: {}",
            builtin,
            url
        ));
    }
    crate::safety::guard(crate::safety::GuardCtx {
        builtin,
        effect: crate::safety::Effect::Network,
        what: "request",
        targets: vec![url.to_string()],
        blast_radius: serde_json::json!({ "url": url }),
        reversible: true,
        fs_paths: false,
    })?;
    Ok(())
}

/// Jail a caller-supplied path that the builtin is about to write, exactly as
/// `file_write` does — resolve it workspace-relative, then guard it as
/// `WriteLocal` with `fs_paths: true`.
///
/// A download has two effects and the effect taxonomy carries one. `web_download`,
/// `wget_download` and `web_upload_file` are classified `Network` by the `web_*`
/// prefix rule, they call [`guard_network`] on the URL, and they are in
/// `SELF_GUARDED` — so they look fully gated at every place a reader would check.
/// None of that touches the file. `guard_network` passes `fs_paths: false` and
/// `Effect::Network`, and the jail in `safety::guard` fires only when the effect
/// `is_filesystem()` *and* `fs_paths` is set, so the path went through no check
/// at all: `web.download <url> C:\outside\workspace\x` wrote there in agent mode
/// while `file.write` to the identical path was refused.
///
/// Returns the workspace-resolved path, so a relative path lands inside the jail
/// rather than beside the process's working directory — the same treatment
/// `file_write` gives it, and it also removes the option-injection question,
/// since a resolved absolute path cannot begin with `-`.
fn guard_local_write(builtin: &str, path: &str) -> Result<String> {
    let path = crate::safety::resolve_path_str(path);
    crate::safety::guard(crate::safety::GuardCtx {
        builtin,
        effect: crate::safety::Effect::WriteLocal,
        what: "write",
        targets: vec![path.clone()],
        blast_radius: serde_json::json!({ "path": path }),
        reversible: true,
        fs_paths: true,
    })?;
    Ok(path)
}

/// The `Destructive` counterpart of [`guard_local_write`], for a move.
///
/// `fs::rename` removes the source and can overwrite the destination, so it is
/// not the same promise as a write — `Destructive` is `approve` in agent mode
/// rather than `allow`. That is a real change in what an agent may do without
/// asking, and it is the honest one: `file_delete_lines` is already
/// `Destructive` for altering a file in place, and moving one over another is
/// not the smaller act.
fn guard_local_move(builtin: &str, path: &str) -> Result<String> {
    let path = crate::safety::resolve_path_str(path);
    crate::safety::guard(crate::safety::GuardCtx {
        builtin,
        effect: crate::safety::Effect::Destructive,
        what: "move",
        targets: vec![path.clone()],
        blast_radius: serde_json::json!({ "path": path }),
        reversible: false,
        fs_paths: true,
    })?;
    Ok(path)
}

// There is deliberately no read counterpart for `web_upload_file`. The jail in
// `safety::guard` fires only for `WriteLocal` and `Destructive` — `ReadLocal` is
// unjailed by design, and `file.read` of a path outside the workspace followed
// by `web.post` is already an allowed pair. Jailing the upload would be a policy
// change invented here rather than an inconsistency being corrected, so it is
// left as it is and named instead. `tests/network_write_jail.rs` pins the
// distinction so it stays a decision rather than an oversight.

#[cfg(test)]
mod egress_tests {
    use super::{egress_allowed, url_host};

    #[test]
    fn url_host_extraction() {
        assert_eq!(
            url_host("https://api.example.com/v1/x?q=1").as_deref(),
            Some("api.example.com")
        );
        assert_eq!(
            url_host("http://user:pw@Host.COM:8080/p").as_deref(),
            Some("host.com")
        );
        assert_eq!(url_host("not a url").as_deref(), None);
    }

    #[test]
    fn egress_allowlist_policy() {
        // Unset allowlist → unchanged (allow all).
        assert!(egress_allowed("https://anything.example/x", ""));
        // Exact host and subdomain match.
        assert!(egress_allowed("https://example.com/x", "example.com"));
        assert!(egress_allowed("https://api.example.com/x", "example.com"));
        assert!(egress_allowed(
            "https://a.b.example.com/x",
            "foo.org; example.com"
        ));
        // Non-allowed host denied; a lookalike suffix is NOT a subdomain match.
        assert!(!egress_allowed("https://evil.com/x", "example.com"));
        assert!(!egress_allowed("https://notexample.com/x", "example.com"));
        // Undeterminable host under an active allowlist → denied.
        assert!(!egress_allowed("garbage", "example.com"));
    }
}

/// Evaluate a lambda with N positional arguments by temporarily binding its `params`
/// in the environment, then `eval_expr` on its body. Restores env afterwards.
fn call_lambda(lam: &Lambda, args: &[Value], env: &mut Env) -> Result<Value> {
    // Finding 13: unbounded self-recursion used to overflow the stack and abort
    // the process, which no error handling could catch. The guard is held for
    // the whole call, so the depth unwinds even when an inner call returns Err.
    let _depth = crate::safety::enter_call()?;

    let params = &lam.params;
    if params.len() != args.len() {
        return Err(anyhow!(
            "lambda expected {} args, got {}",
            params.len(),
            args.len()
        ));
    }

    // Save and clear pipe input to prevent it from leaking into lambda evaluation
    let saved_pipe = env.input().cloned();
    env.set_input(None);

    // Save previous bindings
    let mut saved: Vec<(String, Option<Value>)> = Vec::with_capacity(params.len());
    for (i, p) in params.iter().enumerate() {
        let prev = env.get_var(p).cloned();
        saved.push((p.clone(), prev));
        env.set_var_unchecked(p, args[i].clone());
    }

    // Eval and restore
    let result = eval_expr(&lam.body, env);

    for (name, prev) in saved.into_iter().rev() {
        match prev {
            Some(v) => env.set_var_unchecked(&name, v),
            None => env.del_var(&name),
        }
    }

    // Restore pipe input
    match saved_pipe {
        Some(v) => env.set_input(Some(v)),
        None => env.set_input(None),
    }

    result
}

