/// List all available tools or filter by category/OS
/// Usage: tools() | tools("network") | tools("linux")
fn bi_tools(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let db = OSToolsDatabase::new();

    // Get filter if provided
    let filter = args.first().and_then(|v| {
        if let Value::Str(s) = v {
            Some(s.to_lowercase())
        } else {
            None
        }
    });

    let tools: Vec<&crate::os_tools::OSTool> = if let Some(ref f) = filter {
        // Check if it's an OS filter
        let os_filter = match f.as_str() {
            "linux" => Some(OperatingSystem::Linux),
            "bsd" | "freebsd" | "openbsd" | "netbsd" => Some(OperatingSystem::BSD),
            "macos" | "mac" | "darwin" => Some(OperatingSystem::MacOS),
            "windows" | "win" => Some(OperatingSystem::Windows),
            "ios" | "iphone" => Some(OperatingSystem::iOS),
            "android" => Some(OperatingSystem::Android),
            _ => None,
        };

        if let Some(os) = os_filter {
            db.get_tools_by_os(&os)
        } else {
            // Check if it's a category filter
            let cat_filter = match f.as_str() {
                "filesystem" | "file" | "files" => Some(ToolCategory::FileSystem),
                "text" | "textprocessing" => Some(ToolCategory::TextProcessing),
                "network" | "net" => Some(ToolCategory::NetworkTools),
                "system" | "systeminfo" | "sysinfo" => Some(ToolCategory::SystemInfo),
                "process" | "processes" => Some(ToolCategory::ProcessManagement),
                "archive" | "archives" | "compression" => Some(ToolCategory::Archives),
                "search" => Some(ToolCategory::SearchTools),
                "monitor" | "monitoring" => Some(ToolCategory::Monitoring),
                "dev" | "development" => Some(ToolCategory::Development),
                "media" => Some(ToolCategory::Media),
                "security" | "sec" => Some(ToolCategory::Security),
                "util" | "utilities" => Some(ToolCategory::Utilities),
                "web" | "webtools" => Some(ToolCategory::WebTools),
                "cyber" | "cybersecurity" | "pentest" => Some(ToolCategory::CyberSecurity),
                "recon" | "reconnaissance" | "osint" => Some(ToolCategory::Reconnaissance),
                "forensics" | "forensic" => Some(ToolCategory::Forensics),
                "crypto" | "cryptography" => Some(ToolCategory::Cryptography),
                _ => None,
            };

            if let Some(cat) = cat_filter {
                db.get_tools_by_category(&cat)
            } else {
                // Fallback to search
                db.search_tools(f)
            }
        }
    } else {
        // Return all tools
        db.tools.values().collect()
    };

    // Convert to Value::Array of Records
    let tool_values: Vec<Value> = tools
        .iter()
        .map(|t| {
            let mut rec = BTreeMap::new();
            rec.insert("name".to_string(), Value::Str(t.name.clone()));
            rec.insert("description".to_string(), Value::Str(t.description.clone()));
            rec.insert("command".to_string(), Value::Str(t.command.clone()));
            rec.insert(
                "category".to_string(),
                Value::Str(format!("{:?}", t.category)),
            );
            rec.insert(
                "safety".to_string(),
                Value::Str(format!("{:?}", t.safety_level)),
            );
            rec.insert("requires_admin".to_string(), Value::Bool(t.requires_admin));
            rec.insert(
                "supported_os".to_string(),
                Value::Array(
                    t.supported_os
                        .iter()
                        .map(|os| Value::Str(format!("{:?}", os)))
                        .collect(),
                ),
            );
            Value::Record(rec)
        })
        .collect();

    Ok(Value::Array(tool_values))
}

/// Get detailed information about a specific tool
/// Usage: tool_info("curl") | tool_info("nmap")
fn bi_tool_info(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let tool_name = args
        .first()
        .and_then(|v| {
            if let Value::Str(s) = v {
                Some(s.clone())
            } else {
                None
            }
        })
        .ok_or_else(|| crate::safety::arg_err("tool_info requires tool name as argument"))?;

    let db = OSToolsDatabase::new();
    let tool = db
        .get_tool(&tool_name)
        .ok_or_else(|| anyhow!("Tool '{}' not found", tool_name))?;

    let mut rec = BTreeMap::new();
    rec.insert("name".to_string(), Value::Str(tool.name.clone()));
    rec.insert(
        "description".to_string(),
        Value::Str(tool.description.clone()),
    );
    rec.insert("command".to_string(), Value::Str(tool.command.clone()));
    rec.insert(
        "category".to_string(),
        Value::Str(format!("{:?}", tool.category)),
    );
    rec.insert(
        "safety_level".to_string(),
        Value::Str(format!("{:?}", tool.safety_level)),
    );
    rec.insert(
        "requires_admin".to_string(),
        Value::Bool(tool.requires_admin),
    );
    rec.insert(
        "supported_os".to_string(),
        Value::Array(
            tool.supported_os
                .iter()
                .map(|os| Value::Str(format!("{:?}", os)))
                .collect(),
        ),
    );
    rec.insert(
        "common_args".to_string(),
        Value::Array(
            tool.common_args
                .iter()
                .map(|a| Value::Str(a.clone()))
                .collect(),
        ),
    );

    // Add examples
    let examples: Vec<Value> = tool
        .examples
        .iter()
        .map(|ex| {
            let mut ex_rec = BTreeMap::new();
            ex_rec.insert(
                "description".to_string(),
                Value::Str(ex.description.clone()),
            );
            ex_rec.insert("command".to_string(), Value::Str(ex.command.clone()));
            if let Some(ref output) = ex.expected_output {
                ex_rec.insert("expected_output".to_string(), Value::Str(output.clone()));
            }
            Value::Record(ex_rec)
        })
        .collect();
    rec.insert("examples".to_string(), Value::Array(examples));

    // Add parameters if available
    let params: Vec<Value> = tool
        .parameters
        .iter()
        .map(|p| {
            let mut p_rec = BTreeMap::new();
            p_rec.insert("name".to_string(), Value::Str(p.name.clone()));
            p_rec.insert("description".to_string(), Value::Str(p.description.clone()));
            p_rec.insert(
                "type".to_string(),
                Value::Str(format!("{:?}", p.param_type)),
            );
            p_rec.insert("required".to_string(), Value::Bool(p.required));
            if let Some(ref default) = p.default_value {
                p_rec.insert("default".to_string(), Value::Str(default.clone()));
            }
            if !p.enum_values.is_empty() {
                p_rec.insert(
                    "enum_values".to_string(),
                    Value::Array(
                        p.enum_values
                            .iter()
                            .map(|v| Value::Str(v.clone()))
                            .collect(),
                    ),
                );
            }
            Value::Record(p_rec)
        })
        .collect();
    rec.insert("parameters".to_string(), Value::Array(params));

    Ok(Value::Record(rec))
}

/// Get OpenAI-compatible function calling schemas for tools
/// Usage: tool_schema("curl") | tool_schema() for all | tool_schema("network") for category
fn bi_tool_schema(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let db = OSToolsDatabase::new();

    let filter = args.first().and_then(|v| {
        if let Value::Str(s) = v {
            Some(s.clone())
        } else {
            None
        }
    });

    let schemas = if let Some(ref name) = filter {
        // Check if it's a specific tool
        if let Some(tool) = db.get_tool(name) {
            vec![tool.to_openai_function_schema()]
        } else {
            // Check if it's a category
            let cat = match name.to_lowercase().as_str() {
                "network" | "net" => Some(ToolCategory::NetworkTools),
                "web" | "webtools" => Some(ToolCategory::WebTools),
                "cyber" | "cybersecurity" => Some(ToolCategory::CyberSecurity),
                "filesystem" | "file" => Some(ToolCategory::FileSystem),
                "security" | "sec" => Some(ToolCategory::Security),
                "forensics" => Some(ToolCategory::Forensics),
                "crypto" | "cryptography" => Some(ToolCategory::Cryptography),
                _ => None,
            };

            if let Some(c) = cat {
                db.get_category_schemas(&c)
            } else {
                // Search and return schemas for matching tools
                db.search_tools(name)
                    .iter()
                    .map(|t| t.to_openai_function_schema())
                    .collect()
            }
        }
    } else {
        // Return all schemas
        db.to_openai_function_schemas()
    };

    // Convert serde_json::Value to our Value
    let schema_values: Vec<Value> = schemas.into_iter().map(json_to_value).collect();

    Ok(Value::Array(schema_values))
}

/// Execute a tool with given arguments
/// Usage: tool_exec("ls", ["-la"]) | tool_exec("curl", ["-s", "https://example.com"])
fn bi_tool_exec(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    if args.is_empty() {
        return Err(anyhow!(
            "tool_exec requires: tool_name, [args], [allow_dangerous]"
        ));
    }

    let tool_name = if let Value::Str(s) = &args[0] {
        s.clone()
    } else {
        return Err(anyhow!(
            "tool_exec: first argument must be tool name string"
        ));
    };

    let tool_args: Vec<String> = if args.len() > 1 {
        if let Value::Array(arr) = &args[1] {
            arr.iter()
                .filter_map(|v| {
                    if let Value::Str(s) = v {
                        Some(s.clone())
                    } else {
                        None
                    }
                })
                .collect()
        } else if let Value::Str(s) = &args[1] {
            // Single argument as string
            vec![s.clone()]
        } else {
            vec![]
        }
    } else {
        vec![]
    };

    let allow_dangerous = if args.len() > 2 {
        if let Value::Bool(b) = &args[2] {
            *b
        } else {
            false
        }
    } else {
        false
    };

    crate::safety::guard_exec(
        "tool_exec",
        format!("{} {}", tool_name, tool_args.join(" ")),
    )?;
    let db = OSToolsDatabase::new();

    let result = execute_tool_safe(&db, &tool_name, &tool_args, allow_dangerous)
        .map_err(|e| anyhow!("Tool execution failed: {}", e))?;

    // Convert result to Value::Record
    let mut rec = BTreeMap::new();
    rec.insert("success".to_string(), Value::Bool(result.success));
    rec.insert("stdout".to_string(), Value::Str(result.stdout));
    rec.insert("stderr".to_string(), Value::Str(result.stderr));
    rec.insert(
        "exit_code".to_string(),
        result
            .exit_code
            .map(|c| Value::Int(c as i64))
            .unwrap_or(Value::Null),
    );
    rec.insert("tool_name".to_string(), Value::Str(result.tool_name));
    rec.insert(
        "command_executed".to_string(),
        Value::Str(result.command_executed),
    );
    rec.insert(
        "execution_time_ms".to_string(),
        Value::Int(result.execution_time_ms as i64),
    );

    Ok(Value::Record(rec))
}

/// Search for tools by keyword or description
/// Usage: tool_search("network") | tool_search("file copy")
fn bi_tool_search(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let query = args
        .first()
        .and_then(|v| {
            if let Value::Str(s) = v {
                Some(s.clone())
            } else {
                None
            }
        })
        .ok_or_else(|| crate::safety::arg_err("tool_search requires a search query"))?;

    let db = OSToolsDatabase::new();

    // Use get_recommended_tools for smart search
    let tools = db.get_recommended_tools(&query);

    // If no recommendations, fall back to regular search
    let tools = if tools.is_empty() {
        db.search_tools(&query)
    } else {
        tools
    };

    let tool_values: Vec<Value> = tools
        .iter()
        .map(|t| {
            let mut rec = BTreeMap::new();
            rec.insert("name".to_string(), Value::Str(t.name.clone()));
            rec.insert("description".to_string(), Value::Str(t.description.clone()));
            rec.insert("command".to_string(), Value::Str(t.command.clone()));
            rec.insert(
                "category".to_string(),
                Value::Str(format!("{:?}", t.category)),
            );
            rec.insert(
                "safety".to_string(),
                Value::Str(format!("{:?}", t.safety_level)),
            );
            Value::Record(rec)
        })
        .collect();

    Ok(Value::Array(tool_values))
}

// ===========================================================================
// Recursive Language Model (RLM) Builtins
// ===========================================================================

/// Run a recursive agent that can spawn subagents
/// Usage: rlm_agent("goal", ["tool1", "tool2"])
///        rlm_agent("goal", ["tools"], {max_depth: 3, max_agents: 20})
fn bi_rlm_agent(args: Vec<Value>, _input: Option<Value>, env: &mut Env) -> Result<Value> {
    if args.is_empty() {
        return Err(crate::safety::arg_err(
            "rlm_agent requires: goal, [tools], [config]",
        ));
    }

    let goal = if let Value::Str(s) = &args[0] {
        s.clone()
    } else {
        return Err(anyhow!("rlm_agent: first argument must be goal string"));
    };

    // Parse tool names
    let tool_names: Vec<String> = if args.len() > 1 {
        if let Value::Array(arr) = &args[1] {
            arr.iter()
                .filter_map(|v| {
                    if let Value::Str(s) = v {
                        Some(s.clone())
                    } else {
                        None
                    }
                })
                .collect()
        } else {
            vec![
                "ls".to_string(),
                "cat".to_string(),
                "grep".to_string(),
                "find".to_string(),
            ]
        }
    } else {
        vec![
            "ls".to_string(),
            "cat".to_string(),
            "grep".to_string(),
            "find".to_string(),
        ]
    };

    // Parse config if provided
    let config = if args.len() > 2 {
        parse_rlm_config(&args[2])?
    } else {
        RlmConfig::default()
    };

    // Check for model URI
    let model_uri = if args.len() > 3 {
        if let Value::Str(s) = &args[3] {
            Some(s.clone())
        } else {
            None
        }
    } else {
        None
    };

    let tool_refs: Vec<&str> = tool_names.iter().map(|s| s.as_str()).collect();

    let (result, stats) = if let Some(uri) = model_uri {
        run_recursive_with_model(&goal, &tool_refs, &uri, config, false, env)?
    } else {
        run_recursive(&goal, &tool_refs, config, false, env)?
    };

    // Return result with stats
    let mut rec = BTreeMap::new();
    rec.insert("output".to_string(), Value::Str(result));
    rec.insert(
        "total_agents".to_string(),
        Value::Int(stats.total_spawned as i64),
    );
    rec.insert(
        "active_agents".to_string(),
        Value::Int(stats.currently_active as i64),
    );
    rec.insert(
        "messages_sent".to_string(),
        Value::Int(stats.messages_sent as i64),
    );
    rec.insert(
        "elapsed_ms".to_string(),
        Value::Int(stats.elapsed_ms as i64),
    );

    Ok(Value::Record(rec))
}

/// Create an RLM configuration
/// Usage: rlm_config({max_depth: 5, max_agents: 50, timeout: 60})
fn bi_rlm_config(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let config = if args.is_empty() {
        RlmConfig::default()
    } else {
        parse_rlm_config(&args[0])?
    };

    let mut rec = BTreeMap::new();
    rec.insert("max_depth".to_string(), Value::Int(config.max_depth as i64));
    rec.insert(
        "max_agents".to_string(),
        Value::Int(config.max_agents as i64),
    );
    rec.insert(
        "agent_timeout_secs".to_string(),
        Value::Int(config.agent_timeout_secs as i64),
    );
    rec.insert(
        "max_concurrent_children".to_string(),
        Value::Int(config.max_concurrent_children as i64),
    );
    rec.insert(
        "trace_enabled".to_string(),
        Value::Bool(config.trace_enabled),
    );
    if let Some(uri) = config.subagent_model_uri {
        rec.insert("subagent_model_uri".to_string(), Value::Str(uri));
    }

    Ok(Value::Record(rec))
}

/// Get RLM statistics from the last run
/// Usage: rlm_stats()
fn bi_rlm_stats(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    // If input is a record with stats, format it nicely
    let stats_value = input.or_else(|| args.first().cloned());

    if let Some(Value::Record(rec)) = stats_value {
        // Already a stats record, return as-is
        return Ok(Value::Record(rec));
    }

    // Return default stats structure
    let mut rec = BTreeMap::new();
    rec.insert("total_spawned".to_string(), Value::Int(0));
    rec.insert("currently_active".to_string(), Value::Int(0));
    rec.insert("messages_sent".to_string(), Value::Int(0));
    rec.insert("elapsed_ms".to_string(), Value::Int(0));
    rec.insert("max_depth".to_string(), Value::Int(5));
    rec.insert("max_agents".to_string(), Value::Int(50));

    Ok(Value::Record(rec))
}

/// Spawn a subagent (used in agent context)
/// Usage: rlm_spawn("name", "goal", ["tools"])
fn bi_rlm_spawn(args: Vec<Value>, _input: Option<Value>, env: &mut Env) -> Result<Value> {
    if args.len() < 2 {
        return Err(crate::safety::arg_err(
            "rlm_spawn requires: name, goal, [tools]",
        ));
    }

    let name = if let Value::Str(s) = &args[0] {
        s.clone()
    } else {
        return Err(anyhow!("rlm_spawn: name must be a string"));
    };

    let goal = if let Value::Str(s) = &args[1] {
        s.clone()
    } else {
        return Err(anyhow!("rlm_spawn: goal must be a string"));
    };

    let tool_names: Vec<String> = if args.len() > 2 {
        if let Value::Array(arr) = &args[2] {
            arr.iter()
                .filter_map(|v| {
                    if let Value::Str(s) = v {
                        Some(s.clone())
                    } else {
                        None
                    }
                })
                .collect()
        } else {
            vec!["ls".to_string(), "cat".to_string()]
        }
    } else {
        vec!["ls".to_string(), "cat".to_string()]
    };

    // Run a single-depth recursive agent for the spawn
    let config = RlmConfig {
        max_depth: 1, // Single level only
        max_agents: 5,
        agent_timeout_secs: 30,
        ..Default::default()
    };

    // Spawning an autonomous sub-agent is an execution decision in its own right:
    // the individual tool calls it makes are guarded at their own chokepoints,
    // but *whether to start it at all* is the one point a policy can weigh.
    crate::safety::guard_exec("rlm_spawn", format!("spawn agent '{name}': {goal}"))?;
    let tool_refs: Vec<&str> = tool_names.iter().map(|s| s.as_str()).collect();
    let (result, stats) = run_recursive(&goal, &tool_refs, config, false, env)?;

    let mut rec = BTreeMap::new();
    rec.insert("name".to_string(), Value::Str(name));
    rec.insert("goal".to_string(), Value::Str(goal));
    rec.insert("output".to_string(), Value::Str(result));
    rec.insert("success".to_string(), Value::Bool(stats.total_spawned > 0));
    rec.insert(
        "agents_used".to_string(),
        Value::Int(stats.total_spawned as i64),
    );
    rec.insert(
        "elapsed_ms".to_string(),
        Value::Int(stats.elapsed_ms as i64),
    );

    Ok(Value::Record(rec))
}

/// Parse RLM configuration from a Value
fn parse_rlm_config(value: &Value) -> Result<RlmConfig> {
    let mut config = RlmConfig::default();

    if let Value::Record(rec) = value {
        if let Some(Value::Int(n)) = rec.get("max_depth") {
            config.max_depth = *n as usize;
        }
        if let Some(Value::Int(n)) = rec.get("max_agents") {
            config.max_agents = *n as usize;
        }
        if let Some(Value::Int(n)) = rec.get("timeout") {
            config.agent_timeout_secs = *n as u64;
        }
        if let Some(Value::Int(n)) = rec.get("agent_timeout_secs") {
            config.agent_timeout_secs = *n as u64;
        }
        if let Some(Value::Int(n)) = rec.get("max_concurrent_children") {
            config.max_concurrent_children = *n as usize;
        }
        if let Some(Value::Bool(b)) = rec.get("trace_enabled") {
            config.trace_enabled = *b;
        }
        if let Some(Value::Bool(b)) = rec.get("trace") {
            config.trace_enabled = *b;
        }
        if let Some(Value::Str(s)) = rec.get("model_uri") {
            config.subagent_model_uri = Some(s.clone());
        }
        if let Some(Value::Str(s)) = rec.get("subagent_model_uri") {
            config.subagent_model_uri = Some(s.clone());
        }
    }

    Ok(config)
}

// =============== New Aspirational Feature Builtins ===============

/// sh(args) - Execute a shell command directly
/// Usage: sh(["echo", "hello"]) or sh("echo hello")
///
/// SECURITY: Gated behind AETHER_ALLOW_SH=true environment variable.
fn bi_sh(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    use std::process::Command;

    // Security gate: require explicit opt-in
    validate_sh_allowed()?;

    if args.is_empty() {
        return Err(crate::safety::arg_err("sh requires command arguments"));
    }

    let (program, cmd_args): (String, Vec<String>) = match &args[0] {
        Value::Str(s) => {
            // Split string into program and args
            let parts: Vec<&str> = s.split_whitespace().collect();
            if parts.is_empty() {
                return Err(anyhow!("sh: empty command"));
            }
            (
                parts[0].to_string(),
                parts[1..].iter().map(|s| s.to_string()).collect(),
            )
        }
        Value::Array(arr) => {
            if arr.is_empty() {
                return Err(anyhow!("sh: empty command array"));
            }
            let program = match &arr[0] {
                Value::Str(s) => s.clone(),
                _ => return Err(anyhow!("sh: first argument must be program name string")),
            };
            let args: Result<Vec<String>> = arr[1..]
                .iter()
                .map(|v| match v {
                    Value::Str(s) => Ok(s.clone()),
                    Value::Int(n) => Ok(n.to_string()),
                    Value::Float(f) => Ok(f.to_string()),
                    _ => Err(anyhow!("sh: arguments must be strings or numbers")),
                })
                .collect();
            (program, args?)
        }
        _ => {
            return Err(crate::safety::arg_err(
                "sh requires string or array of strings",
            ))
        }
    };

    crate::safety::guard(crate::safety::GuardCtx {
        builtin: "sh",
        effect: crate::safety::Effect::Exec,
        what: "exec",
        targets: vec![format!("{} {}", program, cmd_args.join(" "))
            .trim()
            .to_string()],
        blast_radius: serde_json::json!({ "program": program, "args": cmd_args }),
        reversible: false,
        fs_paths: false,
    })?;

    let output = Command::new(&program)
        .args(&cmd_args)
        .output()
        .with_context(|| format!("sh: failed to execute '{}'", program))?;

    // Audit log the execution
    eprintln!(
        "[SECURITY] sh() executed: program='{}', args={:?}",
        program, cmd_args
    );

    let mut record = BTreeMap::new();
    record.insert(
        "stdout".to_string(),
        Value::Str(String::from_utf8_lossy(&output.stdout).to_string()),
    );
    record.insert(
        "stderr".to_string(),
        Value::Str(String::from_utf8_lossy(&output.stderr).to_string()),
    );
    record.insert("success".to_string(), Value::Bool(output.status.success()));
    record.insert(
        "exit_code".to_string(),
        Value::Int(output.status.code().unwrap_or(-1) as i64),
    );

    Ok(Value::Record(record))
}

// ─────────────────────────────────────────────────────────────────────────
// Output economy (token efficiency): AECON compact rendering + token estimate.
// See docs/AGENTIC_FIRST_DESIGN.md §6.2. The dominant agent output cost is
// homogeneous record arrays (ls, proc.list, docker.ps, db queries); AECON emits
// the field names ONCE as a header, then positional TSV rows — typically a
// large output-token saving over repeating keys per row (as JSON does).
// ─────────────────────────────────────────────────────────────────────────

/// Render one cell value compactly. Strings are emitted raw unless empty or
/// containing the TSV delimiters (tab/newline), in which case they're JSON
/// quoted; nested arrays/records are inlined as JSON to preserve row structure.
fn aecon_atom(v: &Value) -> String {
    match v {
        Value::Str(s) => {
            // A bare cell opening with `{` or `[` is reserved for a composite value
            // (record/array), which renders as JSON below. A *string* that happens to
            // start that way is JSON-quoted so the two can never be confused — the
            // same reservation `""` already provides for the empty string.
            if s.is_empty()
                || s.contains('\t')
                || s.contains('\n')
                || s.starts_with('{')
                || s.starts_with('[')
            {
                serde_json::to_string(s).unwrap_or_else(|_| format!("{:?}", s))
            } else {
                s.clone()
            }
        }
        Value::Uri(u) => u.clone(),
        Value::Int(n) => n.to_string(),
        Value::Float(f) => f.to_string(),
        Value::Bool(b) => b.to_string(),
        Value::Null => "null".to_string(),
        other => serde_json::to_string(&other.to_json()).unwrap_or_else(|_| "null".to_string()),
    }
}

/// Longest common character prefix shared by every string in `vals` (empty if
/// they share none). Char-aligned, so the returned `String`'s byte length is a
/// valid UTF-8 slice boundary in each input — used by `@prefix` factoring.
fn longest_common_str_prefix(vals: &[&str]) -> String {
    let mut prefix: Vec<char> = match vals.first() {
        Some(s) => s.chars().collect(),
        None => return String::new(),
    };
    for s in vals.iter().skip(1) {
        let mut n = 0usize;
        for (a, b) in prefix.iter().zip(s.chars()) {
            if *a == b {
                n += 1;
            } else {
                break;
            }
        }
        prefix.truncate(n);
        if prefix.is_empty() {
            break;
        }
    }
    prefix.into_iter().collect()
}

/// Longest common character *suffix* shared by every string in `vals` (empty if
/// they share none). Char-aligned, so subtracting the returned `String`'s byte
/// length from each input's length lands on a valid UTF-8 boundary — used by
/// `@suffix` factoring (shared extensions, domain tails, id suffixes).
fn longest_common_str_suffix(vals: &[&str]) -> String {
    let mut suffix: Vec<char> = match vals.first() {
        Some(s) => s.chars().rev().collect(),
        None => return String::new(),
    };
    for s in vals.iter().skip(1) {
        let mut n = 0usize;
        for (a, b) in suffix.iter().zip(s.chars().rev()) {
            if *a == b {
                n += 1;
            } else {
                break;
            }
        }
        suffix.truncate(n);
        if suffix.is_empty() {
            break;
        }
    }
    suffix.into_iter().rev().collect()
}

/// Depth limit for `@nest` flattening. Deep enough for real API payloads, shallow
/// enough that a pathological or cyclic-looking shape cannot blow the stack.
const AECON_NEST_DEPTH: usize = 4;

/// Flatten a record's nested-record fields into dotted columns, in place.
/// `user: {id, name}` becomes `user.id` / `user.name`, recursively to
/// `AECON_NEST_DEPTH`. Records are the only thing expanded — arrays and scalars stay
/// whole, so a cell is always an atom. Returns the *top-level* keys that were
/// expanded, which the `@nest` line names so decode knows which dotted columns to
/// rebuild (and which merely contain a literal dot).
fn aecon_flatten_into(
    src: &BTreeMap<String, Value>,
    out: &mut BTreeMap<String, Value>,
    prefix: &str,
    depth: usize,
) {
    for (k, v) in src {
        let name = if prefix.is_empty() {
            k.clone()
        } else {
            format!("{prefix}.{k}")
        };
        match v {
            // An empty record carries no columns, so flattening it would erase the
            // field entirely; keep it as an atom so the round-trip holds.
            Value::Record(inner) if depth < AECON_NEST_DEPTH && !inner.is_empty() => {
                aecon_flatten_into(inner, out, &name, depth + 1)
            }
            other => {
                out.insert(name, other.clone());
            }
        }
    }
}

/// Render a Value as AECON (Aether Compact Object Notation). Tabular values
/// (Table, or a homogeneous Array<Record>) become a `@aecon` header + TSV rows;
/// single records become `{k=v ...}`; scalar arrays become `[a,b,c]`; scalars
/// render as their literal. Deterministic (records are key-sorted BTreeMaps).
fn aecon_render(v: &Value) -> String {
    let (rows, header): (Vec<&BTreeMap<String, Value>>, Option<Vec<String>>) = match v {
        Value::Table(t) => {
            let h = if t.schema.is_empty() {
                None
            } else {
                Some(t.schema.clone())
            };
            (t.rows.iter().collect(), h)
        }
        Value::Array(arr)
            if !arr.is_empty() && arr.iter().all(|e| matches!(e, Value::Record(_))) =>
        {
            let rs = arr
                .iter()
                .filter_map(|e| match e {
                    Value::Record(m) => Some(m),
                    _ => None,
                })
                .collect();
            (rs, None)
        }
        _ => (Vec::new(), None),
    };

    // `@nest`: a record-valued cell would otherwise serialize as whole JSON on every
    // row — keys and all — which is precisely what this format exists to avoid, and
    // none of the column passes below can reach inside it. Expanding it into dotted
    // columns subjects each leaf to `@const`/`@dict`/`@prefix`/`@suffix`/`@same` like
    // any other column. A top-level key is expanded only when no existing column
    // already starts with `<key>.`, so a literal dotted key is never shadowed; the
    // `@nest` line names exactly what was expanded, so decode rebuilds only those.
    let mut nest_keys: Vec<String> = Vec::new();
    let flattened: Option<Vec<BTreeMap<String, Value>>> = if rows.len() >= 2 {
        let top: Vec<&String> = rows[0].keys().collect();
        let expandable: Vec<String> = rows[0]
            .iter()
            .filter(|(k, v)| match v {
                Value::Record(inner) => {
                    !inner.is_empty()
                        && !top.iter().any(|other| other.starts_with(&format!("{k}.")))
                }
                _ => false,
            })
            .map(|(k, _)| k.clone())
            .collect();
        // Every row must agree that the field is a record, or the flattened table is
        // ragged and the homogeneity check below would reject it anyway.
        let consistent = expandable.iter().all(|k| {
            rows.iter()
                .all(|r| matches!(r.get(k), Some(Value::Record(m)) if !m.is_empty()))
        });
        if expandable.is_empty() || !consistent {
            None
        } else {
            nest_keys = expandable;
            Some(
                rows.iter()
                    .map(|r| {
                        let mut out = BTreeMap::new();
                        for (k, v) in r.iter() {
                            if nest_keys.contains(k) {
                                if let Value::Record(inner) = v {
                                    aecon_flatten_into(inner, &mut out, k, 1);
                                    continue;
                                }
                            }
                            out.insert(k.clone(), v.clone());
                        }
                        out
                    })
                    .collect(),
            )
        }
    } else {
        None
    };
    let (rows, header) = match &flattened {
        // Flattening rewrites the column set, so a caller-supplied schema no longer
        // describes it; the expanded keys are the schema.
        Some(f) => (f.iter().collect::<Vec<_>>(), None),
        None => (rows, header),
    };

    if !rows.is_empty() {
        let keys: Vec<String> = header.unwrap_or_else(|| rows[0].keys().cloned().collect());
        let homogeneous = rows
            .iter()
            .all(|r| r.len() == keys.len() && keys.iter().all(|k| r.contains_key(k)));
        if homogeneous {
            // Constant-column factoring: columns whose value is identical across
            // ALL rows are emitted once in a `@const` line rather than repeated
            // per row — a real per-row token saving for the common case of
            // constant status/type/owner fields. (No constants → unchanged.)
            let (mut const_keys, mut var_keys): (Vec<String>, Vec<String>) =
                (Vec::new(), Vec::new());
            if rows.len() >= 2 {
                for k in &keys {
                    let first = rows[0].get(k);
                    if rows.iter().all(|r| r.get(k) == first) {
                        const_keys.push(k.clone());
                    } else {
                        var_keys.push(k.clone());
                    }
                }
            } else {
                var_keys = keys.clone();
            }
            // If every column is constant (identical rows), don't factor it all
            // away — keep them as the header so the row count stays observable.
            if var_keys.is_empty() {
                var_keys = keys.clone();
                const_keys.clear();
            }
            // Per-column encoding choice, decided by exact character cost.
            //
            // Every eligible STRING column has three candidate encodings — raw,
            // `@dict` (each distinct value once, referenced per row by integer
            // index), and `@prefix`/`@suffix` (shared leading and trailing runs
            // emitted once and stripped from every row) — and the cheapest wins.
            //
            // Costing them for real replaces two hand-tuned dictionary heuristics
            // (`d <= rows/2`, `avg_len >= 3`) that mis-fired in both directions:
            // they declined dictionaries that would have paid on long values, and
            // — because `@dict` was tried first and won by default — they took
            // columns that prefix/suffix factoring would have compressed further.
            // Costs are byte counts, so the choice is deterministic and
            // format-stable across builds (no tokenizer, no float).
            //
            // Eligibility is bare-safe strings only (non-empty, no tab/newline).
            // For `@prefix`/`@suffix` that keeps the stripped residue splittable;
            // for `@dict` it is a *correctness* requirement, because the distinct
            // values are emitted tab-separated on the `@dict` line — a value
            // containing a tab would silently corrupt its own dictionary.
            let mut dict_cols: std::collections::BTreeMap<String, Vec<String>> =
                std::collections::BTreeMap::new();
            let mut dict_index: std::collections::HashMap<
                String,
                std::collections::HashMap<String, usize>,
            > = std::collections::HashMap::new();
            let mut prefix_cols: std::collections::BTreeMap<String, String> =
                std::collections::BTreeMap::new();
            let mut suffix_cols: std::collections::BTreeMap<String, String> =
                std::collections::BTreeMap::new();
            for k in &var_keys {
                let mut vals: Vec<&str> = Vec::with_capacity(rows.len());
                let mut all_bare = true;
                for r in &rows {
                    match r.get(k) {
                        Some(Value::Str(s))
                            if !s.is_empty() && !s.contains('\t') && !s.contains('\n') =>
                        {
                            vals.push(s.as_str())
                        }
                        _ => {
                            all_bare = false;
                            break;
                        }
                    }
                }
                if !all_bare {
                    continue;
                }
                // `@same` runs after this choice and elides any cell equal to the
                // one above it, so a candidate must be costed as the later pass will
                // actually leave it — otherwise a dictionary can win on paper and
                // lose in the emitted output. Mirrors that pass's gate exactly,
                // including the shapes it declines.
                let same_eligible = rows.len() >= 4 && var_keys.len() >= 2;
                let after_same = |cells: &[&str]| -> usize {
                    let total: usize = cells.iter().map(|c| c.len()).sum();
                    if !same_eligible {
                        return total;
                    }
                    let elidable: usize = (1..cells.len())
                        .filter(|&i| cells[i] == cells[i - 1])
                        .map(|i| cells[i].len())
                        .sum();
                    if elidable > k.len() + 1 {
                        total - elidable + k.len() + 1
                    } else {
                        total
                    }
                };
                let raw_cost = after_same(&vals);

                // `@dict`: the distinct values once (tab-joined), plus one index
                // per row. Only meaningful when something actually repeats.
                let mut distinct: Vec<&str> = Vec::new();
                let mut first_seen: std::collections::HashMap<&str, usize> =
                    std::collections::HashMap::new();
                for v in &vals {
                    if !first_seen.contains_key(v) {
                        first_seen.insert(v, distinct.len());
                        distinct.push(v);
                    }
                }
                let dict_cost = if distinct.len() < vals.len() {
                    let indices: Vec<String> =
                        vals.iter().map(|v| first_seen[v].to_string()).collect();
                    let idx_refs: Vec<&str> = indices.iter().map(|s| s.as_str()).collect();
                    "\n@dict : ".len()
                        + k.len()
                        + distinct.iter().map(|d| d.len()).sum::<usize>()
                        + distinct.len().saturating_sub(1)
                        + after_same(&idx_refs)
                } else {
                    usize::MAX
                };

                // `@prefix`/`@suffix`: each run is included only if emitting it once
                // beats leaving it on every row. The suffix is searched in the
                // residue the prefix leaves, so the two can never overlap — even on
                // a value they consume entirely. `longest_common_str_prefix` is
                // char-aligned, so slicing at its byte length is a valid boundary.
                let n = vals.len();
                let lcp = longest_common_str_prefix(&vals);
                let p_line = "\n@prefix : ".len() + k.len() + lcp.len();
                let lcp = if !lcp.is_empty() && lcp.len() * n > p_line {
                    lcp
                } else {
                    String::new()
                };
                let residue: Vec<&str> = vals.iter().map(|s| &s[lcp.len()..]).collect();
                let lcs = longest_common_str_suffix(&residue);
                let s_line = "\n@suffix : ".len() + k.len() + lcs.len();
                let lcs = if !lcs.is_empty() && lcs.len() * n > s_line {
                    lcs
                } else {
                    String::new()
                };
                let ps_cost = if lcp.is_empty() && lcs.is_empty() {
                    usize::MAX
                } else {
                    residue.iter().map(|s| s.len() - lcs.len()).sum::<usize>()
                        + if lcp.is_empty() { 0 } else { p_line }
                        + if lcs.is_empty() { 0 } else { s_line }
                };

                // Cheapest wins; comparisons are strict and ordered, so ties fall to
                // the simpler encoding (raw, then prefix/suffix).
                if dict_cost < raw_cost && dict_cost <= ps_cost {
                    let idx: std::collections::HashMap<String, usize> = distinct
                        .iter()
                        .enumerate()
                        .map(|(i, v)| ((*v).to_string(), i))
                        .collect();
                    dict_index.insert(k.clone(), idx);
                    dict_cols.insert(k.clone(), distinct.iter().map(|s| s.to_string()).collect());
                } else if ps_cost < raw_cost {
                    if !lcp.is_empty() {
                        prefix_cols.insert(k.clone(), lcp);
                    }
                    if !lcs.is_empty() {
                        suffix_cols.insert(k.clone(), lcs);
                    }
                }
            }
            // Delta encoding for large-valued, slowly-varying INTEGER columns
            // (timestamps, sequential ids): row 0 carries the absolute value, each
            // later row carries the difference from the previous row; a `@delta:`
            // line names the affected columns. Gated to fire only where it's a real
            // *token* win — the raw values must be multi-token (avg ≥4 decimal
            // digits; small ints are one token regardless) and the deltas must be
            // well under half the raw character count. Deltas use i128 (no
            // overflow); never collides with `@dict` (string-only) as this is
            // integer-only.
            let mut delta_cols: std::collections::BTreeMap<String, Vec<String>> =
                std::collections::BTreeMap::new();
            if rows.len() >= 4 {
                for k in &var_keys {
                    if dict_index.contains_key(k) {
                        continue;
                    }
                    let mut vals: Vec<i64> = Vec::with_capacity(rows.len());
                    let mut all_int = true;
                    for r in &rows {
                        match r.get(k) {
                            Some(Value::Int(n)) => vals.push(*n),
                            _ => {
                                all_int = false;
                                break;
                            }
                        }
                    }
                    if !all_int {
                        continue;
                    }
                    let raw_chars: usize = vals.iter().map(|v| v.to_string().len()).sum();
                    if raw_chars / vals.len() < 4 {
                        continue; // raws aren't multi-token — a delta saves nothing
                    }
                    let mut cells: Vec<String> = Vec::with_capacity(vals.len());
                    cells.push(vals[0].to_string());
                    let mut delta_chars = cells[0].len();
                    for i in 1..vals.len() {
                        let s = ((vals[i] as i128) - (vals[i - 1] as i128)).to_string();
                        delta_chars += s.len();
                        cells.push(s);
                    }
                    if delta_chars * 2 < raw_chars {
                        delta_cols.insert(k.clone(), cells);
                    }
                }
            }
            // Type tags for lossless decode (reliability): emitted only for the
            // columns where the compact form would be misread by inference — a
            // string that looks like a number/bool/null, or an integral float.
            // Dict columns are always strings and delta columns always integers,
            // so they never need a tag; this costs tokens only on real ambiguity.
            let mut type_tags: std::collections::BTreeMap<String, char> =
                std::collections::BTreeMap::new();
            for k in const_keys.iter().chain(var_keys.iter()) {
                if dict_index.contains_key(k)
                    || delta_cols.contains_key(k)
                    || prefix_cols.contains_key(k)
                    || suffix_cols.contains_key(k)
                {
                    continue;
                }
                let vals: Vec<&Value> = if const_keys.contains(k) {
                    vec![rows[0].get(k).unwrap_or(&Value::Null)]
                } else {
                    rows.iter()
                        .map(|r| r.get(k).unwrap_or(&Value::Null))
                        .collect()
                };
                if let Some(tag) = aecon_type_tag(&vals) {
                    type_tags.insert(k.clone(), tag);
                }
            }
            // Render every cell once, so repeat-elision below can be gated on the
            // characters it actually saves rather than on a guess.
            let mut matrix: Vec<Vec<String>> = rows
                .iter()
                .enumerate()
                .map(|(ri, r)| {
                    var_keys
                        .iter()
                        .map(|k| {
                            if let Some(col) = delta_cols.get(k) {
                                return col[ri].clone();
                            }
                            let v = r.get(k).unwrap_or(&Value::Null);
                            if let Value::Str(s) = v {
                                let p = prefix_cols.get(k).map_or(0, |p| p.len());
                                let sfx = suffix_cols.get(k).map_or(0, |x| x.len());
                                if p > 0 || sfx > 0 {
                                    // bare-safe and non-overlapping by construction.
                                    return s[p..s.len() - sfx].to_string();
                                }
                            }
                            match (dict_index.get(k), v) {
                                (Some(idx), Value::Str(s)) => idx
                                    .get(s)
                                    .map(|i| i.to_string())
                                    .unwrap_or_else(|| aecon_atom(v)),
                                _ => aecon_atom(v),
                            }
                        })
                        .collect()
                })
                .collect();

            // Repeat elision (`@same`): in a column that runs in blocks — the shape
            // of any sorted or grouped result — a cell identical to the one above it
            // is emitted as *nothing*. An empty cell is an unambiguous sentinel
            // because a genuinely empty string renders JSON-quoted (`""`). `@const`
            // already covers columns constant across every row; this covers the runs
            // `@const` cannot see. Excluded: `@delta` columns (whose running sum owns
            // the previous-row state), `@prefix`/`@suffix` columns (whose stripped
            // residue may legitimately be empty), and single-column tables — where
            // an all-elided row renders as a bare empty line. The decoder now reads
            // interior blank lines as rows, so that last exclusion is defence in
            // depth rather than the sole guard; it costs nothing, because a
            // single-column run is already `@dict`'s case.
            let mut same_cols: Vec<String> = Vec::new();
            if rows.len() >= 4 && var_keys.len() >= 2 {
                for (ci, k) in var_keys.iter().enumerate() {
                    if delta_cols.contains_key(k)
                        || prefix_cols.contains_key(k)
                        || suffix_cols.contains_key(k)
                    {
                        continue;
                    }
                    let saved: usize = (1..matrix.len())
                        .filter(|&ri| matrix[ri][ci] == matrix[ri - 1][ci])
                        .map(|ri| matrix[ri][ci].len())
                        .sum();
                    // Naming a column costs a tab plus its name; the `\n@same `
                    // marker is charged once, to the set, below.
                    if saved > k.len() + 1 {
                        same_cols.push(k.clone());
                    }
                }
                // The line only pays if the set as a whole beats its own overhead.
                let set_saved: usize = same_cols
                    .iter()
                    .filter_map(|k| var_keys.iter().position(|v| v == k))
                    .map(|ci| {
                        (1..matrix.len())
                            .filter(|&ri| matrix[ri][ci] == matrix[ri - 1][ci])
                            .map(|ri| matrix[ri][ci].len())
                            .sum::<usize>()
                    })
                    .sum();
                let set_cost: usize =
                    "\n@same ".len() + same_cols.iter().map(|k| k.len() + 1).sum::<usize>();
                if set_saved <= set_cost {
                    same_cols.clear();
                }
                // Reverse order: each comparison must see the previous row's
                // *un-elided* cell.
                for ci in same_cols
                    .iter()
                    .filter_map(|k| var_keys.iter().position(|v| v == k))
                    .collect::<Vec<_>>()
                {
                    for ri in (1..matrix.len()).rev() {
                        if matrix[ri][ci] == matrix[ri - 1][ci] {
                            matrix[ri][ci].clear();
                        }
                    }
                }
            }

            // Tight format: a bare tab-separated header line (the column schema),
            // optional `@const` (factored constants), `@dict` (low-cardinality
            // columns), `@prefix`/`@suffix` (shared leading/trailing runs), `@same`
            // (repeat-elided columns), `@delta:` (delta-encoded numeric columns) and
            // `@type` (lossless type tags) metadata lines, then positional
            // tab-separated rows. No `@aecon rows=N cols=` prefix — the header is
            // self-describing and ~7 tokens cheaper per result than the verbose form.
            let mut out = var_keys.join("\t");
            if !nest_keys.is_empty() {
                out.push_str("\n@nest ");
                out.push_str(&nest_keys.join("\t"));
            }
            if !const_keys.is_empty() {
                let consts: Vec<String> = const_keys
                    .iter()
                    .map(|k| {
                        format!(
                            "{}={}",
                            k,
                            aecon_atom(rows[0].get(k).unwrap_or(&Value::Null))
                        )
                    })
                    .collect();
                out.push_str("\n@const ");
                out.push_str(&consts.join("\t"));
            }
            for (col, distinct) in &dict_cols {
                out.push_str(&format!("\n@dict {}: ", col));
                out.push_str(&distinct.join("\t"));
            }
            for (col, prefix) in &prefix_cols {
                out.push_str(&format!("\n@prefix {}: {}", col, prefix));
            }
            for (col, suffix) in &suffix_cols {
                out.push_str(&format!("\n@suffix {}: {}", col, suffix));
            }
            if !same_cols.is_empty() {
                out.push_str("\n@same ");
                out.push_str(&same_cols.join("\t"));
            }
            if !delta_cols.is_empty() {
                out.push_str("\n@delta: ");
                let names: Vec<&str> = delta_cols.keys().map(|s| s.as_str()).collect();
                out.push_str(&names.join("\t"));
            }
            if !type_tags.is_empty() {
                out.push_str("\n@type ");
                let tags: Vec<String> = type_tags
                    .iter()
                    .map(|(k, t)| format!("{}:{}", k, t))
                    .collect();
                out.push_str(&tags.join("\t"));
            }
            for cells in &matrix {
                out.push('\n');
                out.push_str(&cells.join("\t"));
            }
            return out;
        }
    }

    match v {
        Value::Record(m) => {
            let pairs: Vec<String> = m
                .iter()
                .map(|(k, val)| format!("{}={}", k, aecon_atom(val)))
                .collect();
            format!("{{{}}}", pairs.join(" "))
        }
        Value::Array(arr) => {
            let items: Vec<String> = arr.iter().map(aecon_atom).collect();
            format!("[{}]", items.join(","))
        }
        other => aecon_atom(other),
    }
}

/// Whether a bare string would be misread by `aecon_decode_atom` as a non-string
/// (number/bool/null) — i.e. it needs an explicit `s` type tag for lossless decode.
fn aecon_str_is_ambiguous(s: &str) -> bool {
    s == "null"
        || s == "true"
        || s == "false"
        || s.parse::<i64>().is_ok()
        || s.parse::<f64>().is_ok()
}

/// The type tag a column needs for lossless decode, or `None` if inference is
/// already exact. Only two cases are ambiguous in the compact form: an all-string
/// column containing a number/bool/null-looking value (`s`), and an all-float
/// column containing an integral value that renders without a `.` (`f`, which
/// inference would read back as `Int`). Mixed-variant columns return `None`
/// (best-effort — use `canonical` for those).
fn aecon_type_tag(vals: &[&Value]) -> Option<char> {
    if vals.is_empty() {
        return None;
    }
    if vals.iter().all(|v| matches!(v, Value::Str(_))) {
        let ambiguous = vals.iter().any(|v| match v {
            // Empty / tab / newline strings render JSON-quoted and decode exactly,
            // so only *bare* ambiguous strings need the tag.
            Value::Str(s) => {
                !s.is_empty() && !s.contains('\t') && !s.contains('\n') && aecon_str_is_ambiguous(s)
            }
            _ => false,
        });
        return ambiguous.then_some('s');
    }
    if vals.iter().all(|v| matches!(v, Value::Float(_))) {
        let ambiguous = vals.iter().any(|v| match v {
            Value::Float(f) => f.is_finite() && f.fract() == 0.0,
            _ => false,
        });
        return ambiguous.then_some('f');
    }
    None
}

/// Decode a cell honoring an explicit type tag (`s` → string, `f` → float),
/// falling back to inference when there is no tag.
fn aecon_decode_atom_typed(cell: &str, tag: Option<&char>) -> Value {
    match tag {
        Some('s') => {
            if cell.starts_with('"') {
                serde_json::from_str::<String>(cell)
                    .map(Value::Str)
                    .unwrap_or_else(|_| Value::Str(cell.to_string()))
            } else {
                Value::Str(cell.to_string())
            }
        }
        Some('f') => cell
            .parse::<f64>()
            .map(Value::Float)
            .unwrap_or_else(|_| aecon_decode_atom(cell)),
        _ => aecon_decode_atom(cell),
    }
}

/// Reverse `aecon_atom`: best-effort typed reconstruction of a single cell.
/// JSON-quoted cells (empty/tab/newline strings) are decoded exactly; otherwise
/// `null`/`true`/`false`/integer/float are recognized, falling back to a bare
/// string. The string↔number boundary is inferred (a string `"123"` decodes as
/// `Int`), exactly like CSV — for lossless typing use `canonical` (JSON).
fn aecon_decode_atom(cell: &str) -> Value {
    if cell.starts_with('"') {
        if let Ok(s) = serde_json::from_str::<String>(cell) {
            return Value::Str(s);
        }
    }
    // Composite values render as bare JSON, and `aecon_atom` quotes any *string*
    // that would open the same way, so a leading `{`/`[` unambiguously means one.
    if cell.starts_with('{') || cell.starts_with('[') {
        if let Ok(j) = serde_json::from_str::<serde_json::Value>(cell) {
            return Value::from_json(&j);
        }
    }
    match cell {
        "null" => return Value::Null,
        "true" => return Value::Bool(true),
        "false" => return Value::Bool(false),
        _ => {}
    }
    if let Ok(i) = cell.parse::<i64>() {
        return Value::Int(i);
    }
    if let Ok(f) = cell.parse::<f64>() {
        return Value::Float(f);
    }
    Value::Str(cell.to_string())
}

/// Rebuild the nested records that `@nest` flattened away. Only columns whose first
/// dotted segment is named in `nest` are rebuilt — every other key is kept verbatim,
/// so a column that merely *contains* a dot is never mistaken for a nested field.
fn aecon_unflatten(
    flat: BTreeMap<String, Value>,
    nest: &std::collections::HashSet<String>,
) -> BTreeMap<String, Value> {
    let mut out: BTreeMap<String, Value> = BTreeMap::new();
    for (k, v) in flat {
        let head = k.split('.').next().unwrap_or("");
        if !nest.contains(head) || !k.contains('.') {
            out.insert(k, v);
            continue;
        }
        let segments: Vec<&str> = k.split('.').collect();
        // Walk down, creating records as needed, and place the leaf at the bottom.
        let mut cursor = &mut out;
        for seg in &segments[..segments.len() - 1] {
            let entry = cursor
                .entry((*seg).to_string())
                .or_insert_with(|| Value::Record(BTreeMap::new()));
            if !matches!(entry, Value::Record(_)) {
                *entry = Value::Record(BTreeMap::new());
            }
            cursor = match entry {
                Value::Record(m) => m,
                _ => unreachable!("just forced to a record"),
            };
        }
        cursor.insert(segments[segments.len() - 1].to_string(), v);
    }
    out
}

/// Decode the tabular AECON form (header + optional `@const`/`@dict`/`@delta`/
/// `@prefix`/`@suffix`/`@same`/`@type` metadata lines + positional rows) back to an
/// `Array<Record>`.
/// Inverse of the tabular branch of `aecon_render`: `@const` columns are restored to
/// every row, `@dict` indices are resolved to their string values, `@delta` columns
/// are reconstructed by running sum, `@prefix`/`@suffix` columns get their shared
/// runs re-attached, `@same` columns resolve an empty cell to the row above, and
/// `@type` tags force the exact type of columns
/// the compact form would otherwise infer wrongly (numeric-looking strings,
/// integral floats) — making the round-trip lossless. Returns the parsed array;
/// non-tabular input (a single `{k=v}` record, a scalar array, or a bare scalar)
/// is returned as a best-effort single value.
fn aecon_decode(s: &str) -> Value {
    let lines: Vec<&str> = s.split('\n').collect();
    if lines.is_empty() {
        return Value::Null;
    }
    let header = lines[0];
    // Non-tabular fallbacks: a single record / scalar array / bare scalar.
    if !header.contains('\t') && (header.starts_with('{') || header.starts_with('[')) {
        return aecon_decode_atom(header);
    }
    let var_keys: Vec<String> = header.split('\t').map(|s| s.to_string()).collect();

    // `@const` is decoded *after* the metadata loop because `@type` (which can
    // correct a const's inferred type) is emitted after it; collect the raw
    // key=value pairs first, then apply tags.
    let mut const_raw: Vec<(String, String)> = Vec::new();
    let mut dicts: std::collections::HashMap<String, Vec<String>> =
        std::collections::HashMap::new();
    let mut prefixes: std::collections::HashMap<String, String> = std::collections::HashMap::new();
    let mut suffixes: std::collections::HashMap<String, String> = std::collections::HashMap::new();
    let mut same_set: std::collections::HashSet<String> = std::collections::HashSet::new();
    let mut nest_set: std::collections::HashSet<String> = std::collections::HashSet::new();
    let mut delta_set: std::collections::HashSet<String> = std::collections::HashSet::new();
    let mut type_tags: std::collections::HashMap<String, char> = std::collections::HashMap::new();
    let mut row_start = 1;
    for (i, line) in lines.iter().enumerate().skip(1) {
        if let Some(rest) = line.strip_prefix("@const ") {
            for kv in rest.split('\t') {
                if let Some((k, v)) = kv.split_once('=') {
                    const_raw.push((k.to_string(), v.to_string()));
                }
            }
        } else if let Some(rest) = line.strip_prefix("@dict ") {
            if let Some((col, vals)) = rest.split_once(": ") {
                dicts.insert(
                    col.to_string(),
                    vals.split('\t').map(|s| s.to_string()).collect(),
                );
            }
        } else if let Some(rest) = line.strip_prefix("@prefix ") {
            if let Some((col, p)) = rest.split_once(": ") {
                prefixes.insert(col.to_string(), p.to_string());
            }
        } else if let Some(rest) = line.strip_prefix("@suffix ") {
            if let Some((col, p)) = rest.split_once(": ") {
                suffixes.insert(col.to_string(), p.to_string());
            }
        } else if let Some(rest) = line.strip_prefix("@same ") {
            for c in rest.split('\t') {
                same_set.insert(c.to_string());
            }
        } else if let Some(rest) = line.strip_prefix("@nest ") {
            for c in rest.split('\t') {
                nest_set.insert(c.to_string());
            }
        } else if let Some(rest) = line.strip_prefix("@delta: ") {
            for c in rest.split('\t') {
                delta_set.insert(c.to_string());
            }
        } else if let Some(rest) = line.strip_prefix("@type ") {
            for spec in rest.split('\t') {
                if let Some((col, tag)) = spec.rsplit_once(':') {
                    if let Some(c) = tag.chars().next() {
                        type_tags.insert(col.to_string(), c);
                    }
                }
            }
        } else {
            row_start = i;
            break;
        }
        row_start = i + 1;
    }
    let consts: Vec<(String, Value)> = const_raw
        .iter()
        .map(|(k, v)| (k.clone(), aecon_decode_atom_typed(v, type_tags.get(k))))
        .collect();

    // Running absolute value per delta column, advanced as rows are read in order.
    let mut delta_run: std::collections::HashMap<String, i128> = std::collections::HashMap::new();
    // Last emitted value per `@same` column, so an elided (empty) cell resolves to
    // the row above it.
    let mut prev_same: std::collections::HashMap<String, Value> = std::collections::HashMap::new();
    let mut out_rows: Vec<Value> = Vec::new();
    // Trailing blank lines are formatting; an *interior* blank line is a real row
    // whose every cell was factored away — a single-column table whose value equals
    // its `@prefix`+`@suffix` renders exactly that way. Trim the former so the
    // latter is not silently dropped.
    let mut row_end = lines.len();
    while row_end > row_start && lines[row_end - 1].is_empty() {
        row_end -= 1;
    }
    for line in &lines[row_start..row_end] {
        let cells: Vec<&str> = line.split('\t').collect();
        let mut m = BTreeMap::new();
        for (ci, k) in var_keys.iter().enumerate() {
            let cell = cells.get(ci).copied().unwrap_or("");
            let val = if same_set.contains(k) && cell.is_empty() && prev_same.contains_key(k) {
                prev_same[k].clone()
            } else if delta_set.contains(k) {
                let n: i128 = cell.parse().unwrap_or(0);
                let abs = match delta_run.get(k) {
                    Some(prev) => prev + n, // later rows carry the difference
                    None => n,              // row 0 carries the absolute value
                };
                delta_run.insert(k.clone(), abs);
                Value::Int(abs as i64)
            } else if let Some(values) = dicts.get(k) {
                match cell.parse::<usize>().ok().and_then(|i| values.get(i)) {
                    Some(s) => Value::Str(s.clone()),
                    None => aecon_decode_atom(cell),
                }
            } else if prefixes.contains_key(k) || suffixes.contains_key(k) {
                let prefix = prefixes.get(k).map(String::as_str).unwrap_or("");
                let suffix = suffixes.get(k).map(String::as_str).unwrap_or("");
                Value::Str(format!("{prefix}{cell}{suffix}"))
            } else {
                aecon_decode_atom_typed(cell, type_tags.get(k))
            };
            if same_set.contains(k) {
                prev_same.insert(k.clone(), val.clone());
            }
            m.insert(k.clone(), val);
        }
        for (k, v) in &consts {
            m.insert(k.clone(), v.clone());
        }
        out_rows.push(Value::Record(if nest_set.is_empty() {
            m
        } else {
            aecon_unflatten(m, &nest_set)
        }));
    }
    Value::Array(out_rows)
}

/// Token count used by the token-economy builtins (`tokens`/`budget`/`digest`)
/// and the Agent API accounting. With `--features real-tokens` this is the
/// **real GPT-4 cl100k BPE** (vocab embedded in `tiktoken-rs`); otherwise a
/// labeled heuristic (alphanumeric run ≈ ceil(len/4) tokens; each symbol ≈ 1).
#[cfg(feature = "real-tokens")]
pub fn est_token_count(s: &str) -> usize {
    use std::sync::OnceLock;
    static BPE: OnceLock<tiktoken_rs::CoreBPE> = OnceLock::new();
    let bpe = BPE.get_or_init(|| tiktoken_rs::cl100k_base().expect("load cl100k_base"));
    bpe.encode_with_special_tokens(s).len()
}

#[cfg(not(feature = "real-tokens"))]
pub fn est_token_count(s: &str) -> usize {
    let mut toks = 0usize;
    let mut chars = s.chars().peekable();
    while let Some(c) = chars.next() {
        if c.is_whitespace() {
            continue;
        }
        if c.is_alphanumeric() || c == '_' {
            let mut len = 1usize;
            while let Some(&n) = chars.peek() {
                if n.is_alphanumeric() || n == '_' {
                    len += 1;
                    chars.next();
                } else {
                    break;
                }
            }
            toks += len.div_ceil(4).max(1);
        } else {
            toks += 1;
        }
    }
    toks
}

/// aecon(value?) - Render a value (argument or piped input) as compact AECON
/// text. Saves output tokens on homogeneous record arrays by emitting keys once.
fn bi_aecon(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let v = args.into_iter().next().or(input).ok_or_else(|| {
        crate::safety::bad_arg("aecon", "a value (argument or piped input)", "nothing")
    })?;
    Ok(Value::Str(aecon_render(&v)))
}

/// aecon_decode(text?) - Parse tabular AECON text (argument or piped input) back
/// into an `Array<Record>`, reversing `@const`/`@dict`/`@delta`/`@prefix`/`@suffix`/
/// `@same` factoring.
/// The inverse of `aecon` for homogeneous tables; the string↔number boundary is
/// inferred (use `canonical` for lossless typing).
fn bi_aecon_decode(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let v = args.into_iter().next().or(input).ok_or_else(|| {
        crate::safety::bad_arg(
            "aecon_decode",
            "AECON text (argument or piped input)",
            "nothing",
        )
    })?;
    let s = match v {
        Value::Str(s) => s,
        other => {
            return Err(crate::safety::bad_arg(
                "aecon_decode",
                "a String of AECON text",
                &format!("{:?}", other),
            ))
        }
    };
    Ok(aecon_decode(&s))
}

/// tokens(value?) - Estimate the token count of a value's rendered form (its
/// string content if a String, else its display form). Pair with `aecon` to
/// compare output costs, e.g. `tokens(v)` vs `tokens(aecon(v))`.
fn bi_tokens(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let v = args.into_iter().next().or(input).ok_or_else(|| {
        crate::safety::bad_arg("tokens", "a value (argument or piped input)", "nothing")
    })?;
    let s = match &v {
        Value::Str(s) => s.clone(),
        other => other.to_display_string(),
    };
    Ok(Value::Int(est_token_count(&s) as i64))
}

/// A compact structural type descriptor for a value: a Record maps each key to
/// its type name; an Array reports its element type; a scalar reports its type.
/// Lets `digest` convey shape in a handful of tokens.
fn value_shape(v: &Value) -> Value {
    match v {
        Value::Record(m) => Value::Record(
            m.iter()
                .map(|(k, val)| (k.clone(), Value::Str(val.type_name().to_string())))
                .collect(),
        ),
        Value::Array(a) => Value::Str(format!(
            "Array<{}>",
            a.first().map(|e| e.type_name()).unwrap_or("Any")
        )),
        other => Value::Str(other.type_name().to_string()),
    }
}

/// digest(value?) - A constant-token structural summary of a value: its kind,
/// size, element/field shape, a 2-element sample, and the token cost of the full
/// value (default render vs compact AECON). Lets an agent understand a large
/// result's shape and size cheaply, then decide whether to page (`budget`),
/// compact (`aecon`), or skip it — maximal information per token.
fn bi_digest(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let v = args.into_iter().next().or(input).ok_or_else(|| {
        crate::safety::bad_arg("digest", "a value (argument or piped input)", "nothing")
    })?;
    let mut r = BTreeMap::new();
    match &v {
        Value::Array(a) => {
            r.insert("kind".to_string(), Value::Str("array".to_string()));
            r.insert("len".to_string(), Value::Int(a.len() as i64));
            if let Some(first) = a.first() {
                r.insert("element".to_string(), value_shape(first));
            }
            r.insert(
                "sample".to_string(),
                Value::Array(a.iter().take(2).cloned().collect()),
            );
        }
        Value::Table(t) => {
            r.insert("kind".to_string(), Value::Str("table".to_string()));
            r.insert("rows".to_string(), Value::Int(t.rows.len() as i64));
            r.insert(
                "cols".to_string(),
                Value::Array(t.schema.iter().map(|c| Value::Str(c.clone())).collect()),
            );
            r.insert(
                "sample".to_string(),
                Value::Array(
                    t.rows
                        .iter()
                        .take(2)
                        .map(|row| Value::Record(row.clone()))
                        .collect(),
                ),
            );
        }
        Value::Record(m) => {
            r.insert("kind".to_string(), Value::Str("record".to_string()));
            r.insert("keys".to_string(), Value::Int(m.len() as i64));
            r.insert("shape".to_string(), value_shape(&v));
        }
        Value::Str(s) => {
            r.insert("kind".to_string(), Value::Str("string".to_string()));
            r.insert("len".to_string(), Value::Int(s.chars().count() as i64));
            r.insert(
                "preview".to_string(),
                Value::Str(s.chars().take(60).collect::<String>()),
            );
        }
        other => {
            r.insert(
                "kind".to_string(),
                Value::Str(other.type_name().to_string()),
            );
            r.insert("value".to_string(), other.clone());
        }
    }
    r.insert(
        "full_tokens".to_string(),
        Value::Int(est_token_count(&v.to_display_string()) as i64),
    );
    r.insert(
        "compact_tokens".to_string(),
        Value::Int(est_token_count(&aecon_render(&v)) as i64),
    );
    Ok(Value::Record(r))
}

/// Project a record to only the named fields (in the given order, skipping
/// fields that don't exist).
fn pick_record(m: &BTreeMap<String, Value>, fields: &[String]) -> Value {
    let mut out = BTreeMap::new();
    for f in fields {
        if let Some(v) = m.get(f) {
            out.insert(f.clone(), v.clone());
        }
    }
    Value::Record(out)
}

/// pick(value?, fields...) - Source-side projection: keep only the named fields
/// of each record (an array of records, a single record, or a table), dropping
/// the rest *before* rendering. The biggest output-token saver — pair with
/// `aecon`: `data | pick("name", "size") | aecon`. With piped input the args are
/// the field names; otherwise the first arg is the value.
fn bi_pick(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let collect_fields = |vals: &[Value]| -> Vec<String> {
        vals.iter()
            .filter_map(|a| match a {
                Value::Str(s) => Some(s.clone()),
                _ => None,
            })
            .collect()
    };
    let (value, fields) = if let Some(inp) = input {
        (inp, collect_fields(&args))
    } else {
        let value = args
            .first()
            .cloned()
            .ok_or_else(|| crate::safety::bad_arg("pick", "value, fields: String...", "nothing"))?;
        (value, collect_fields(&args[1..]))
    };
    if fields.is_empty() {
        return Err(crate::safety::bad_arg(
            "pick",
            "at least one field name",
            "none",
        ));
    }
    let result = match value {
        Value::Array(a) => Value::Array(
            a.iter()
                .map(|e| match e {
                    Value::Record(m) => pick_record(m, &fields),
                    other => other.clone(),
                })
                .collect(),
        ),
        Value::Record(m) => pick_record(&m, &fields),
        Value::Table(t) => Value::Array(t.rows.iter().map(|m| pick_record(m, &fields)).collect()),
        other => other,
    };
    Ok(result)
}

/// JSON-escape and quote a string (delegates to serde_json for correctness).
fn json_quote(s: &str) -> String {
    serde_json::to_string(s).unwrap_or_else(|_| format!("{:?}", s))
}

/// Write a Value as canonical JSON: deterministic and byte-stable across
/// platforms/locale. Record keys are emitted in sorted order (Records are
/// BTreeMaps); floats use Rust's shortest round-trip, locale-independent
/// formatting; non-finite floats and non-serializable values (lambdas/futures)
/// become explicit sentinels so output never varies or fails.
fn canonical_write(v: &Value, out: &mut String) {
    match v {
        Value::Null => out.push_str("null"),
        Value::Bool(b) => out.push_str(if *b { "true" } else { "false" }),
        Value::Int(n) => out.push_str(&n.to_string()),
        Value::Float(f) => {
            if f.is_finite() {
                out.push_str(&format!("{}", f));
            } else {
                out.push_str("null"); // NaN/Inf are not representable in JSON
            }
        }
        Value::Str(s) | Value::Uri(s) => out.push_str(&json_quote(s)),
        Value::Array(a) => {
            out.push('[');
            for (i, e) in a.iter().enumerate() {
                if i > 0 {
                    out.push(',');
                }
                canonical_write(e, out);
            }
            out.push(']');
        }
        Value::Record(m) => {
            out.push('{');
            for (i, (k, val)) in m.iter().enumerate() {
                if i > 0 {
                    out.push(',');
                }
                out.push_str(&json_quote(k));
                out.push(':');
                canonical_write(val, out);
            }
            out.push('}');
        }
        Value::Table(t) => {
            // Canonical object with keys in sorted order: "rows" then "schema".
            out.push_str("{\"rows\":[");
            for (i, r) in t.rows.iter().enumerate() {
                if i > 0 {
                    out.push(',');
                }
                out.push('{');
                for (j, (k, val)) in r.iter().enumerate() {
                    if j > 0 {
                        out.push(',');
                    }
                    out.push_str(&json_quote(k));
                    out.push(':');
                    canonical_write(val, out);
                }
                out.push('}');
            }
            out.push_str("],\"schema\":[");
            for (i, c) in t.schema.iter().enumerate() {
                if i > 0 {
                    out.push(',');
                }
                out.push_str(&json_quote(c));
            }
            out.push_str("]}");
        }
        Value::Lambda(_) | Value::AsyncLambda(_) | Value::Future(_) => out.push_str("null"),
        Value::Error(msg) => {
            out.push_str("{\"error\":");
            out.push_str(&json_quote(msg));
            out.push('}');
        }
        Value::Builtin(b) => {
            out.push_str("{\"builtin\":");
            out.push_str(&json_quote(&b.name));
            out.push('}');
        }
    }
}

fn canonical_render(v: &Value) -> String {
    let mut out = String::new();
    canonical_write(v, &mut out);
    out
}

/// canonical(value?) - Render a value as canonical JSON: deterministic and
/// byte-identical for equal values across OS/locale (sorted keys, shortest
/// round-trip floats, explicit null for non-finite/non-serializable). The
/// lossless counterpart to `aecon`; the basis for reproducible output/diffs.
fn bi_canonical(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let v = args.into_iter().next().or(input).ok_or_else(|| {
        crate::safety::bad_arg("canonical", "a value (argument or piped input)", "nothing")
    })?;
    Ok(Value::Str(canonical_render(&v)))
}

/// Budget a rendered string to `max` estimated tokens, never silently lossy:
/// over budget → keep a prefix and append an explicit elision marker.
fn budget_string_record(s: &str, max: usize) -> Value {
    let total = est_token_count(s);
    let mut r = BTreeMap::new();
    if total <= max {
        r.insert("page".to_string(), Value::Str(s.to_string()));
        r.insert("truncated".to_string(), Value::Bool(false));
        r.insert("page_tokens".to_string(), Value::Int(total as i64));
        r.insert("total_tokens".to_string(), Value::Int(total as i64));
        r.insert("elided_chars".to_string(), Value::Int(0));
    } else {
        let keep = max.saturating_mul(4); // ~4 chars/token heuristic
        let prefix: String = s.chars().take(keep).collect();
        let elided = s.chars().count().saturating_sub(keep);
        let page = format!("{}…({} more chars elided)", prefix, elided);
        let page_tokens = est_token_count(&page);
        r.insert("page".to_string(), Value::Str(page));
        r.insert("truncated".to_string(), Value::Bool(true));
        r.insert("page_tokens".to_string(), Value::Int(page_tokens as i64));
        r.insert("total_tokens".to_string(), Value::Int(total as i64));
        r.insert("elided_chars".to_string(), Value::Int(elided as i64));
    }
    Value::Record(r)
}

/// budget(value?, max_tokens, cursor?) - Render a value to fit within an
/// estimated token budget, never silently lossy. For arrays/tables it returns a
/// page of rows starting at `cursor` plus paging metadata (`next_cursor`,
/// `elided`, `total`, `page_tokens`); for other values it truncates the AECON
/// rendering with an explicit elision marker. With piped input the args are
/// `(max_tokens, cursor?)`; otherwise `(value, max_tokens, cursor?)`.
fn bi_budget(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    // Resolve (value, max, cursor) depending on whether input is piped.
    let (value, max_v, cursor_v) = if let Some(inp) = input {
        (inp, args.first().cloned(), args.get(1).cloned())
    } else {
        let v = args
            .first()
            .cloned()
            .ok_or_else(|| crate::safety::bad_arg("budget", "value, max_tokens: Int", "nothing"))?;
        (v, args.get(1).cloned(), args.get(2).cloned())
    };
    let max = match max_v {
        Some(Value::Int(n)) if n > 0 => n as usize,
        other => {
            return Err(crate::safety::bad_arg(
                "budget",
                "max_tokens: positive Int",
                other.as_ref().map(|v| v.type_name()).unwrap_or("nothing"),
            ))
        }
    };
    let cursor = match cursor_v {
        Some(Value::Int(n)) if n >= 0 => n as usize,
        _ => 0,
    };

    Ok(budget_value(&value, max, cursor))
}

/// Core of `budget`: render `value` to fit ~`max` estimated tokens, paging
/// arrays/tables from `cursor` (with metadata) and truncating other values'
/// AECON rendering losslessly. Public so the REPL can apply `AE_TOKEN_BUDGET`.
pub fn budget_value(value: &Value, max: usize, cursor: usize) -> Value {
    let rows: Vec<Value> = match value {
        Value::Table(t) => t.rows.iter().map(|r| Value::Record(r.clone())).collect(),
        Value::Array(a) => a.clone(),
        other => return budget_string_record(&aecon_render(other), max),
    };

    let total = rows.len();
    let start = cursor.min(total);
    let mut end = start;
    let mut used = 0usize;
    while end < total {
        // Conservative per-row estimate (a single record renders with its keys;
        // the final page shares one header, so this never under-counts).
        let row_tok = est_token_count(&aecon_render(&rows[end]));
        if end > start && used + row_tok > max {
            break;
        }
        used += row_tok;
        end += 1;
    }
    if end == start && total > start {
        end = start + 1; // always make progress, even on a single oversized row
    }

    let page_slice = Value::Array(rows[start..end].to_vec());
    let page_str = aecon_render(&page_slice);
    let page_tokens = est_token_count(&page_str);
    let shown = end - start;

    let mut r = BTreeMap::new();
    r.insert("page".to_string(), Value::Str(page_str));
    r.insert("shown".to_string(), Value::Int(shown as i64));
    r.insert("from".to_string(), Value::Int(start as i64));
    r.insert("total".to_string(), Value::Int(total as i64));
    r.insert("elided".to_string(), Value::Int((total - end) as i64));
    r.insert("page_tokens".to_string(), Value::Int(page_tokens as i64));
    r.insert(
        "next_cursor".to_string(),
        if end < total {
            Value::Int(end as i64)
        } else {
            Value::Null
        },
    );
    r.insert(
        "truncated".to_string(),
        Value::Bool(end < total || start > 0),
    );
    Value::Record(r)
}

/// Render a result for **agent mode** (`AETHER_MODE=agent`): compact, deterministic
/// AECON instead of the human pretty-printer (no ANSI, keys emitted once, the
/// four structural levers applied). `Null` prints nothing and a bare `Str` is
/// returned raw (a single field value is what the agent asked for). When a token
/// budget is set, the value is paged via `budget_value` and rendered as the AECON
/// page followed by one compact `@page …` metadata line (`shown`/`total`/`elided`/
/// `next_cursor`/…), avoiding the double-encoding that pretty-printing the
/// envelope record would cause.
pub fn render_agent(v: &Value, budget: Option<usize>) -> Option<String> {
    // Scrub secret shapes from the value before it enters the agent's context
    // window (§7.6). Agent-path only — the human pretty-printer keeps full
    // fidelity. Opt out with AETHER_REDACT=off.
    let redacted;
    let v = if crate::safety::redaction_enabled() {
        redacted = redact_value(v);
        &redacted
    } else {
        v
    };
    match v {
        Value::Null => None,
        Value::Str(s) => Some(s.clone()),
        _ => {
            let full = match budget {
                Some(max) if max > 0 => render_budget_envelope(&budget_value(v, max, 0)),
                _ => aecon_render(v),
            };
            // A result too large to be worth sending whole is kept server-side
            // and referenced instead. The agent narrows it down with a pipeline
            // and only the small answer crosses back — the saving no encoder can
            // reach, because it is the bytes never sent.
            if crate::handles::worth_handling(v, full.len()) {
                Some(render_handle(v, full.len()))
            } else {
                Some(full)
            }
        }
    }
}

/// `undo(n = 1)` — put back what the last `n` mutating steps overwrote.
///
/// Returns one record per step, **including the ones it could not reverse**.
/// The counts are reported separately because "3 restored" and "3 restored, 1
/// irreversible" call for different decisions, and collapsing them is how a
/// partial recovery gets mistaken for a complete one.
fn bi_undo(args: Vec<Value>) -> Result<Value> {
    let n = match args.first() {
        None => 1,
        Some(v) => v
            .as_int()
            .map_err(|_| crate::safety::bad_arg("undo", "a step count", "a non-integer"))?
            .max(0) as usize,
    };
    let outcomes = crate::journal::undo(n);
    let (mut restored, mut removed, mut skipped, mut failed) = (0, 0, 0, 0);
    let rows: Vec<Value> = outcomes
        .iter()
        .map(|o| {
            let mut m = std::collections::BTreeMap::new();
            let (action, what, why) = match o {
                crate::journal::Outcome::Restored(w) => {
                    restored += 1;
                    ("restored", w.clone(), String::new())
                }
                crate::journal::Outcome::Removed(w) => {
                    removed += 1;
                    ("removed", w.clone(), String::new())
                }
                crate::journal::Outcome::Skipped { what, why } => {
                    skipped += 1;
                    ("skipped", what.clone(), why.clone())
                }
                crate::journal::Outcome::Failed { what, why } => {
                    failed += 1;
                    ("failed", what.clone(), why.clone())
                }
            };
            m.insert("action".to_string(), Value::Str(action.to_string()));
            m.insert("what".to_string(), Value::Str(what));
            if !why.is_empty() {
                m.insert("why".to_string(), Value::Str(why));
            }
            Value::Record(m)
        })
        .collect();

    let mut out = std::collections::BTreeMap::new();
    out.insert("restored".to_string(), Value::Int(restored));
    out.insert("removed".to_string(), Value::Int(removed));
    out.insert("skipped".to_string(), Value::Int(skipped));
    out.insert("failed".to_string(), Value::Int(failed));
    out.insert("steps".to_string(), Value::Array(rows));
    // Say it in words as well as counts: a caller that reads only the summary
    // still learns the world was not fully restored.
    out.insert(
        "complete".to_string(),
        Value::Bool(skipped == 0 && failed == 0),
    );
    Ok(Value::Record(out))
}

/// `journal()` — the recorded steps, and how many of them can be reversed.
fn bi_journal() -> Result<Value> {
    let entries = crate::journal::entries();
    let reversible = crate::journal::reversible_count();
    let rows: Vec<Value> = entries
        .iter()
        .map(|e| {
            let mut m = std::collections::BTreeMap::new();
            m.insert("seq".to_string(), Value::Int(e.seq as i64));
            m.insert("builtin".to_string(), Value::Str(e.builtin.clone()));
            m.insert("effect".to_string(), Value::Str(e.effect.clone()));
            if !e.path.is_empty() {
                m.insert("path".to_string(), Value::Str(e.path.clone()));
            }
            m.insert("reversible".to_string(), Value::Bool(e.reversible()));
            if let crate::journal::Before::Irreversible(why) = &e.before {
                m.insert("why".to_string(), Value::Str(why.clone()));
            }
            Value::Record(m)
        })
        .collect();
    let mut out = std::collections::BTreeMap::new();
    out.insert("steps".to_string(), Value::Int(entries.len() as i64));
    out.insert("reversible".to_string(), Value::Int(reversible as i64));
    out.insert(
        "irreversible".to_string(),
        Value::Int((entries.len() - reversible) as i64),
    );
    out.insert(
        "enabled".to_string(),
        Value::Bool(crate::journal::enabled()),
    );
    out.insert("entries".to_string(), Value::Array(rows));
    Ok(Value::Record(out))
}

/// `journal_clear()` — forget the recorded steps. Touches no files; the
/// captured contents are dropped, so anything before this point can no longer
/// be rewound.
fn bi_journal_clear() -> Result<Value> {
    let n = crate::journal::entries().len();
    crate::journal::clear();
    let mut m = std::collections::BTreeMap::new();
    m.insert("forgotten".to_string(), Value::Int(n as i64));
    m.insert(
        "note".to_string(),
        Value::Str("no files changed; these steps can no longer be undone".to_string()),
    );
    Ok(Value::Record(m))
}

/// `handle(id)` — the full value behind a handle, exactly as computed.
///
/// A missing id is a structured error rather than a null, and it names the live
/// handles: a handle from a previous process is gone, and an agent that gets
/// `null` back cannot tell that apart from an empty result.
fn bi_handle(args: Vec<Value>) -> Result<Value> {
    let id = args
        .first()
        .and_then(|v| v.as_str().ok())
        .map(|s| s.to_string())
        .ok_or_else(|| crate::safety::arg_err("handle(id): a handle id is required"))?;
    match crate::handles::get(&id) {
        Some(v) => Ok(v),
        None => {
            let live: Vec<String> = crate::handles::list().into_iter().map(|h| h.id).collect();
            let got = if live.is_empty() {
                format!("'{id}' (no handles live — they do not survive the process)")
            } else {
                format!("'{id}' (live: {})", live.join(", "))
            };
            Err(crate::safety::bad_arg(
                "handle",
                "a live handle id, as listed by handles()",
                &got,
            ))
        }
    }
}

/// `handles()` — every live handle with its shape and size, without the data.
fn bi_handles() -> Result<Value> {
    Ok(Value::Array(
        crate::handles::list()
            .into_iter()
            .map(|h| {
                let mut m = std::collections::BTreeMap::new();
                m.insert("id".to_string(), Value::Str(h.id));
                m.insert("shape".to_string(), Value::Str(h.shape));
                m.insert("items".to_string(), Value::Int(h.items as i64));
                m.insert("bytes".to_string(), Value::Int(h.bytes as i64));
                Value::Record(m)
            })
            .collect(),
    ))
}

/// `handle_drop(id)` — release a handle, reporting whether it existed.
fn bi_handle_drop(args: Vec<Value>) -> Result<Value> {
    let id = args
        .first()
        .and_then(|v| v.as_str().ok())
        .map(|s| s.to_string())
        .ok_or_else(|| crate::safety::arg_err("handle_drop(id): a handle id is required"))?;
    Ok(Value::Bool(crate::handles::drop_handle(&id)))
}

/// Render a large result as a handle: what it is, how big, a short preview, and
/// the exact call that narrows it down.
///
/// The hint is not decoration — it is how the agent discovers `handle` at all.
/// These builtins are reachable but not in the ontology listing, so the call
/// site teaches itself at the moment it is needed, which beats requiring a
/// discovery round-trip to learn how to avoid a discovery round-trip.
fn render_handle(v: &Value, full_bytes: usize) -> String {
    let h = crate::handles::put(v.clone(), full_bytes);
    let preview = crate::handles::preview_of(v);
    let omitted = crate::handles::omitted(v);
    let mut out = String::new();
    out.push_str(&format!("@handle {}\n", h.id));
    out.push_str(&format!("@shape {}\n", h.shape));
    out.push_str(&format!("@items {}\n", h.items));
    out.push_str(&format!("@bytes {}\n", h.bytes));
    out.push_str(&aecon_render(&preview));
    if omitted > 0 {
        // Stated explicitly: a preview that looks like a result is how silent
        // truncation misleads.
        out.push_str(&format!("\n@omitted {omitted}"));
    }
    out.push_str(&format!(
        "\n@hint handle(\"{}\") | where(...) | take(5)  — full value kept, nothing lost",
        h.id
    ));
    out
}

/// Recursively redact known secret shapes from a value before it is rendered to
/// an agent. Scalar strings are shape-scrubbed (API-key prefixes, JWTs, PEM
/// blocks, URL credentials, `key=secret` assignments) via `safety::redact_str`;
/// any record/table field whose *name* denotes a secret is replaced with the
/// marker even when its value doesn't match a shape. Structure is preserved —
/// only secret leaves change — and the transform is deterministic.
pub fn redact_value(v: &Value) -> Value {
    match v {
        Value::Str(s) => {
            let (r, _) = crate::safety::redact_str(s);
            Value::Str(r)
        }
        Value::Uri(s) => {
            let (r, _) = crate::safety::redact_str(s);
            Value::Uri(r)
        }
        Value::Array(items) => Value::Array(items.iter().map(redact_value).collect()),
        Value::Record(m) => Value::Record(redact_field_map(m)),
        Value::Table(t) => Value::Table(crate::value::Table {
            rows: t.rows.iter().map(redact_field_map).collect(),
            schema: t.schema.clone(),
        }),
        other => other.clone(),
    }
}

/// Redact a record/row field map: secret-named fields become the marker;
/// every other field is recursively redacted.
fn redact_field_map(
    m: &std::collections::BTreeMap<String, Value>,
) -> std::collections::BTreeMap<String, Value> {
    let mut out = std::collections::BTreeMap::new();
    for (k, val) in m {
        if crate::safety::is_secret_name(k) && redactable_by_name(val) {
            out.insert(
                k.clone(),
                Value::Str(crate::safety::REDACTION_MARKER.to_string()),
            );
        } else {
            out.insert(k.clone(), redact_value(val));
        }
    }
    out
}

/// Whether a value under a secret-*sounding* field name should actually be
/// replaced by the marker.
///
/// `is_secret_name` matches substrings, so `TOKEN` also matches `full_tokens`,
/// `compact_tokens`, `page_tokens` and `tokens_in`. Those hold **counts**, and
/// redacting them made the token-economy surface — the thing this project
/// measures itself by — report `[REDACTED]` to agents instead of numbers.
///
/// Two rules, both narrow:
///
/// * A secret is a string. A number, bool or null under a secret-sounding name
///   cannot be one, and blanking it destroys information for no gain.
/// * An **approval or plan token** (`apv_…`, `apl_…`) is a capability the agent
///   is required to echo back, not a credential to hide. `plan()` returned
///   `token="[REDACTED]"` in its machine-readable field while printing the real
///   token in `hint` — incoherent, and it broke the documented plan/apply flow
///   for any caller reading the structured field.
///
/// Found by driving the shell as an agent.
fn redactable_by_name(v: &Value) -> bool {
    match v {
        Value::Str(s) | Value::Uri(s) => !crate::safety::is_capability_token(s),
        // Containers are walked normally so genuine secrets inside are still
        // caught by shape and by their own field names.
        Value::Array(_) | Value::Record(_) | Value::Table(_) => false,
        _ => false,
    }
}

/// Render a result for **deterministic mode** (`--deterministic` / `AE_DETERMINISTIC`):
/// canonical JSON — byte-identical for equal values across OS/locale (sorted keys,
/// shortest round-trip floats), for snapshot tests, content-addressable caching,
/// and cross-tool diffs. The whole value is emitted (no budget truncation, which
/// would break reproducibility of the full result). `Null` prints nothing.
pub fn render_canonical(v: &Value) -> Option<String> {
    match v {
        Value::Null => None,
        _ => Some(canonical_render(v)),
    }
}

/// Format a `budget_value`/`budget_string_record` envelope as AECON page text plus
/// a single `@page k=v…` metadata line (the page field is already AECON text, so
/// it is emitted raw rather than re-quoted).
fn render_budget_envelope(env: &Value) -> String {
    if let Value::Record(m) = env {
        let page = match m.get("page") {
            Some(Value::Str(s)) => s.clone(),
            _ => String::new(),
        };
        let meta: Vec<String> = m
            .iter()
            .filter(|(k, _)| k.as_str() != "page")
            .map(|(k, val)| format!("{}={}", k, aecon_atom(val)))
            .collect();
        if meta.is_empty() {
            page
        } else {
            format!("{}\n@page {}", page, meta.join("\t"))
        }
    } else {
        aecon_render(env)
    }
}

// ─────────────────────────────────────────────────────────────────────────
// Plan / Apply (docs/AGENTIC_FIRST_DESIGN.md §9): a destructive batch is
// described declaratively, reviewed (typed plan + blast radius + a bound token),
// approved once, then applied ATOMICALLY inside a transaction (all-or-nothing,
// auto-rollback on any failure). Composes approval (safety) + transactions (tx)
// + structured output. Supported ops: write{path,content}, rm{path}, mkdir{path}.
// ─────────────────────────────────────────────────────────────────────────

/// A content-bound token for a plan (`apl_<16 hex of sha256(canonical(ops))>`),
/// so approving one plan cannot authorize a different set of operations.
fn plan_token(ops: &Value) -> String {
    let mut h = Sha256::new();
    h.update(canonical_render(ops).as_bytes());
    let digest = h.finalize();
    let hex: String = digest
        .iter()
        .take(8)
        .map(|b| format!("{:02x}", b))
        .collect();
    format!("apl_{}", hex)
}

/// Validate and normalize plan ops into `(op, path, content?)` tuples.
#[allow(clippy::type_complexity)]
fn parse_plan_ops(ops: &Value) -> Result<Vec<(String, String, Option<String>, Option<String>)>> {
    let arr = match ops {
        Value::Array(a) => a,
        other => {
            return Err(crate::safety::bad_arg(
                "plan/apply",
                "ops: Array<Record{op, path, content?}>",
                other.type_name(),
            ))
        }
    };
    let mut out = Vec::with_capacity(arr.len());
    for (i, e) in arr.iter().enumerate() {
        let m = match e {
            Value::Record(m) => m,
            _ => {
                return Err(anyhow!(
                    "plan: op #{} must be a record {{op, path, content?}}",
                    i
                ))
            }
        };
        let op = match m.get("op") {
            Some(Value::Str(s)) => s.clone(),
            _ => {
                return Err(crate::safety::arg_err(format!(
                    "plan: op #{} missing 'op' string",
                    i
                )))
            }
        };
        let path = match m.get("path") {
            Some(Value::Str(s)) => s.clone(),
            _ => {
                return Err(crate::safety::arg_err(format!(
                    "plan: op #{} missing 'path' string",
                    i
                )))
            }
        };
        let content = match m.get("content") {
            Some(Value::Str(s)) => Some(s.clone()),
            _ => None,
        };
        // `copy`/`move` carry a destination path in `dest` (or `to`).
        let dest = match m.get("dest").or_else(|| m.get("to")) {
            Some(Value::Str(s)) => Some(s.clone()),
            _ => None,
        };
        match op.as_str() {
            "write" | "append" if content.is_none() => {
                return Err(crate::safety::arg_err(format!(
                    "plan: {} op #{} requires 'content'",
                    op, i
                )))
            }
            "copy" | "move" if dest.is_none() => {
                return Err(crate::safety::arg_err(format!(
                    "plan: {} op #{} requires 'dest' (destination path)",
                    op, i
                )))
            }
            "write" | "append" | "rm" | "mkdir" | "copy" | "move" => {}
            other => {
                return Err(anyhow!(
                    "plan: op #{} unsupported op '{}' (expected write|append|rm|mkdir|copy|move)",
                    i,
                    other
                ))
            }
        }
        out.push((op, path, content, dest));
    }
    Ok(out)
}

/// plan(ops) - Produce a typed, reviewable plan for a destructive batch without
/// executing it: a summary (writes/deletes/mkdirs), operation count, and a
/// content-bound approval `token`. Review, `approve(token)`, then `apply(ops)`.
fn bi_plan(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let ops = args
        .first()
        .cloned()
        .ok_or_else(|| crate::safety::bad_arg("plan", "ops: Array<Record{op, path}>", "nothing"))?;
    let parsed = parse_plan_ops(&ops)?;
    let (mut writes, mut appends, mut deletes, mut mkdirs, mut copies, mut moves) =
        (0i64, 0i64, 0i64, 0i64, 0i64, 0i64);
    for (op, _, _, _) in &parsed {
        match op.as_str() {
            "write" => writes += 1,
            "append" => appends += 1,
            "rm" => deletes += 1,
            "mkdir" => mkdirs += 1,
            "copy" => copies += 1,
            "move" => moves += 1,
            _ => {}
        }
    }
    let token = plan_token(&ops);
    let mut summary = BTreeMap::new();
    summary.insert("writes".to_string(), Value::Int(writes));
    summary.insert("appends".to_string(), Value::Int(appends));
    summary.insert("deletes".to_string(), Value::Int(deletes));
    summary.insert("mkdirs".to_string(), Value::Int(mkdirs));
    summary.insert("copies".to_string(), Value::Int(copies));
    summary.insert("moves".to_string(), Value::Int(moves));
    let mut r = BTreeMap::new();
    r.insert("operations".to_string(), Value::Int(parsed.len() as i64));
    r.insert("summary".to_string(), Value::Record(summary));
    r.insert("token".to_string(), Value::Str(token.clone()));
    r.insert(
        "hint".to_string(),
        Value::Str(format!(
            "review, then in agent mode: approve(\"{}\") and apply(<ops>)",
            token
        )),
    );
    r.insert("plan".to_string(), ops);
    Ok(Value::Record(r))
}

/// plan_diff(ops) - What a plan would change, as text a reviewer can read.
///
/// `plan()` answers "how many operations, of what kinds". That is enough to
/// decide whether a plan is the right *shape* and not enough to decide whether
/// it is correct: two plans with identical summaries can write entirely
/// different bytes. This renders the actual before/after.
///
/// A separate builtin rather than a field on `plan()` on purpose. A diff is
/// unbounded in a way a summary is not, and this project's convention is
/// progressive disclosure -- an agent that wants the detail asks for it, and
/// one that only wants the shape does not pay for it.
///
/// Output is capped per file, with the elided count reported rather than
/// silently dropped -- the same contract `budget()` uses.
fn bi_plan_diff(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    const MAX_LINES_PER_OP: usize = 40;

    let ops = args.first().cloned().ok_or_else(|| {
        crate::safety::bad_arg("plan_diff", "ops: Array<Record{op, path}>", "nothing")
    })?;
    let parsed = parse_plan_ops(&ops)?;

    let mut entries = Vec::with_capacity(parsed.len());
    let mut total_added = 0i64;
    let mut total_removed = 0i64;

    for (op, path, content, dest) in &parsed {
        let mut rec = BTreeMap::new();
        rec.insert("op".to_string(), Value::Str(op.clone()));
        rec.insert("path".to_string(), Value::Str(path.clone()));

        // What is there now. `None` means the path does not exist or cannot be
        // read as text -- reported, never guessed at.
        let existing = std::fs::read_to_string(path).ok();
        let exists = std::path::Path::new(path).exists();

        let (before, after): (Vec<String>, Vec<String>) = match op.as_str() {
            "write" => (
                existing
                    .as_deref()
                    .unwrap_or("")
                    .lines()
                    .map(str::to_string)
                    .collect(),
                content
                    .as_deref()
                    .unwrap_or("")
                    .lines()
                    .map(str::to_string)
                    .collect(),
            ),
            "append" => {
                let base: Vec<String> = existing
                    .as_deref()
                    .unwrap_or("")
                    .lines()
                    .map(str::to_string)
                    .collect();
                let mut end = base.clone();
                end.extend(content.as_deref().unwrap_or("").lines().map(str::to_string));
                (base, end)
            }
            "rm" => (
                existing
                    .as_deref()
                    .unwrap_or("")
                    .lines()
                    .map(str::to_string)
                    .collect(),
                Vec::new(),
            ),
            _ => (Vec::new(), Vec::new()),
        };

        let mut lines: Vec<Value> = Vec::new();
        let mut added = 0i64;
        let mut removed = 0i64;

        match op.as_str() {
            "write" | "append" | "rm" => {
                // A line-set difference, not a longest-common-subsequence diff:
                // it answers "what appears and what disappears" without claiming
                // to reconstruct how an editor would have moved things.
                for l in &before {
                    if !after.contains(l) {
                        removed += 1;
                        if lines.len() < MAX_LINES_PER_OP {
                            lines.push(Value::Str(format!("-{l}")));
                        }
                    }
                }
                for l in &after {
                    if !before.contains(l) {
                        added += 1;
                        if lines.len() < MAX_LINES_PER_OP {
                            lines.push(Value::Str(format!("+{l}")));
                        }
                    }
                }
                if existing.is_none() && exists {
                    rec.insert(
                        "note".to_string(),
                        Value::Str("path exists but is not readable as text".to_string()),
                    );
                }
            }
            "mkdir" => {
                rec.insert(
                    "note".to_string(),
                    Value::Str(if exists {
                        "directory already exists".to_string()
                    } else {
                        "creates directory".to_string()
                    }),
                );
            }
            "copy" | "move" => {
                let d = dest.clone().unwrap_or_default();
                rec.insert("dest".to_string(), Value::Str(d.clone()));
                rec.insert(
                    "note".to_string(),
                    Value::Str(if std::path::Path::new(&d).exists() {
                        format!("{op} over an existing {d}")
                    } else {
                        format!("{op} to a new {d}")
                    }),
                );
            }
            _ => {}
        }

        rec.insert("exists".to_string(), Value::Bool(exists));
        rec.insert("added".to_string(), Value::Int(added));
        rec.insert("removed".to_string(), Value::Int(removed));
        let shown = lines.len() as i64;
        let elided = (added + removed) - shown;
        rec.insert("lines".to_string(), Value::Array(lines));
        if elided > 0 {
            rec.insert("elided".to_string(), Value::Int(elided));
        }

        total_added += added;
        total_removed += removed;
        entries.push(Value::Record(rec));
    }

    let mut out = BTreeMap::new();
    out.insert("operations".to_string(), Value::Int(parsed.len() as i64));
    out.insert("added".to_string(), Value::Int(total_added));
    out.insert("removed".to_string(), Value::Int(total_removed));
    out.insert("diff".to_string(), Value::Array(entries));
    out.insert("token".to_string(), Value::Str(plan_token(&ops)));
    Ok(Value::Record(out))
}

/// apply(ops) - Execute a plan atomically inside a transaction. In agent mode it
/// requires the plan's token to be approved (else returns `{status:"needs_approval"}`);
/// any failure rolls the whole batch back. Filesystem paths are confined to the
/// workspace jail when enforced.
fn bi_apply(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let ops = args.first().cloned().ok_or_else(|| {
        crate::safety::bad_arg("apply", "ops: Array<Record{op, path}>", "nothing")
    })?;
    let parsed = parse_plan_ops(&ops)?;
    let token = plan_token(&ops);
    let agent = matches!(crate::safety::current_mode(), crate::safety::Mode::Agent);

    if agent && !crate::safety::is_approved(&token) {
        let mut r = BTreeMap::new();
        r.insert(
            "status".to_string(),
            Value::Str("needs_approval".to_string()),
        );
        r.insert("token".to_string(), Value::Str(token.clone()));
        r.insert("operations".to_string(), Value::Int(parsed.len() as i64));
        r.insert(
            "hint".to_string(),
            Value::Str(format!("approve(\"{}\") then re-run apply", token)),
        );
        return Ok(Value::Record(r));
    }

    let enforce_jail = agent || std::env::var("AETHER_WORKSPACE").is_ok();
    crate::tx::begin().map_err(|e| anyhow!("apply: {}", e))?;

    let mut applied = 0i64;
    let mut failure: Option<String> = None;
    for (op, path, content, dest) in &parsed {
        if enforce_jail && !crate::safety::within_workspace(path) {
            failure = Some(format!("'{}' is outside the workspace", path));
            break;
        }
        // copy/move write a destination — it is jailed and snapshotted too.
        if let Some(d) = dest {
            if enforce_jail && !crate::safety::within_workspace(d) {
                failure = Some(format!("destination '{}' is outside the workspace", d));
                break;
            }
        }
        crate::tx::snapshot(path);
        if let Some(d) = dest {
            crate::tx::snapshot(d);
        }
        let res: std::io::Result<()> = match op.as_str() {
            "write" => std::fs::write(path, content.as_deref().unwrap_or("")),
            "append" => {
                use std::io::Write;
                std::fs::OpenOptions::new()
                    .create(true)
                    .append(true)
                    .open(path)
                    .and_then(|mut f| f.write_all(content.as_deref().unwrap_or("").as_bytes()))
            }
            "rm" => std::fs::remove_file(path),
            "mkdir" => std::fs::create_dir_all(path),
            "copy" => std::fs::copy(path, dest.as_deref().unwrap_or("")).map(|_| ()),
            "move" => std::fs::rename(path, dest.as_deref().unwrap_or("")),
            _ => Ok(()),
        };
        if let Err(e) = res {
            failure = Some(format!("{} {}: {}", op, path, e));
            break;
        }
        applied += 1;
    }

    let mut r = BTreeMap::new();
    if let Some(err) = failure {
        let restored = crate::tx::rollback().unwrap_or(0);
        let _ = crate::safety::audit(
            "apply",
            crate::safety::Effect::Destructive,
            "failed",
            &token,
            serde_json::json!({ "error": err, "rolled_back": restored }),
        );
        r.insert("status".to_string(), Value::Str("failed".to_string()));
        r.insert("error".to_string(), Value::Str(err));
        r.insert("rolled_back".to_string(), Value::Bool(true));
        r.insert("restored".to_string(), Value::Int(restored as i64));
    } else {
        let _ = crate::tx::commit();
        let _ = crate::safety::audit(
            "apply",
            crate::safety::Effect::Destructive,
            "applied",
            &token,
            serde_json::json!({ "operations": applied }),
        );
        r.insert("status".to_string(), Value::Str("applied".to_string()));
        r.insert("applied".to_string(), Value::Int(applied));
    }
    Ok(Value::Record(r))
}

/// tx_begin() - Start a filesystem transaction. Subsequent file_write/rm calls
/// record their pre-modification state so the batch can be rolled back.
fn bi_tx_begin(_args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let id = crate::tx::begin()?;
    let mut r = BTreeMap::new();
    r.insert("transaction".to_string(), Value::Str(id));
    r.insert("active".to_string(), Value::Bool(true));
    // Nesting depth after this begin (1 = outermost; a nested begin pushes a child).
    r.insert("depth".to_string(), Value::Int(crate::tx::depth() as i64));
    Ok(Value::Record(r))
}

/// tx_commit() - Commit the active transaction (keep changes, discard journal).
fn bi_tx_commit(_args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let n = crate::tx::commit()?;
    let mut r = BTreeMap::new();
    r.insert("committed".to_string(), Value::Bool(true));
    r.insert("operations".to_string(), Value::Int(n as i64));
    Ok(Value::Record(r))
}

/// tx_rollback() - Roll back the active transaction, restoring every recorded
/// path to its pre-transaction state.
fn bi_tx_rollback(_args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let n = crate::tx::rollback()?;
    let mut r = BTreeMap::new();
    r.insert("rolled_back".to_string(), Value::Bool(true));
    r.insert("restored".to_string(), Value::Int(n as i64));
    Ok(Value::Record(r))
}

/// tx_status() - Report whether a transaction is active and its operation count.
fn bi_tx_status(_args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let mut r = BTreeMap::new();
    match crate::tx::status() {
        Some((id, n)) => {
            r.insert("active".to_string(), Value::Bool(true));
            r.insert("transaction".to_string(), Value::Str(id));
            r.insert("operations".to_string(), Value::Int(n as i64));
            r.insert("depth".to_string(), Value::Int(crate::tx::depth() as i64));
        }
        None => {
            r.insert("active".to_string(), Value::Bool(false));
            r.insert("depth".to_string(), Value::Int(0));
        }
    }
    Ok(Value::Record(r))
}

/// tx_savepoint(name) - Mark a named savepoint inside the active transaction; a
/// later `tx_rollback_to(name)` reverts only the operations recorded after it.
fn bi_tx_savepoint(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let name = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        _ => {
            return Err(crate::safety::bad_arg(
                "tx_savepoint",
                "name: String",
                "nothing",
            ))
        }
    };
    crate::tx::savepoint(&name)?;
    let mut r = BTreeMap::new();
    r.insert("savepoint".to_string(), Value::Str(name));
    Ok(Value::Record(r))
}

/// tx_rollback_to(name) - Roll back to a named savepoint, reverting only the
/// operations recorded after it; the transaction stays open.
fn bi_tx_rollback_to(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let name = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        _ => {
            return Err(crate::safety::bad_arg(
                "tx_rollback_to",
                "name: String",
                "nothing",
            ))
        }
    };
    let n = crate::tx::rollback_to(&name)?;
    let mut r = BTreeMap::new();
    r.insert("rolled_back_to".to_string(), Value::Str(name));
    r.insert("restored".to_string(), Value::Int(n as i64));
    Ok(Value::Record(r))
}

/// safety_status() - Report the current safety operating envelope so an agent
/// knows what it may do before acting: execution mode, acting principal,
/// workspace jail root, audit log, whether a transaction is active, and the
/// resolved policy decision (allow/deny/approve) for every effect class.
fn bi_safety_status(_args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    use crate::safety::{Decision, Effect, Mode};
    let mode = crate::safety::current_mode();
    let mode_str = match mode {
        Mode::Agent => "agent",
        Mode::Human => "human",
    };
    let effects = [
        Effect::Pure,
        Effect::ReadLocal,
        Effect::WriteLocal,
        Effect::Network,
        Effect::Process,
        Effect::Destructive,
        Effect::Exec,
        Effect::Privileged,
    ];
    let mut policy = BTreeMap::new();
    for e in effects {
        let d = match crate::safety::decide(e, mode) {
            Decision::Allow => "allow",
            Decision::Deny => "deny",
            Decision::Approve => "approve",
        };
        policy.insert(e.as_str().to_string(), Value::Str(d.to_string()));
    }
    let mut r = BTreeMap::new();
    r.insert("mode".to_string(), Value::Str(mode_str.to_string()));
    r.insert(
        "principal".to_string(),
        crate::safety::current_principal()
            .map(Value::Str)
            .unwrap_or(Value::Null),
    );
    r.insert(
        "workspace".to_string(),
        Value::Str(
            crate::safety::workspace_root()
                .to_string_lossy()
                .to_string(),
        ),
    );
    r.insert(
        "audit_log".to_string(),
        crate::safety::audit_path()
            .map(|p| Value::Str(p.to_string_lossy().to_string()))
            .unwrap_or(Value::Null),
    );
    r.insert(
        "transaction_active".to_string(),
        Value::Bool(crate::tx::is_active()),
    );
    r.insert("policy".to_string(), Value::Record(policy));
    r.insert(
        "governor".to_string(),
        Value::from_json(&crate::safety::governor_snapshot()),
    );
    Ok(Value::Record(r))
}

/// governor_status() - Report the resource-governor envelope (§7.6): current
/// counts (ops/files/procs), the configured limits (null = unlimited), elapsed
/// wall-clock ms, and whether governors are active (agent mode). Lets an agent
/// watch its blast-radius budget burn down before it hits `E_BUDGET_EXCEEDED`.
fn bi_governor_status(_args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    Ok(Value::from_json(&crate::safety::governor_snapshot()))
}

/// governor_reset() - Reset the resource-governor counters and wall-clock start,
/// beginning a fresh envelope (e.g. after deliberately raising a limit or at a
/// session boundary).
fn bi_governor_reset(_args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    crate::safety::governor_reset();
    Ok(Value::Bool(true))
}

// ─────────────────────────────────────────────────────────────────────────
// Stateful sessions (docs/AGENTIC_FIRST_DESIGN.md §6.3): a persistent Env keyed
// by session id, so an agent builds up state across calls (`let x = …` then use
// `x` later) WITHOUT re-sending prior context each turn — a token-efficiency and
// capability win over the single-shot eval path.
// ─────────────────────────────────────────────────────────────────────────

static SESS_COUNTER: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);

/// A stateful session: a persistent environment plus running token accounting.
struct Session {
    env: crate::env::Env,
    tokens_in: u64,
    tokens_out: u64,
    evals: u64,
}

impl Session {
    fn new() -> Self {
        // Register the module namespaces (file, sys, str, http, …) so a session
        // can run module-qualified calls like `file.read(…)`, not just builtins.
        let mut env = crate::env::Env::new();
        for (name, module) in crate::modules::all_modules() {
            env.register_module(name, module);
        }
        Self {
            env,
            tokens_in: 0,
            tokens_out: 0,
            evals: 0,
        }
    }
}

lazy_static::lazy_static! {
    static ref SESSIONS: std::sync::Mutex<HashMap<String, Session>> =
        std::sync::Mutex::new(HashMap::new());
}

/// sess_open() - Create a stateful session and return its id. Subsequent
/// `sess_eval(id, code)` calls share one persistent environment.
fn bi_sess_open(_args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let id = format!(
        "sess_{}_{}",
        std::process::id(),
        SESS_COUNTER.fetch_add(1, std::sync::atomic::Ordering::SeqCst)
    );
    SESSIONS
        .lock()
        .map_err(|_| anyhow!("session store poisoned"))?
        .insert(id.clone(), Session::new());
    let mut r = BTreeMap::new();
    r.insert("session".to_string(), Value::Str(id));
    r.insert("active".to_string(), Value::Bool(true));
    Ok(Value::Record(r))
}

/// sess_eval(id, code) - Evaluate code in a session's persistent environment;
/// `let` bindings and mutations persist across calls. Returns the result value.
fn bi_sess_eval(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let id = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        other => {
            return Err(crate::safety::bad_arg(
                "sess_eval",
                "session_id: String",
                other.map(|v| v.type_name()).unwrap_or("nothing"),
            ))
        }
    };
    let code = match args.get(1) {
        Some(Value::Str(s)) => s.clone(),
        other => {
            return Err(crate::safety::bad_arg(
                "sess_eval",
                "code: String",
                other.map(|v| v.type_name()).unwrap_or("nothing"),
            ))
        }
    };
    // Take the env out (not holding the lock across eval — avoids deadlock if the
    // evaluated code touches the session store) and put it back afterward so
    // bindings made before any error still persist.
    let mut session = {
        let mut store = SESSIONS
            .lock()
            .map_err(|_| anyhow!("session store poisoned"))?;
        match store.remove(&id) {
            Some(s) => s,
            None => return Err(anyhow!("sess_eval: no such session '{}'", id)),
        }
    };
    let result = (|| -> Result<Value> {
        let stmts = crate::parser::parse_program(&code)?;
        crate::eval::eval_program(&stmts, &mut session.env)
    })();
    // Accumulate running token usage for this session.
    session.evals += 1;
    session.tokens_in += est_token_count(&code) as u64;
    let out_str = match &result {
        Ok(v) => v.to_display_string(),
        Err(e) => e.to_string(),
    };
    session.tokens_out += est_token_count(&out_str) as u64;
    SESSIONS
        .lock()
        .map_err(|_| anyhow!("session store poisoned"))?
        .insert(id, session);
    result
}

/// sess_usage(id) - Running token accounting for a session: estimated
/// `tokens_in`/`tokens_out`/`tokens_total` and the number of `evals`.
fn bi_sess_usage(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let id = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        other => {
            return Err(crate::safety::bad_arg(
                "sess_usage",
                "session_id: String",
                other.map(|v| v.type_name()).unwrap_or("nothing"),
            ))
        }
    };
    let store = SESSIONS
        .lock()
        .map_err(|_| anyhow!("session store poisoned"))?;
    match store.get(&id) {
        Some(s) => {
            let mut r = BTreeMap::new();
            r.insert("tokens_in".to_string(), Value::Int(s.tokens_in as i64));
            r.insert("tokens_out".to_string(), Value::Int(s.tokens_out as i64));
            r.insert(
                "tokens_total".to_string(),
                Value::Int((s.tokens_in + s.tokens_out) as i64),
            );
            r.insert("evals".to_string(), Value::Int(s.evals as i64));
            Ok(Value::Record(r))
        }
        None => Err(anyhow!("sess_usage: no such session '{}'", id)),
    }
}

/// sess_close(id) - Discard a session and its environment.
fn bi_sess_close(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let id = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        other => {
            return Err(crate::safety::bad_arg(
                "sess_close",
                "session_id: String",
                other.map(|v| v.type_name()).unwrap_or("nothing"),
            ))
        }
    };
    let existed = SESSIONS
        .lock()
        .map_err(|_| anyhow!("session store poisoned"))?
        .remove(&id)
        .is_some();
    let mut r = BTreeMap::new();
    r.insert("closed".to_string(), Value::Bool(existed));
    Ok(Value::Record(r))
}

/// ontology_manifest() - Compact root of the ontology for progressive
/// disclosure: categories with builtin counts, effect classes, and samples,
/// plus the effect legend. Load this cheaply, then `ontology_describe` the slice
/// you need instead of carrying the full ontology in context.
fn bi_ontology_manifest(_args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    Ok(Value::from_json(&crate::agent_api::ontology_manifest_json()))
}

/// ontology_describe(name) - Expand one ontology slice: a category name → its
/// builtins (name, signature, effect), or a builtin name → its full definition
/// (effect, params, examples).
fn bi_ontology_describe(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let q = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        other => {
            return Err(crate::safety::bad_arg(
                "ontology_describe",
                "name: String (category or builtin)",
                other.map(|v| v.type_name()).unwrap_or("nothing"),
            ))
        }
    };
    Ok(Value::from_json(&crate::agent_api::ontology_describe_json(
        &q,
    )))
}

/// Pull a string field out of a caught-error record, accepting either the
/// wrapper form `{error: {...}}` that try/catch binds or the bare inner record.
fn diag_field<'a>(err: &'a BTreeMap<String, Value>, key: &str) -> Option<&'a Value> {
    if let Some(Value::Record(inner)) = err.get("error") {
        if let Some(v) = inner.get(key) {
            return Some(v);
        }
    }
    err.get(key)
}

/// diagnose(error) - The **minimal** repair context for a failed call.
///
/// Progressive disclosure applied to failure (§5.4): given the structured error
/// a `catch` block bound, return only what is needed to fix *this* call — the
/// code, whether retrying can help, the offending builtin's signature and effect
/// class, its required parameters, and one example — instead of making the agent
/// pay for a full `ontology_describe` dump or, worse, the whole ontology.
///
/// Deliberately returns *less* than `ontology_describe`: no prose description,
/// no category listing, at most one example. Unknown/absent builtin names yield
/// the code and hint alone rather than an invented suggestion.
fn bi_diagnose(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let subject = args.first().cloned().or(input);
    let err = match subject {
        Some(Value::Record(r)) => r,
        // A bare string is what a non-safety failure used to look like. Report
        // it honestly as uncoded rather than guessing a code from its prose.
        Some(Value::Str(s)) => {
            let mut out = BTreeMap::new();
            out.insert("code".to_string(), Value::Str("E_UNKNOWN".to_string()));
            out.insert("retryable".to_string(), Value::Bool(false));
            out.insert("message".to_string(), Value::Str(s));
            out.insert(
                "hint".to_string(),
                Value::Str(
                    "this failure carries no structured code; it cannot be \
                     repaired programmatically"
                        .to_string(),
                ),
            );
            return Ok(Value::Record(out));
        }
        other => {
            return Err(crate::safety::bad_arg(
                "diagnose",
                "error: Record (the value bound by catch)",
                other.map(|v| v.type_name()).unwrap_or("nothing"),
            ))
        }
    };

    let mut out = BTreeMap::new();
    let code = match diag_field(&err, "code") {
        Some(Value::Str(c)) => c.clone(),
        _ => "E_UNKNOWN".to_string(),
    };
    out.insert("code".to_string(), Value::Str(code.clone()));
    if let Some(v) = diag_field(&err, "retryable") {
        out.insert("retryable".to_string(), v.clone());
    }
    if let Some(v) = diag_field(&err, "hint") {
        out.insert("hint".to_string(), v.clone());
    }
    if let Some(v) = diag_field(&err, "did_you_mean") {
        out.insert("did_you_mean".to_string(), v.clone());
    }
    if let Some(v) = diag_field(&err, "approval") {
        out.insert("approval".to_string(), v.clone());
    }
    // The typed argument pair, when the failure carries one: an agent repairing a
    // `E_BAD_ARG` should not have to parse English to learn what shape was wanted.
    if let (Some(e), Some(g)) = (diag_field(&err, "expected"), diag_field(&err, "got")) {
        out.insert("expected".to_string(), e.clone());
        out.insert("got".to_string(), g.clone());
    }

    // The expensive part — the builtin's own contract — is fetched only when the
    // error actually names a builtin that exists.
    let name = match diag_field(&err, "builtin") {
        Some(Value::Str(b)) if !b.is_empty() => b.clone(),
        _ => return Ok(Value::Record(out)),
    };
    let def = crate::agent_api::ontology_describe_json(&name);
    if def.get("builtin").and_then(|v| v.as_str()).is_none() {
        // Named a builtin the ontology does not document: say so, don't invent.
        return Ok(Value::Record(out));
    }
    for key in ["builtin", "signature", "effect"] {
        if let Some(v) = def.get(key) {
            out.insert(key.to_string(), Value::from_json(v));
        }
    }
    // Whether re-running the *operation* is safe, which is a different question from
    // whether the *error* was transient (`retryable`). After a timeout an agent knows
    // the error may be worth retrying; only this says whether retrying can duplicate
    // the effect. Emitted only when it adds something `retryable` does not already
    // imply — a retryable error on an idempotent call is the uninteresting case.
    let idem = crate::safety::idempotent(&name);
    let err_retryable = matches!(out.get("retryable"), Some(Value::Bool(true)));
    if !idem || err_retryable {
        out.insert("idempotent".to_string(), Value::Bool(idem));
    }
    // A signature already spells out the parameters and the return type. Emitting
    // them again is pure duplication in the exact place we are trying to be cheap,
    // so the expanded forms appear only when there is no signature to read.
    let has_signature = matches!(out.get("signature"), Some(Value::Str(s)) if !s.is_empty());
    if !has_signature {
        if let Some(v) = def.get("return_type") {
            out.insert("return_type".to_string(), Value::from_json(v));
        }
    }
    if let Some(params) = def
        .get("parameters")
        .and_then(|v| v.as_array())
        .filter(|_| !has_signature)
    {
        // Compact: name:type, required-ness only — descriptions are prose the
        // repair does not need.
        let compact: Vec<Value> = params
            .iter()
            .map(|p| {
                let nm = p.get("name").and_then(|v| v.as_str()).unwrap_or("_");
                let ty = p.get("type").and_then(|v| v.as_str()).unwrap_or("Any");
                let req = p.get("required").and_then(|v| v.as_bool()).unwrap_or(false);
                Value::Str(format!("{}:{}{}", nm, ty, if req { "" } else { "?" }))
            })
            .collect();
        out.insert("parameters".to_string(), Value::Array(compact));
    }
    if let Some(ex) = def
        .get("examples")
        .and_then(|v| v.as_array())
        .and_then(|a| a.first())
        .and_then(|e| e.get("code"))
        .and_then(|c| c.as_str())
    {
        out.insert("example".to_string(), Value::Str(ex.to_string()));
    }
    Ok(Value::Record(out))
}

/// try_repair(code) - Run `code` so that a *failed* attempt leaves no trace.
///
/// The honest description: this does not invent a fix. It makes retrying safe.
/// A self-healing loop that re-runs a mutating batch is only sound if a failed
/// attempt is undone first — otherwise attempt N+1 starts from the debris of
/// attempt N and the failures compound. `try_repair` brackets the evaluation in
/// a named savepoint (§9) and, on failure, rolls back to it, so every attempt
/// starts from identical state.
///
/// Returns `{ok, value}` on success, or `{ok: false, restored, error, retryable}`
/// on failure — `error` being the same structured record `catch` would bind, so
/// it feeds straight into `diagnose()`. Rolls back only the ops *this* call
/// recorded: an enclosing transaction stays open and keeps its earlier work.
fn bi_try_repair(args: Vec<Value>, input: Option<Value>, env: &mut Env) -> Result<Value> {
    let code = match args.first().cloned().or(input) {
        Some(Value::Str(s)) => s,
        other => {
            return Err(crate::safety::bad_arg(
                "try_repair",
                "code: String",
                other.map(|v| v.type_name()).unwrap_or("nothing"),
            ))
        }
    };

    // Reuse an enclosing transaction when there is one (its earlier work must
    // survive); otherwise open one for the duration of the attempt.
    let owned = !crate::tx::is_active();
    if owned {
        crate::tx::begin().map_err(|e| anyhow!("try_repair: {}", e))?;
    }
    let mark = format!("__repair_{}", REPAIR_SEQ.fetch_add(1, Ordering::Relaxed));
    crate::tx::savepoint(&mark).map_err(|e| anyhow!("try_repair: {}", e))?;

    let result = (|| -> Result<Value> {
        let stmts = crate::parser::parse_program(&code)?;
        crate::eval::eval_program(&stmts, env)
    })();

    let mut out = BTreeMap::new();
    match result {
        Ok(v) => {
            if owned {
                crate::tx::commit().map_err(|e| anyhow!("try_repair: {}", e))?;
            }
            out.insert("ok".to_string(), Value::Bool(true));
            out.insert("value".to_string(), v);
        }
        Err(e) => {
            // Undo this attempt's mutations before reporting, so the caller's
            // next attempt starts from the same state this one did.
            let restored = crate::tx::rollback_to(&mark).unwrap_or(0);
            if owned {
                let _ = crate::tx::rollback();
            }
            // Every failure reaching here is structured (the builtin boundary
            // guarantees it), but a parse error raised before dispatch is not —
            // so pass it through the same net.
            let coded = crate::safety::ensure_structured("try_repair", e);
            let json = coded
                .downcast_ref::<crate::safety::SafetyError>()
                .map(|se| se.to_json())
                .unwrap_or(serde_json::Value::Null);
            // `to_json` wraps in `{error: {...}}`; unwrap it so the caller reads
            // `result.error.code`, not `result.error.error.code`.
            let structured = Value::from_json(json.get("error").unwrap_or(&json));
            let retryable = match &structured {
                Value::Record(r) => match r.get("retryable") {
                    Some(Value::Bool(b)) => *b,
                    _ => false,
                },
                _ => false,
            };
            out.insert("ok".to_string(), Value::Bool(false));
            out.insert("restored".to_string(), Value::Int(restored as i64));
            out.insert("retryable".to_string(), Value::Bool(retryable));
            out.insert("error".to_string(), structured);
        }
    }
    Ok(Value::Record(out))
}

/// Monotonic counter making each `try_repair` savepoint name unique, so nested
/// or sequential attempts cannot roll back to each other's mark.
static REPAIR_SEQ: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);

lazy_static::lazy_static! {
    /// The process-global RBAC manager backing the in-shell `rbac_*` builtins
    /// and the safety layer's principal authorization.
    static ref GLOBAL_RBAC: std::sync::Arc<crate::auth::RbacManager> =
        std::sync::Arc::new(crate::auth::RbacManager::new());
}

/// Return the global RBAC manager, (re-)installing it into the safety layer so
/// guarded builtins consult it. Idempotent; called by each `rbac_*` builtin.
fn global_rbac() -> std::sync::Arc<crate::auth::RbacManager> {
    let m = GLOBAL_RBAC.clone();
    crate::safety::set_rbac_manager(m.clone());
    m
}

/// rbac_principal(user_id?) - Set or get the current acting principal for safety
/// authorization. With an argument, sets the principal (creating the user if
/// needed) and activates RBAC; with none, returns the current principal or null.
fn bi_rbac_principal(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let mgr = global_rbac();
    match args.first() {
        Some(Value::Str(uid)) => {
            // Only the *setting* form is privileged; reading back the current
            // principal (the argless form below) is not, and an agent that
            // cannot ask what it is acting as will guess.
            crate::safety::guard(crate::safety::GuardCtx {
                builtin: "rbac_principal",
                effect: crate::safety::Effect::Privileged,
                what: "act as a different principal",
                targets: vec![uid.clone()],
                blast_radius: serde_json::json!({ "principal": true }),
                reversible: true,
                fs_paths: false,
            })?;
            if mgr.get_user(uid).is_none() {
                let mut u = crate::auth::User::new(uid.clone());
                u.id = uid.clone(); // use the id as the principal handle
                let _ = mgr.add_user(u);
            }
            crate::safety::set_principal(Some(uid.clone()));
            Ok(Value::Str(uid.clone()))
        }
        None | Some(Value::Null) => Ok(crate::safety::current_principal()
            .map(Value::Str)
            .unwrap_or(Value::Null)),
        _ => Err(anyhow!(
            "rbac_principal: expected a user id string or no argument"
        )),
    }
}

/// rbac_grant(user_id, permission) - Grant a direct permission (e.g.
/// "effect:destructive", "effect:*", "builtin:rm", "*:*") to a user so that,
/// when acting as that principal, guarded ops of that class bypass approval.
fn bi_rbac_grant(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let uid = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        _ => return Err(anyhow!("rbac_grant: expected a user id string")),
    };
    let perm = match args.get(1) {
        Some(Value::Str(s)) => s.clone(),
        _ => {
            return Err(anyhow!(
                "rbac_grant: expected a permission string, e.g. \"effect:destructive\""
            ))
        }
    };
    let mgr = global_rbac();
    let mut user = mgr.get_user(&uid).unwrap_or_else(|| {
        let mut u = crate::auth::User::new(uid.clone());
        u.id = uid.clone();
        u
    });
    user.permissions.insert(perm.clone());
    mgr.add_user(user)?;
    mgr.invalidate_user_cache(&uid);
    let mut rec = BTreeMap::new();
    rec.insert("user".to_string(), Value::Str(uid));
    rec.insert("granted".to_string(), Value::Str(perm));
    Ok(Value::Record(rec))
}

/// rbac_can(permission) - Whether the current principal holds `permission`
/// (resolving roles + wildcards). Returns false if no principal is set.
fn bi_rbac_can(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let perm = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        _ => return Err(anyhow!("rbac_can: expected a permission string")),
    };
    let mgr = global_rbac();
    let allowed = match crate::safety::current_principal() {
        Some(p) => mgr.check_permission(&p, &perm),
        None => false,
    };
    Ok(Value::Bool(allowed))
}

// ------------------------------------------------------------------------
// Interactive login (§7.1)
//
// `auth::AuthManager` -- registration, password verification, sessions, tokens,
// API keys, its own audit trail -- existed in full and had no caller anywhere
// in the crate. The only way to become a principal was `rbac_principal(id)`,
// which asserts an identity rather than proving one: any caller could name any
// user and be treated as them.
//
// These four builtins are that missing door. `rbac_login` proves the identity
// against a stored Argon2id hash before it touches `set_principal`, so the
// principal the guard trusts is one somebody authenticated as.
//
// They are `Privileged`, and therefore denied in agent mode: logging in is how
// authority is acquired, and an agent that could acquire authority on its own
// has none. An agent receives its principal from `AETHER_PRINCIPAL` or the RBAC
// config file at startup, chosen by whoever launched it.
// ------------------------------------------------------------------------

lazy_static::lazy_static! {
    /// The process-global authentication manager, sharing the RBAC store that
    /// the safety layer consults -- one user directory, not two.
    static ref GLOBAL_AUTH: std::sync::Arc<crate::auth::AuthManager> =
        std::sync::Arc::new(crate::auth::AuthManager::new(GLOBAL_RBAC.clone()));

    /// The session established by the last successful `rbac_login`.
    static ref LOGIN_SESSION: std::sync::Mutex<Option<LoginSession>> =
        std::sync::Mutex::new(None);
}

#[derive(Clone)]
struct LoginSession {
    session_id: String,
    user_id: String,
    username: String,
    expires_at: String,
}

/// Read a password from the argument if given, and interactively otherwise.
/// Refuses to prompt when stdin is not a terminal: a prompt nobody can answer
/// is a hang, and silently reading a password off a pipe is worse.
fn password_arg(args: &[Value], idx: usize, prompt: &str) -> Result<String> {
    if let Some(Value::Str(p)) = args.get(idx) {
        if p.is_empty() {
            return Err(anyhow!("an empty password is not a password"));
        }
        return Ok(p.clone());
    }
    use std::io::IsTerminal;
    if !std::io::stdin().is_terminal() {
        return Err(anyhow!(
            "no password given and stdin is not a terminal -- pass it as the second argument"
        ));
    }
    let got = bi_input_read_password(vec![Value::Str(prompt.to_string())], None)?;
    match got {
        Value::Str(p) if !p.is_empty() => Ok(p),
        _ => Err(anyhow!("no password entered")),
    }
}

/// rbac_register(username, password?) - Create a credentialed user. With no
/// password argument, prompts twice and requires the two to match. The password
/// is stored as an Argon2id PHC string, never in the clear and never as a bare
/// digest.
fn bi_rbac_register(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let username = match args.first() {
        Some(Value::Str(s)) if !s.is_empty() => s.clone(),
        _ => return Err(anyhow!("rbac_register: expected a username string")),
    };
    let password = password_arg(&args, 1, &format!("Password for {username}: "))?;
    if args.get(1).is_none() {
        let again = password_arg(&[], 0, "Repeat password: ")?;
        if again != password {
            return Err(anyhow!("rbac_register: the two passwords do not match"));
        }
    }
    let _ = global_rbac(); // install the shared store into the safety layer
    let user = GLOBAL_AUTH.register_user(&username, &password)?;
    let mut rec = BTreeMap::new();
    rec.insert("user".to_string(), Value::Str(user.username));
    rec.insert("user_id".to_string(), Value::Str(user.id));
    Ok(Value::Record(rec))
}

/// rbac_login(username, password?) - Authenticate and become that principal.
/// With no password argument, prompts (terminal only). On success the acting
/// principal is set to the authenticated user id, so RBAC grants apply to a
/// proven identity rather than an asserted one.
fn bi_rbac_login(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let username = match args.first() {
        Some(Value::Str(s)) if !s.is_empty() => s.clone(),
        _ => return Err(anyhow!("rbac_login: expected a username string")),
    };
    let password = password_arg(&args, 1, &format!("Password for {username}: "))?;
    let _ = global_rbac();
    let result = GLOBAL_AUTH.authenticate(crate::auth::Credential::Password {
        username: username.clone(),
        password,
    });
    if !result.success {
        // Deliberately unspecific: which half was wrong is the attacker's
        // question, and `AuthManager` has already recorded the detail in its
        // own audit log.
        return Err(anyhow!("rbac_login: invalid credentials"));
    }
    let user = result
        .user
        .ok_or_else(|| anyhow!("rbac_login: no user returned"))?;
    let session = result
        .session
        .ok_or_else(|| anyhow!("rbac_login: no session returned"))?;
    let expires_at = session.expires_at.to_rfc3339();
    crate::safety::set_principal(Some(user.id.clone()));
    if let Ok(mut g) = LOGIN_SESSION.lock() {
        *g = Some(LoginSession {
            session_id: session.id.clone(),
            user_id: user.id.clone(),
            username: user.username.clone(),
            expires_at: expires_at.clone(),
        });
    }
    let mut rec = BTreeMap::new();
    rec.insert("user".to_string(), Value::Str(user.username));
    rec.insert("user_id".to_string(), Value::Str(user.id));
    rec.insert("session".to_string(), Value::Str(session.id));
    rec.insert("expires_at".to_string(), Value::Str(expires_at));
    Ok(Value::Record(rec))
}

/// rbac_logout() - End the session and drop back to anonymous. Never gated:
/// giving up authority is the one privilege operation that cannot be an
/// escalation.
fn bi_rbac_logout(_args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let was = LOGIN_SESSION.lock().ok().and_then(|mut g| g.take());
    crate::safety::set_principal(None);
    match was {
        Some(s) => {
            let _ = GLOBAL_AUTH.logout(&s.session_id);
            Ok(Value::Bool(true))
        }
        None => Ok(Value::Bool(false)),
    }
}

/// rbac_session() - The current login session as a record, or null when
/// anonymous or expired. Read-only, so an agent can always ask who it is.
fn bi_rbac_session(_args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let Some(s) = LOGIN_SESSION.lock().ok().and_then(|g| g.clone()) else {
        return Ok(Value::Null);
    };
    // An expired session is not a session. Report it as gone and clear the
    // principal, rather than leaving the guard trusting a dead identity.
    if GLOBAL_AUTH.validate_session(&s.session_id).is_none() {
        let _ = bi_rbac_logout(vec![], None);
        return Ok(Value::Null);
    }
    let mut rec = BTreeMap::new();
    rec.insert("user".to_string(), Value::Str(s.username));
    rec.insert("user_id".to_string(), Value::Str(s.user_id));
    rec.insert("session".to_string(), Value::Str(s.session_id));
    rec.insert("expires_at".to_string(), Value::Str(s.expires_at));
    Ok(Value::Record(rec))
}

/// audit_tail(n?) - Return the most recent n audit entries (default 20) from the
/// active hash-chained log as an array of records, so an agent can review what
/// it did and what was allowed/denied/approved. Read-only.
fn bi_audit_tail(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let n = match args.first() {
        Some(Value::Int(k)) if *k >= 0 => *k as usize,
        _ => 20,
    };
    let entries: Vec<Value> = crate::safety::read_audit_tail(n)
        .iter()
        .map(Value::from_json)
        .collect();
    Ok(Value::Array(entries))
}

/// approve(token) - Grant a safety approval token in-process so a subsequent
/// guarded action bound to that token may proceed. Pairs with the
/// E_NEEDS_APPROVAL error returned by guarded builtins in agent mode (§7.2).
fn bi_approve(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let token = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        _ => return Err(anyhow!("approve: expected an approval token string")),
    };

    // The approver must not be the party being approved (AS-2026-02's sibling,
    // AS-2026-01).
    //
    // §5.3 grades `Destructive` and `Exec` as *approve* in agent mode, and §7.2
    // documents the loop as `E_NEEDS_APPROVAL` -> `approve(token)` -> re-run.
    // That loop is right for a human at a REPL and wrong for an agent, because
    // the agent holds the token it was just refused with: demonstrated in
    // `tests/approval_self_grant.rs`, where the denied call succeeds on retry.
    // Against an agent that errs the second step is a real speed bump; against
    // one that is adversarial or prompt-injected the `approve` cell is simply
    // `allow`.
    //
    // So the in-band path is refused in agent mode only. Human mode is
    // untouched, and the out-of-band channel the design already provides —
    // `AETHER_APPROVE` / `AETHER_APPROVE_ALL`, set by whoever launches the
    // agent — still works. No capability is removed that was not already
    // reachable by someone outside the agent's control.
    if crate::safety::current_mode() == crate::safety::Mode::Agent {
        return Err(anyhow::Error::new(crate::safety::SafetyError {
            code: crate::safety::ErrorCode::PolicyDeny,
            message: "approve: an agent may not approve its own call".to_string(),
            builtin: "approve".to_string(),
            hint: "the token was issued to the caller that was refused, so spending it \
                   here would make the approval gate self-service; approve out of band \
                   with AETHER_APPROVE=<token> (or AETHER_APPROVE_ALL=1 for trusted \
                   automation), which is set by whoever launched the agent"
                .to_string(),
            approval: None,
            did_you_mean: Vec::new(),
            expected: String::new(),
            got: String::new(),
        }));
    }

    crate::safety::grant_approval(&token);
    let mut rec = BTreeMap::new();
    rec.insert("approved".to_string(), Value::Bool(true));
    rec.insert("token".to_string(), Value::Str(token));
    Ok(Value::Record(rec))
}

/// audit_verify(path?) - Verify the tamper-evident, hash-chained audit log
/// (§7.5). With no argument, verifies the currently active log. Returns a
/// record {valid, entries, path} or {valid: false, error, path}.
fn bi_audit_verify(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let path = match args.first() {
        Some(Value::Str(s)) => std::path::PathBuf::from(s),
        _ => match crate::safety::audit_path() {
            Some(p) => p,
            None => return Err(anyhow!("audit_verify: no audit log is active; pass a path")),
        },
    };
    let mut rec = BTreeMap::new();
    rec.insert(
        "path".to_string(),
        Value::Str(path.to_string_lossy().to_string()),
    );
    match crate::safety::verify_audit(&path) {
        Ok(n) => {
            rec.insert("valid".to_string(), Value::Bool(true));
            rec.insert("entries".to_string(), Value::Int(n as i64));
        }
        Err(e) => {
            rec.insert("valid".to_string(), Value::Bool(false));
            rec.insert("error".to_string(), Value::Str(e));
        }
    }
    Ok(Value::Record(rec))
}

/// now() - Get current Unix timestamp in seconds
fn bi_now(_args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    use std::time::{SystemTime, UNIX_EPOCH};
    let duration = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map_err(|e| anyhow!("now: system time error: {}", e))?;
    Ok(Value::Int(duration.as_secs() as i64))
}

/// sort_by(fn, direction?) - Sort array by key function
/// Usage: arr | sort_by(fn(x) => x.name) or arr | sort_by(fn(x) => x.size, "desc")
fn bi_sort_by(args: Vec<Value>, input: Option<Value>, env: &mut Env) -> Result<Value> {
    let arr = input
        .as_ref()
        .and_then(|v| match v {
            Value::Array(a) => Some(a.as_slice()),
            _ => None,
        })
        .or_else(|| {
            args.first().and_then(|v| match v {
                Value::Array(a) => Some(a.as_slice()),
                _ => None,
            })
        })
        .ok_or_else(|| crate::safety::arg_err("sort_by requires array input"))?;

    let lambda = args.iter().find_map(|v| match v {
        Value::Lambda(l) => Some(l),
        _ => None,
    });

    let descending = args.iter().any(|v| match v {
        Value::Str(s) => s == "desc" || s == "descending",
        _ => false,
    });

    // A bare field name is accepted as the sort key: `sort_by("size")` rather
    // than `sort_by(fn(f) => f.size)`.
    //
    // Added after hitting this while using the shell as an agent. The string
    // form is what most callers reach for first, and it previously failed
    // twice over: the argument was silently ignored (only "desc"/"descending"
    // were recognised), and the call then errored for want of a lambda — one
    // wasted round-trip on a call that read as obviously correct.
    //
    // "desc"/"descending" stay reserved as the direction, so a field actually
    // named that must use the lambda form. Stated rather than papered over.
    let field = args.iter().find_map(|v| match v {
        Value::Str(s) if s != "desc" && s != "descending" => Some(s.clone()),
        _ => None,
    });

    if lambda.is_none() && field.is_none() {
        return Err(crate::safety::bad_arg(
            "sort_by",
            "a key: either a field name (\"size\") or a lambda (fn(x) => x.size)",
            "neither",
        ));
    }

    // Extract keys for each element
    let mut keyed: Vec<(Value, Value)> = arr
        .iter()
        .map(|item| {
            let key = match (&lambda, &field) {
                (Some(l), _) => call_lambda(l, &[item.clone()], env).unwrap_or(Value::Null),
                (None, Some(f)) => match item {
                    Value::Record(m) => m.get(f).cloned().unwrap_or(Value::Null),
                    _ => Value::Null,
                },
                (None, None) => Value::Null,
            };
            (key, item.clone())
        })
        .collect();

    // Sort by keys
    keyed.sort_by(|(a, _), (b, _)| {
        let cmp = sort_compare_values(a, b);
        if descending {
            cmp.reverse()
        } else {
            cmp
        }
    });

    let result: Vec<Value> = keyed.into_iter().map(|(_, v)| v).collect();
    Ok(Value::Array(result))
}

/// Helper to compare two values for sorting
fn sort_compare_values(a: &Value, b: &Value) -> std::cmp::Ordering {
    use std::cmp::Ordering;
    match (a, b) {
        (Value::Int(x), Value::Int(y)) => x.cmp(y),
        (Value::Float(x), Value::Float(y)) => x.partial_cmp(y).unwrap_or(Ordering::Equal),
        (Value::Int(x), Value::Float(y)) => (*x as f64).partial_cmp(y).unwrap_or(Ordering::Equal),
        (Value::Float(x), Value::Int(y)) => x.partial_cmp(&(*y as f64)).unwrap_or(Ordering::Equal),
        (Value::Str(x), Value::Str(y)) => x.cmp(y),
        (Value::Bool(x), Value::Bool(y)) => x.cmp(y),
        _ => Ordering::Equal,
    }
}

/// save_json(path, value?) - Save value as JSON to file
/// Usage: data | save_json("output.json") or save_json("output.json", data)
fn bi_save_json(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    if args.is_empty() {
        return Err(crate::safety::arg_err("save_json requires a file path"));
    }

    let path = match &args[0] {
        Value::Str(s) => s.clone(),
        _ => return Err(anyhow!("save_json: path must be a string")),
    };

    let value = if args.len() > 1 {
        args[1].clone()
    } else {
        input.ok_or_else(|| crate::safety::arg_err("save_json requires a value to save"))?
    };

    // Convert Value to JSON using existing function
    let json = value_to_json(value);
    let json_str = serde_json::to_string_pretty(&json)
        .map_err(|e| anyhow!("save_json: JSON serialization failed: {}", e))?;

    // Write to file
    fs::write(&path, &json_str)
        .with_context(|| format!("save_json: failed to write to '{}'", path))?;

    let mut record = BTreeMap::new();
    record.insert("path".to_string(), Value::Str(path));
    record.insert("bytes".to_string(), Value::Int(json_str.len() as i64));
    record.insert("success".to_string(), Value::Bool(true));

    Ok(Value::Record(record))
}

/// mcp_server_start(config) - Start a custom MCP server
/// Usage: mcp_server_start({name: "fs", type: "builtin", config: {...}})
fn bi_mcp_server_start(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    if args.is_empty() {
        return Err(crate::safety::arg_err(
            "mcp_server_start requires a configuration record",
        ));
    }

    let config = match &args[0] {
        Value::Record(r) => r,
        _ => return Err(anyhow!("mcp_server_start: config must be a record")),
    };

    let name = config
        .get("name")
        .and_then(|v| match v {
            Value::Str(s) => Some(s.clone()),
            _ => None,
        })
        .unwrap_or_else(|| "default".to_string());

    let server_type = config
        .get("type")
        .and_then(|v| match v {
            Value::Str(s) => Some(s.clone()),
            _ => None,
        })
        .unwrap_or_else(|| "builtin".to_string());

    // Generate a unique endpoint
    let port = 3000
        + (std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map(|d| d.as_millis() as u16 % 1000)
            .unwrap_or(0));
    let endpoint = format!("http://localhost:{}", port);

    // Create server info record
    let mut result = BTreeMap::new();
    result.insert("name".to_string(), Value::Str(name));
    result.insert("type".to_string(), Value::Str(server_type));
    result.insert("endpoint".to_string(), Value::Str(endpoint));
    result.insert("port".to_string(), Value::Int(port as i64));
    result.insert("status".to_string(), Value::Str("started".to_string()));

    // Include original config
    if let Some(inner_config) = config.get("config") {
        result.insert("config".to_string(), inner_config.clone());
    }

    Ok(Value::Record(result))
}

/// agent_with_mcp(goal, tools, endpoint) - Create agent with MCP tool access
/// Usage: agent_with_mcp("Task description", ["mcp:read_file", "mcp:list_dir"], server.endpoint)
fn bi_agent_with_mcp(args: Vec<Value>, _input: Option<Value>, env: &mut Env) -> Result<Value> {
    if args.len() < 2 {
        return Err(crate::safety::arg_err(
            "agent_with_mcp requires goal and tools array",
        ));
    }

    let goal = match &args[0] {
        Value::Str(s) => s.clone(),
        _ => return Err(anyhow!("agent_with_mcp: goal must be a string")),
    };

    let tools: Vec<String> = match &args[1] {
        Value::Array(arr) => arr
            .iter()
            .filter_map(|v| match v {
                Value::Str(s) => Some(s.clone()),
                _ => None,
            })
            .collect(),
        _ => return Err(anyhow!("agent_with_mcp: tools must be an array of strings")),
    };

    let endpoint = if args.len() > 2 {
        match &args[2] {
            Value::Str(s) => Some(s.clone()),
            Value::Array(endpoints) => {
                // Multiple endpoints - join them
                let eps: Vec<String> = endpoints
                    .iter()
                    .filter_map(|v| match v {
                        Value::Str(s) => Some(s.clone()),
                        _ => None,
                    })
                    .collect();
                Some(eps.join(","))
            }
            _ => None,
        }
    } else {
        None
    };

    // Create agent wrapper with MCP capabilities
    let mut agent_record = BTreeMap::new();
    agent_record.insert("goal".to_string(), Value::Str(goal.clone()));
    agent_record.insert(
        "tools".to_string(),
        Value::Array(tools.iter().map(|s| Value::Str(s.clone())).collect()),
    );
    agent_record.insert("type".to_string(), Value::Str("mcp_agent".to_string()));

    if let Some(ep) = &endpoint {
        agent_record.insert("endpoint".to_string(), Value::Str(ep.clone()));
    }

    // Extract base tool names (remove mcp: prefix)
    let base_tools: Vec<&str> = tools
        .iter()
        .map(|s| s.strip_prefix("mcp:").unwrap_or(s.as_str()))
        .collect();

    // Run the agent with the goal
    let dry_run = false;
    let max_steps = 10;
    let result = crate::ai::agents::swarm::run_sync(&goal, &base_tools, max_steps, dry_run, env)?;

    agent_record.insert("result".to_string(), Value::Str(result));
    agent_record.insert("status".to_string(), Value::Str("completed".to_string()));

    Ok(Value::Record(agent_record))
}

/// each(fn) - Like map but for side effects, returns original array
/// Usage: arr | each(fn(x) => print(x))
fn bi_each(args: Vec<Value>, input: Option<Value>, env: &mut Env) -> Result<Value> {
    let arr = input
        .as_ref()
        .and_then(|v| match v {
            Value::Array(a) => Some(a.clone()),
            _ => None,
        })
        .or_else(|| {
            args.first().and_then(|v| match v {
                Value::Array(a) => Some(a.clone()),
                _ => None,
            })
        })
        .ok_or_else(|| crate::safety::arg_err("each requires array input"))?;

    let lambda = args
        .iter()
        .find_map(|v| match v {
            Value::Lambda(l) => Some(l),
            _ => None,
        })
        .ok_or_else(|| crate::safety::arg_err("each requires a lambda function"))?;

    // Apply lambda to each element for side effects
    for item in &arr {
        let _ = call_lambda(lambda, &[item.clone()], env);
    }

    // Return original array
    Ok(Value::Array(arr))
}

/// in(value, collection) - Check if value is in collection
/// Usage: "x" | in(["a", "b", "x"]) or in("x", ["a", "b", "x"])
fn bi_in(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let (needle, haystack) = if let Some(ref inp) = input {
        if args.is_empty() {
            return Err(crate::safety::arg_err("in requires a collection to search"));
        }
        (inp, &args[0])
    } else {
        if args.len() < 2 {
            return Err(crate::safety::arg_err("in requires value and collection"));
        }
        (&args[0], &args[1])
    };

    let found = match haystack {
        Value::Array(arr) => arr.iter().any(|v| values_equal(needle, v)),
        Value::Str(s) => {
            if let Value::Str(n) = needle {
                s.contains(n.as_str())
            } else {
                false
            }
        }
        Value::Record(rec) => {
            if let Value::Str(key) = needle {
                rec.contains_key(key)
            } else {
                false
            }
        }
        _ => false,
    };

    Ok(Value::Bool(found))
}

/// Check if two values are equal
fn values_equal(a: &Value, b: &Value) -> bool {
    match (a, b) {
        (Value::Null, Value::Null) => true,
        (Value::Bool(x), Value::Bool(y)) => x == y,
        (Value::Int(x), Value::Int(y)) => x == y,
        (Value::Float(x), Value::Float(y)) => (x - y).abs() < f64::EPSILON,
        (Value::Int(x), Value::Float(y)) | (Value::Float(y), Value::Int(x)) => {
            (*x as f64 - y).abs() < f64::EPSILON
        }
        (Value::Str(x), Value::Str(y)) => x == y,
        (Value::Array(x), Value::Array(y)) => {
            x.len() == y.len() && x.iter().zip(y.iter()).all(|(a, b)| values_equal(a, b))
        }
        _ => false,
    }
}

// ===================== Enterprise Feature Implementations =====================

/// role_create(name, permissions, description?) - Create a new RBAC role
fn bi_role_create(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let name = input
        .or_else(|| args.first().cloned())
        .map(|v| v.to_display_string())
        .ok_or_else(|| crate::safety::arg_err("role_create: missing 'name'"))?;

    let permissions = args
        .get(1)
        .and_then(|v| match v {
            Value::Array(arr) => Some(
                arr.iter()
                    .filter_map(|p| {
                        if let Value::Record(rec) = p {
                            let resource = rec.get("resource").map(|v| v.to_display_string())?;
                            let actions = rec
                                .get("actions")
                                .and_then(|v| match v {
                                    Value::Array(a) => {
                                        Some(a.iter().map(|v| v.to_display_string()).collect())
                                    }
                                    _ => None,
                                })
                                .unwrap_or_default();
                            Some(Permission { resource, actions })
                        } else {
                            None
                        }
                    })
                    .collect::<Vec<_>>(),
            ),
            _ => None,
        })
        .unwrap_or_default();

    let description = args
        .get(2)
        .map(|v| v.to_display_string())
        .unwrap_or_default();

    let role = Role {
        name: name.clone(),
        permissions,
        description,
        created_at: std::time::Instant::now(),
    };

    RBAC_ROLES.write().unwrap().insert(name.clone(), role);

    let mut result = BTreeMap::new();
    result.insert("status".to_string(), Value::Str("created".to_string()));
    result.insert("role".to_string(), Value::Str(name));
    Ok(Value::Record(result))
}

/// role_delete(name) - Delete an RBAC role
fn bi_role_delete(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let name = input
        .or_else(|| args.first().cloned())
        .map(|v| v.to_display_string())
        .ok_or_else(|| crate::safety::arg_err("role_delete: missing 'name'"))?;

    let existed = RBAC_ROLES.write().unwrap().remove(&name).is_some();

    let mut result = BTreeMap::new();
    result.insert(
        "status".to_string(),
        Value::Str(if existed { "deleted" } else { "not_found" }.to_string()),
    );
    result.insert("role".to_string(), Value::Str(name));
    Ok(Value::Record(result))
}

/// role_grant(user, role) - Grant a role to a user
fn bi_role_grant(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    if args.len() < 2 {
        return Err(crate::safety::arg_err(
            "role_grant: requires user and role arguments",
        ));
    }
    let user = args[0].to_display_string();
    let role = args[1].to_display_string();

    if !RBAC_ROLES.read().unwrap().contains_key(&role) {
        return Err(anyhow!("role_grant: role '{}' does not exist", role));
    }

    USER_ROLES
        .write()
        .unwrap()
        .entry(user.clone())
        .or_default()
        .push(role.clone());

    let mut result = BTreeMap::new();
    result.insert("status".to_string(), Value::Str("granted".to_string()));
    result.insert("user".to_string(), Value::Str(user));
    result.insert("role".to_string(), Value::Str(role));
    Ok(Value::Record(result))
}

/// role_revoke(user, role) - Revoke a role from a user
fn bi_role_revoke(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    if args.len() < 2 {
        return Err(crate::safety::arg_err(
            "role_revoke: requires user and role arguments",
        ));
    }
    let user = args[0].to_display_string();
    let role = args[1].to_display_string();

    let mut user_roles = USER_ROLES.write().unwrap();
    let revoked = if let Some(roles) = user_roles.get_mut(&user) {
        let before = roles.len();
        roles.retain(|r| r != &role);
        roles.len() < before
    } else {
        false
    };

    let mut result = BTreeMap::new();
    result.insert(
        "status".to_string(),
        Value::Str(if revoked { "revoked" } else { "not_found" }.to_string()),
    );
    result.insert("user".to_string(), Value::Str(user));
    result.insert("role".to_string(), Value::Str(role));
    Ok(Value::Record(result))
}

/// user_roles(user) - Get roles assigned to a user
fn bi_user_roles(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let user = input
        .or_else(|| args.first().cloned())
        .map(|v| v.to_display_string())
        .ok_or_else(|| crate::safety::arg_err("user_roles: missing 'user'"))?;

    let roles = USER_ROLES
        .read()
        .unwrap()
        .get(&user)
        .cloned()
        .unwrap_or_default();

    Ok(Value::Array(roles.into_iter().map(Value::Str).collect()))
}

/// check_permission(user, resource, action) - Check if user has permission
fn bi_check_permission(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    if args.len() < 3 {
        return Err(anyhow!(
            "check_permission: requires user, resource, and action arguments"
        ));
    }
    let user = args[0].to_display_string();
    let resource = args[1].to_display_string();
    let action = args[2].to_display_string();

    let user_roles_guard = USER_ROLES.read().unwrap();
    let roles_guard = RBAC_ROLES.read().unwrap();

    let user_role_names = user_roles_guard.get(&user).cloned().unwrap_or_default();

    let has_permission = user_role_names.iter().any(|role_name| {
        if let Some(role) = roles_guard.get(role_name) {
            role.permissions.iter().any(|p| {
                (p.resource == "*" || p.resource == resource)
                    && (p.actions.contains(&"*".to_string())
                        || p.actions.iter().any(|a| a == &action))
            })
        } else {
            false
        }
    });

    Ok(Value::Bool(has_permission))
}

/// roles_list() - List all defined roles
fn bi_roles_list(_args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let roles = RBAC_ROLES.read().unwrap();

    let result: Vec<Value> = roles
        .values()
        .map(|role| {
            let mut rec = BTreeMap::new();
            rec.insert("name".to_string(), Value::Str(role.name.clone()));
            rec.insert(
                "description".to_string(),
                Value::Str(role.description.clone()),
            );
            rec.insert(
                "permissions".to_string(),
                Value::Int(role.permissions.len() as i64),
            );
            Value::Record(rec)
        })
        .collect();

    Ok(Value::Array(result))
}
/// audit_log(action, resource, details?, severity?) - Log an audit entry
fn bi_audit_log(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    if args.len() < 2 {
        return Err(crate::safety::arg_err(
            "audit_log: requires action and resource arguments",
        ));
    }
    let action = args[0].to_display_string();
    let resource = args[1].to_display_string();
    let details = args
        .get(2)
        .map(|v| v.to_display_string())
        .unwrap_or_default();
    let severity_str = args
        .get(3)
        .map(|v| v.to_display_string())
        .unwrap_or_else(|| "info".to_string());

    let severity = match severity_str.to_lowercase().as_str() {
        "warning" => AuditSeverity::Warning,
        "critical" => AuditSeverity::Critical,
        _ => AuditSeverity::Info,
    };

    let id = format!(
        "audit_{}",
        std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_nanos()
    );

    let entry = AuditEntry {
        id: id.clone(),
        timestamp: std::time::Instant::now(),
        user: std::env::var("USER").unwrap_or_else(|_| "system".to_string()),
        action,
        resource,
        details,
        severity,
        success: true,
    };

    AUDIT_LOG.write().unwrap().push(entry);

    let mut result = BTreeMap::new();
    result.insert("status".to_string(), Value::Str("logged".to_string()));
    result.insert("id".to_string(), Value::Str(id));
    Ok(Value::Record(result))
}

/// audit_query(filter?) - Query audit log entries
fn bi_audit_query(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let filter = args.first().and_then(|v| {
        if let Value::Record(rec) = v {
            Some(rec.clone())
        } else {
            None
        }
    });

    let log = AUDIT_LOG.read().unwrap();

    let entries: Vec<Value> = log
        .iter()
        .filter(|e| {
            if let Some(ref f) = filter {
                let action_match = f
                    .get("action")
                    .map(|v| e.action.contains(&v.to_display_string()))
                    .unwrap_or(true);
                let resource_match = f
                    .get("resource")
                    .map(|v| e.resource.contains(&v.to_display_string()))
                    .unwrap_or(true);
                action_match && resource_match
            } else {
                true
            }
        })
        .map(|e| {
            let mut rec = BTreeMap::new();
            rec.insert("id".to_string(), Value::Str(e.id.clone()));
            rec.insert("user".to_string(), Value::Str(e.user.clone()));
            rec.insert("action".to_string(), Value::Str(e.action.clone()));
            rec.insert("resource".to_string(), Value::Str(e.resource.clone()));
            rec.insert(
                "severity".to_string(),
                Value::Str(e.severity.as_str().to_string()),
            );
            rec.insert("success".to_string(), Value::Bool(e.success));
            Value::Record(rec)
        })
        .collect();

    Ok(Value::Array(entries))
}

/// audit_export(format?) - Export audit log
fn bi_audit_export(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let format = args
        .first()
        .map(|v| v.to_display_string())
        .unwrap_or_else(|| "json".to_string());

    let log = AUDIT_LOG.read().unwrap();

    let entries: Vec<Value> = log
        .iter()
        .map(|e| {
            let mut rec = BTreeMap::new();
            rec.insert("id".to_string(), Value::Str(e.id.clone()));
            rec.insert("user".to_string(), Value::Str(e.user.clone()));
            rec.insert("action".to_string(), Value::Str(e.action.clone()));
            rec.insert("resource".to_string(), Value::Str(e.resource.clone()));
            rec.insert("details".to_string(), Value::Str(e.details.clone()));
            rec.insert(
                "severity".to_string(),
                Value::Str(e.severity.as_str().to_string()),
            );
            rec.insert("success".to_string(), Value::Bool(e.success));
            Value::Record(rec)
        })
        .collect();

    let mut result = BTreeMap::new();
    result.insert("format".to_string(), Value::Str(format));
    result.insert("count".to_string(), Value::Int(entries.len() as i64));
    result.insert("entries".to_string(), Value::Array(entries));
    Ok(Value::Record(result))
}

/// audit_stats() - Get audit log statistics
fn bi_audit_stats(_args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let log = AUDIT_LOG.read().unwrap();

    let total = log.len();
    let mut info_count = 0;
    let mut warning_count = 0;
    let mut critical_count = 0;

    for entry in log.iter() {
        match entry.severity {
            AuditSeverity::Info => info_count += 1,
            AuditSeverity::Warning => warning_count += 1,
            AuditSeverity::Critical => critical_count += 1,
        }
    }

    let mut result = BTreeMap::new();
    result.insert("total".to_string(), Value::Int(total as i64));
    result.insert("info".to_string(), Value::Int(info_count));
    result.insert("warning".to_string(), Value::Int(warning_count));
    result.insert("critical".to_string(), Value::Int(critical_count));
    Ok(Value::Record(result))
}
/// sso_init(provider, client_id, issuer_url) - Initialize SSO configuration
fn bi_sso_init(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    if args.len() < 3 {
        return Err(anyhow!(
            "sso_init: requires provider, client_id, and issuer_url arguments"
        ));
    }
    let provider_str = args[0].to_display_string();
    let client_id = args[1].to_display_string();
    let issuer_url = args[2].to_display_string();

    let provider = SsoProvider::from_str(&provider_str).ok_or_else(|| {
        anyhow!(
            "sso_init: invalid provider '{}' (use oauth2, saml, or oidc)",
            provider_str
        )
    })?;

    let config = SsoConfig {
        provider,
        client_id,
        issuer_url,
        enabled: true,
    };

    *SSO_CONFIG.write().unwrap() = Some(config);

    let mut result = BTreeMap::new();
    result.insert("status".to_string(), Value::Str("initialized".to_string()));
    result.insert("provider".to_string(), Value::Str(provider_str));
    Ok(Value::Record(result))
}

/// sso_auth(callback_data) - Authenticate via SSO
fn bi_sso_auth(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let callback = input
        .or_else(|| args.first().cloned())
        .map(|v| v.to_display_string())
        .ok_or_else(|| crate::safety::arg_err("sso_auth: missing callback data"))?;

    let config = SSO_CONFIG.read().unwrap();
    if config.is_none() {
        return Err(anyhow!("sso_auth: SSO not initialized"));
    }

    let token = format!(
        "sso_token_{}",
        std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_nanos()
    );
    let user_id = format!("user_{}", callback.len());

    let session = SsoSession {
        token: token.clone(),
        user_id: user_id.clone(),
        created_at: std::time::Instant::now(),
        expires_at: std::time::Instant::now() + std::time::Duration::from_secs(3600),
    };

    SSO_SESSIONS.write().unwrap().insert(token.clone(), session);

    let mut result = BTreeMap::new();
    result.insert(
        "status".to_string(),
        Value::Str("authenticated".to_string()),
    );
    result.insert("token".to_string(), Value::Str(token));
    result.insert("user_id".to_string(), Value::Str(user_id));
    Ok(Value::Record(result))
}

/// sso_validate(token) - Validate an SSO token
fn bi_sso_validate(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let token = input
        .or_else(|| args.first().cloned())
        .map(|v| v.to_display_string())
        .ok_or_else(|| crate::safety::arg_err("sso_validate: missing 'token'"))?;

    let sessions = SSO_SESSIONS.read().unwrap();
    let session = sessions.get(&token);

    let (valid, user_id) = if let Some(s) = session {
        if std::time::Instant::now() < s.expires_at {
            (true, Some(s.user_id.clone()))
        } else {
            (false, None)
        }
    } else {
        (false, None)
    };

    let mut result = BTreeMap::new();
    result.insert("valid".to_string(), Value::Bool(valid));
    if let Some(uid) = user_id {
        result.insert("user_id".to_string(), Value::Str(uid));
    }
    Ok(Value::Record(result))
}

/// sso_logout(token) - Logout/invalidate an SSO session
fn bi_sso_logout(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let token = input
        .or_else(|| args.first().cloned())
        .map(|v| v.to_display_string())
        .ok_or_else(|| crate::safety::arg_err("sso_logout: missing 'token'"))?;

    let removed = SSO_SESSIONS.write().unwrap().remove(&token).is_some();

    let mut result = BTreeMap::new();
    result.insert(
        "status".to_string(),
        Value::Str(if removed { "logged_out" } else { "not_found" }.to_string()),
    );
    Ok(Value::Record(result))
}

/// sso_status() - Get SSO configuration status
fn bi_sso_status(_args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let config = SSO_CONFIG.read().unwrap();
    let sessions = SSO_SESSIONS.read().unwrap();

    let mut result = BTreeMap::new();
    if let Some(ref c) = *config {
        result.insert("configured".to_string(), Value::Bool(true));
        result.insert(
            "provider".to_string(),
            Value::Str(c.provider.as_str().to_string()),
        );
        result.insert("enabled".to_string(), Value::Bool(c.enabled));
        result.insert(
            "active_sessions".to_string(),
            Value::Int(sessions.len() as i64),
        );
    } else {
        result.insert("configured".to_string(), Value::Bool(false));
    }
    Ok(Value::Record(result))
}
/// compliance_check(standard, scope?) - Run compliance check
fn bi_compliance_check(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let standard_str = input
        .or_else(|| args.first().cloned())
        .map(|v| v.to_display_string())
        .ok_or_else(|| crate::safety::arg_err("compliance_check: missing 'standard'"))?;

    let standard = ComplianceStandard::from_str(&standard_str).ok_or_else(|| {
        anyhow!(
            "compliance_check: invalid standard '{}' (use GDPR, HIPAA, SOC2, or PCI)",
            standard_str
        )
    })?;

    let scope = args
        .get(1)
        .map(|v| v.to_display_string())
        .unwrap_or_else(|| "all".to_string());

    let checks = [
        ("data_encryption", true),
        ("access_logging", !AUDIT_LOG.read().unwrap().is_empty()),
        ("role_based_access", !RBAC_ROLES.read().unwrap().is_empty()),
        ("session_management", SSO_CONFIG.read().unwrap().is_some()),
    ];

    let passed: Vec<Value> = checks
        .iter()
        .filter(|(_, v)| *v)
        .map(|(k, _)| Value::Str(k.to_string()))
        .collect();
    let failed: Vec<Value> = checks
        .iter()
        .filter(|(_, v)| !*v)
        .map(|(k, _)| Value::Str(k.to_string()))
        .collect();

    let mut result = BTreeMap::new();
    result.insert(
        "standard".to_string(),
        Value::Str(standard.as_str().to_string()),
    );
    result.insert("scope".to_string(), Value::Str(scope));
    result.insert("passed".to_string(), Value::Array(passed));
    result.insert("failed".to_string(), Value::Array(failed));
    result.insert(
        "compliant".to_string(),
        Value::Bool(checks.iter().all(|(_, v)| *v)),
    );
    Ok(Value::Record(result))
}

/// compliance_report(standard) - Generate compliance report
fn bi_compliance_report(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let standard_str = input
        .or_else(|| args.first().cloned())
        .map(|v| v.to_display_string())
        .ok_or_else(|| crate::safety::arg_err("compliance_report: missing 'standard'"))?;

    let standard = ComplianceStandard::from_str(&standard_str)
        .ok_or_else(|| anyhow!("compliance_report: invalid standard '{}'", standard_str))?;

    let audit_count = AUDIT_LOG.read().unwrap().len();
    let role_count = RBAC_ROLES.read().unwrap().len();
    let sso_enabled = SSO_CONFIG.read().unwrap().is_some();

    let mut result = BTreeMap::new();
    result.insert(
        "standard".to_string(),
        Value::Str(standard.as_str().to_string()),
    );
    result.insert(
        "generated_at".to_string(),
        Value::Str(chrono::Utc::now().to_rfc3339()),
    );
    result.insert("audit_entries".to_string(), Value::Int(audit_count as i64));
    result.insert("roles_defined".to_string(), Value::Int(role_count as i64));
    result.insert("sso_enabled".to_string(), Value::Bool(sso_enabled));
    Ok(Value::Record(result))
}
/// finetune_start(model, dataset, config?) - Start a fine-tuning job
fn bi_finetune_start(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    if args.len() < 2 {
        return Err(anyhow!(
            "finetune_start: requires model and dataset arguments"
        ));
    }
    let model = args[0].to_display_string();
    let dataset = args[1].to_display_string();

    let config: HashMap<String, String> = args
        .get(2)
        .and_then(|v| {
            if let Value::Record(rec) = v {
                Some(
                    rec.iter()
                        .map(|(k, v)| (k.clone(), v.to_display_string()))
                        .collect(),
                )
            } else {
                None
            }
        })
        .unwrap_or_default();

    let id = format!(
        "ft_{}",
        std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_millis()
    );

    let job = FinetuneJob {
        id: id.clone(),
        model: model.clone(),
        dataset: dataset.clone(),
        status: FinetuneStatus::Pending,
        created_at: std::time::Instant::now(),
        config,
    };

    FINETUNE_JOBS.write().unwrap().insert(id.clone(), job);

    let mut result = BTreeMap::new();
    result.insert("status".to_string(), Value::Str("started".to_string()));
    result.insert("job_id".to_string(), Value::Str(id));
    result.insert("model".to_string(), Value::Str(model));
    result.insert("dataset".to_string(), Value::Str(dataset));
    Ok(Value::Record(result))
}

/// finetune_status(job_id) - Get status of a fine-tuning job
fn bi_finetune_status(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let job_id = input
        .or_else(|| args.first().cloned())
        .map(|v| v.to_display_string())
        .ok_or_else(|| crate::safety::arg_err("finetune_status: missing 'job_id'"))?;

    let jobs = FINETUNE_JOBS.read().unwrap();
    let job = jobs
        .get(&job_id)
        .ok_or_else(|| anyhow!("finetune_status: job '{}' not found", job_id))?;

    let mut result = BTreeMap::new();
    result.insert("job_id".to_string(), Value::Str(job.id.clone()));
    result.insert("model".to_string(), Value::Str(job.model.clone()));
    result.insert("dataset".to_string(), Value::Str(job.dataset.clone()));
    result.insert(
        "status".to_string(),
        Value::Str(job.status.as_str().to_string()),
    );
    Ok(Value::Record(result))
}

/// finetune_list() - List all fine-tuning jobs
fn bi_finetune_list(_args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let jobs = FINETUNE_JOBS.read().unwrap();

    let result: Vec<Value> = jobs
        .values()
        .map(|job| {
            let mut rec = BTreeMap::new();
            rec.insert("job_id".to_string(), Value::Str(job.id.clone()));
            rec.insert("model".to_string(), Value::Str(job.model.clone()));
            rec.insert("dataset".to_string(), Value::Str(job.dataset.clone()));
            rec.insert(
                "status".to_string(),
                Value::Str(job.status.as_str().to_string()),
            );
            Value::Record(rec)
        })
        .collect();

    Ok(Value::Array(result))
}

/// finetune_cancel(job_id) - Cancel a fine-tuning job
fn bi_finetune_cancel(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let job_id = input
        .or_else(|| args.first().cloned())
        .map(|v| v.to_display_string())
        .ok_or_else(|| crate::safety::arg_err("finetune_cancel: missing 'job_id'"))?;

    let mut jobs = FINETUNE_JOBS.write().unwrap();

    if let Some(job) = jobs.get_mut(&job_id) {
        match job.status {
            FinetuneStatus::Pending | FinetuneStatus::Training => {
                job.status = FinetuneStatus::Cancelled;
                let mut result = BTreeMap::new();
                result.insert("status".to_string(), Value::Str("cancelled".to_string()));
                result.insert("job_id".to_string(), Value::Str(job_id));
                Ok(Value::Record(result))
            }
            _ => Err(anyhow!(
                "finetune_cancel: job '{}' cannot be cancelled (status: {})",
                job_id,
                job.status.as_str()
            )),
        }
    } else {
        Err(anyhow!("finetune_cancel: job '{}' not found", job_id))
    }
}

// ===================== A2UI (Agent-to-User Interface) Builtins =====================

/// a2ui_notify(message, {level: "info"|"success"|"warning"|"error"}) - Send notification to user
fn bi_a2ui_notify(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let message = input
        .or_else(|| args.first().cloned())
        .map(|v| v.to_display_string())
        .ok_or_else(|| crate::safety::arg_err("a2ui_notify: missing message"))?;

    let level = args
        .get(1)
        .and_then(|v| {
            if let Value::Record(r) = v {
                r.get("level").map(|l| l.to_display_string())
            } else if let Value::Str(s) = v {
                Some(s.clone())
            } else {
                None
            }
        })
        .unwrap_or_else(|| "info".to_string())
        .parse::<NotificationLevel>()
        .unwrap_or(NotificationLevel::Info);

    A2UI_CHANNEL.notify_level("builtin", &message, level)?;

    Ok(Value::Record({
        let mut r = BTreeMap::new();
        r.insert("sent".to_string(), Value::Bool(true));
        r.insert("message".to_string(), Value::Str(message));
        r
    }))
}

/// a2ui_prompt(message, {placeholder: "..."}) - Request text input from user (blocking)
fn bi_a2ui_prompt(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let message = input
        .or_else(|| args.first().cloned())
        .map(|v| v.to_display_string())
        .ok_or_else(|| crate::safety::arg_err("a2ui_prompt: missing message"))?;

    match A2UI_CHANNEL.prompt_text("builtin", &message)? {
        PromptResponse::Text(s) => Ok(Value::Str(s)),
        PromptResponse::Cancelled => Ok(Value::Null),
        _ => Err(anyhow!("Unexpected response type")),
    }
}

/// a2ui_confirm(message) - Request yes/no confirmation from user (blocking)
fn bi_a2ui_confirm(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let message = input
        .or_else(|| args.first().cloned())
        .map(|v| v.to_display_string())
        .ok_or_else(|| crate::safety::arg_err("a2ui_confirm: missing message"))?;

    let result = A2UI_CHANNEL.prompt_confirm("builtin", &message)?;
    Ok(Value::Bool(result))
}

/// a2ui_select(message, options) - Request selection from user (blocking)
fn bi_a2ui_select(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let message = input
        .or_else(|| args.first().cloned())
        .map(|v| v.to_display_string())
        .ok_or_else(|| crate::safety::arg_err("a2ui_select: missing message"))?;

    let options: Vec<String> = args
        .get(1)
        .and_then(|v| {
            if let Value::Array(arr) = v {
                Some(arr.iter().map(|x| x.to_display_string()).collect())
            } else {
                None
            }
        })
        .ok_or_else(|| crate::safety::arg_err("a2ui_select: missing options array"))?;

    match A2UI_CHANNEL.prompt_select("builtin", &message, options.clone())? {
        PromptResponse::Select(idx) => {
            if idx < options.len() {
                Ok(Value::Str(options[idx].clone()))
            } else {
                Ok(Value::Null)
            }
        }
        PromptResponse::Cancelled => Ok(Value::Null),
        _ => Err(anyhow!("Unexpected response type")),
    }
}

/// a2ui_progress(label, current, total) - Update a progress indicator
fn bi_a2ui_progress(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let label = args
        .first()
        .map(|v| v.to_display_string())
        .ok_or_else(|| crate::safety::arg_err("a2ui_progress: missing label"))?;

    let current = args
        .get(1)
        .and_then(|v| match v {
            Value::Int(n) => Some(*n as u64),
            Value::Float(f) => Some(*f as u64),
            _ => None,
        })
        .ok_or_else(|| crate::safety::arg_err("a2ui_progress: missing current value"))?;

    let total = args
        .get(2)
        .and_then(|v| match v {
            Value::Int(n) => Some(*n as u64),
            Value::Float(f) => Some(*f as u64),
            _ => None,
        })
        .ok_or_else(|| crate::safety::arg_err("a2ui_progress: missing total value"))?;

    // Generate or use existing progress ID
    let progress_id = args
        .get(3)
        .and_then(|v| {
            if let Value::Str(s) = v {
                uuid::Uuid::parse_str(s).ok()
            } else {
                None
            }
        })
        .unwrap_or_else(uuid::Uuid::new_v4);

    A2UI_CHANNEL.progress("builtin", progress_id, &label, current, total)?;

    Ok(Value::Record({
        let mut r = BTreeMap::new();
        r.insert(
            "progress_id".to_string(),
            Value::Str(progress_id.to_string()),
        );
        r.insert("current".to_string(), Value::Int(current as i64));
        r.insert("total".to_string(), Value::Int(total as i64));
        r
    }))
}

/// a2ui_progress_complete(progress_id) - Complete a progress indicator
fn bi_a2ui_progress_complete(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let id_str = input
        .or_else(|| args.first().cloned())
        .map(|v| v.to_display_string())
        .ok_or_else(|| crate::safety::arg_err("a2ui_progress_complete: missing progress_id"))?;

    let progress_id = uuid::Uuid::parse_str(&id_str)
        .map_err(|_| anyhow!("a2ui_progress_complete: invalid progress_id"))?;

    A2UI_CHANNEL.progress_complete("builtin", progress_id)?;

    Ok(Value::Bool(true))
}

/// a2ui_render(content) - Render content in the UI
fn bi_a2ui_render(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let content = input
        .or_else(|| args.first().cloned())
        .ok_or_else(|| crate::safety::arg_err("a2ui_render: missing content"))?;

    let render_content = match &content {
        Value::Str(s) => RenderContent::Text(s.clone()),
        Value::Record(r) => {
            // Check for specific render types
            if let Some(Value::Str(md)) = r.get("markdown") {
                RenderContent::Markdown(md.clone())
            } else if let Some(Value::Str(json_str)) = r.get("json") {
                RenderContent::Json(serde_json::from_str(json_str).unwrap_or_default())
            } else {
                RenderContent::Json(serde_json::to_value(&content).unwrap_or_default())
            }
        }
        Value::Array(_) => RenderContent::Json(serde_json::to_value(&content).unwrap_or_default()),
        _ => RenderContent::Text(content.to_display_string()),
    };

    A2UI_CHANNEL.render("builtin", render_content)?;

    Ok(Value::Bool(true))
}

/// a2ui_render_table(headers, rows) - Render a table in the UI
fn bi_a2ui_render_table(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let headers: Vec<String> = args
        .first()
        .and_then(|v| {
            if let Value::Array(arr) = v {
                Some(arr.iter().map(|x| x.to_display_string()).collect())
            } else {
                None
            }
        })
        .ok_or_else(|| crate::safety::arg_err("a2ui_render_table: missing headers array"))?;

    let rows: Vec<Vec<String>> = args
        .get(1)
        .or(input.as_ref())
        .and_then(|v| {
            if let Value::Array(arr) = v {
                Some(
                    arr.iter()
                        .filter_map(|row| {
                            if let Value::Array(row_arr) = row {
                                Some(row_arr.iter().map(|x| x.to_display_string()).collect())
                            } else if let Value::Record(row_rec) = row {
                                Some(
                                    headers
                                        .iter()
                                        .map(|h| {
                                            row_rec
                                                .get(h)
                                                .map(|v| v.to_display_string())
                                                .unwrap_or_default()
                                        })
                                        .collect(),
                                )
                            } else {
                                None
                            }
                        })
                        .collect(),
                )
            } else {
                None
            }
        })
        .ok_or_else(|| crate::safety::arg_err("a2ui_render_table: missing rows array"))?;

    A2UI_CHANNEL.render("builtin", RenderContent::Table { headers, rows })?;

    Ok(Value::Bool(true))
}

