fn bi_sys_info(_args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let mut rec = std::collections::BTreeMap::new();
    rec.insert(
        "os".to_string(),
        Value::Str(std::env::consts::OS.to_string()),
    );
    rec.insert(
        "arch".to_string(),
        Value::Str(std::env::consts::ARCH.to_string()),
    );
    rec.insert(
        "family".to_string(),
        Value::Str(std::env::consts::FAMILY.to_string()),
    );

    #[cfg(target_os = "windows")]
    {
        let output = std::process::Command::new("powershell")
            .args([
                "-Command",
                "(Get-CimInstance Win32_OperatingSystem).Caption",
            ])
            .output()?;
        if output.status.success() {
            rec.insert(
                "os_name".to_string(),
                Value::Str(String::from_utf8_lossy(&output.stdout).trim().to_string()),
            );
        }
    }
    #[cfg(target_os = "linux")]
    {
        if let Ok(release) = std::fs::read_to_string("/etc/os-release") {
            for line in release.lines() {
                if line.starts_with("PRETTY_NAME=") {
                    rec.insert(
                        "os_name".to_string(),
                        Value::Str(line[13..].trim_matches('"').to_string()),
                    );
                    break;
                }
            }
        }
    }
    #[cfg(target_os = "macos")]
    {
        let output = std::process::Command::new("sw_vers")
            .args(["-productName"])
            .output();
        let version = std::process::Command::new("sw_vers")
            .args(["-productVersion"])
            .output();
        let name = output
            .as_ref()
            .ok()
            .filter(|o| o.status.success())
            .map(|o| String::from_utf8_lossy(&o.stdout).trim().to_string())
            .unwrap_or_else(|| "macOS".to_string());
        let ver = version
            .as_ref()
            .ok()
            .filter(|o| o.status.success())
            .map(|o| String::from_utf8_lossy(&o.stdout).trim().to_string())
            .unwrap_or_default();
        rec.insert(
            "os_name".to_string(),
            Value::Str(format!("{} {}", name, ver).trim().to_string()),
        );
    }

    Ok(Value::Record(rec))
}

