fn bi_svc_logs(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let name = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        _ => return Ok(Value::Null),
    };
    let lines = args
        .get(1)
        .and_then(|v| match v {
            Value::Int(n) => Some(*n),
            _ => None,
        })
        .unwrap_or(100);

    #[cfg(target_os = "windows")]
    {
        let output = std::process::Command::new("powershell")
            .args([
                "-Command",
                &crate::ps_script!(
                    "Get-EventLog -LogName Application -Source {} -Newest {} | Select-Object TimeGenerated,EntryType,Message | ConvertTo-Json",
                    crate::safety::ps_quote(&name), lines
                ),
            ])
            .output()?;
        if output.status.success() {
            let json_str = String::from_utf8_lossy(&output.stdout);
            if let Ok(json) = serde_json::from_str::<serde_json::Value>(&json_str) {
                let items = match &json {
                    serde_json::Value::Array(arr) => arr.clone(),
                    obj @ serde_json::Value::Object(_) => vec![obj.clone()],
                    _ => vec![],
                };
                let entries: Vec<Value> = items
                    .iter()
                    .filter_map(|obj| {
                        let o = obj.as_object()?;
                        let mut rec = std::collections::BTreeMap::new();
                        if let Some(v) = o.get("TimeGenerated") {
                            rec.insert("timestamp".to_string(), json_to_value(v.clone()));
                        }
                        if let Some(v) = o.get("EntryType") {
                            rec.insert("level".to_string(), json_to_value(v.clone()));
                        }
                        if let Some(v) = o.get("Message") {
                            rec.insert("message".to_string(), json_to_value(v.clone()));
                        }
                        Some(Value::Record(rec))
                    })
                    .collect();
                return Ok(Value::Array(entries));
            }
        }
        return Ok(Value::Array(vec![]));
    }
    #[cfg(target_os = "linux")]
    {
        let output = std::process::Command::new("journalctl")
            .args([
                "-u",
                &name,
                "-n",
                &lines.to_string(),
                "--no-pager",
                "-o",
                "json",
            ])
            .output()?;
        if output.status.success() {
            let text = String::from_utf8_lossy(&output.stdout);
            let entries: Vec<Value> = text
                .lines()
                .filter_map(|line| {
                    serde_json::from_str::<serde_json::Value>(line)
                        .ok()
                        .and_then(|obj| {
                            let o = obj.as_object()?;
                            let mut rec = std::collections::BTreeMap::new();
                            if let Some(v) = o.get("__REALTIME_TIMESTAMP") {
                                rec.insert("timestamp".to_string(), json_to_value(v.clone()));
                            }
                            if let Some(v) = o.get("PRIORITY") {
                                rec.insert("level".to_string(), json_to_value(v.clone()));
                            }
                            if let Some(v) = o.get("MESSAGE") {
                                rec.insert("message".to_string(), json_to_value(v.clone()));
                            }
                            if let Some(v) = o.get("_PID") {
                                rec.insert("pid".to_string(), json_to_value(v.clone()));
                            }
                            Some(Value::Record(rec))
                        })
                })
                .collect();
            return Ok(Value::Array(entries));
        }
        // Fallback: text parsing
        let output = std::process::Command::new("journalctl")
            .args(["-u", &name, "-n", &lines.to_string(), "--no-pager"])
            .output()?;
        let text = String::from_utf8_lossy(&output.stdout);
        let entries: Vec<Value> = text
            .lines()
            .filter(|l| !l.trim().is_empty())
            .map(|l| {
                let mut rec = std::collections::BTreeMap::new();
                rec.insert("message".to_string(), Value::Str(l.to_string()));
                Value::Record(rec)
            })
            .collect();
        return Ok(Value::Array(entries));
    }
    #[cfg(target_os = "macos")]
    {
        let output = std::process::Command::new("log")
            .args([
                "show",
                "--predicate",
                &format!("process == '{}'", name),
                "--last",
                "1h",
                "--style",
                "compact",
            ])
            .output()?;
        let text = String::from_utf8_lossy(&output.stdout);
        let entries: Vec<Value> = text
            .lines()
            .take(lines as usize)
            .filter(|l| !l.trim().is_empty())
            .map(|l| {
                let mut rec = std::collections::BTreeMap::new();
                // macOS log compact format: "timestamp  processName[pid]  message"
                // Try to split at known boundaries
                let parts: Vec<&str> = l.splitn(3, "  ").collect();
                if parts.len() >= 2 {
                    rec.insert(
                        "timestamp".to_string(),
                        Value::Str(parts[0].trim().to_string()),
                    );
                    let msg = if parts.len() >= 3 { parts[2] } else { parts[1] };
                    rec.insert("message".to_string(), Value::Str(msg.trim().to_string()));
                } else {
                    rec.insert("message".to_string(), Value::Str(l.to_string()));
                }
                Value::Record(rec)
            })
            .collect();
        return Ok(Value::Array(entries));
    }
    #[allow(unreachable_code)]
    {
        let _ = (name, lines);
        Ok(Value::Null)
    }
}

