fn bi_capabilities(_args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    #[cfg(target_os = "linux")]
    {
        let output = std::process::Command::new("capsh")
            .args(["--print"])
            .output()?;
        let text = String::from_utf8_lossy(&output.stdout).to_string();
        let mut rec = std::collections::BTreeMap::new();
        for line in text.lines() {
            let line = line.trim();
            if let Some((key, val)) = line.split_once('=') {
                let key = key.trim().to_lowercase();
                let val = val.trim();
                match key.as_str() {
                    "current" => {
                        let caps: Vec<Value> = val
                            .split(',')
                            .map(|c| Value::Str(c.trim().to_string()))
                            .filter(|v| {
                                if let Value::Str(s) = v {
                                    !s.is_empty()
                                } else {
                                    false
                                }
                            })
                            .collect();
                        rec.insert("current".to_string(), Value::Array(caps));
                    }
                    "bounding" | "bounding set" => {
                        let caps: Vec<Value> = val
                            .split(',')
                            .map(|c| Value::Str(c.trim().to_string()))
                            .filter(|v| {
                                if let Value::Str(s) = v {
                                    !s.is_empty()
                                } else {
                                    false
                                }
                            })
                            .collect();
                        rec.insert("bounding".to_string(), Value::Array(caps));
                    }
                    "ambient" | "ambient set" => {
                        let caps: Vec<Value> = val
                            .split(',')
                            .map(|c| Value::Str(c.trim().to_string()))
                            .filter(|v| {
                                if let Value::Str(s) = v {
                                    !s.is_empty()
                                } else {
                                    false
                                }
                            })
                            .collect();
                        rec.insert("ambient".to_string(), Value::Array(caps));
                    }
                    "securebits" => {
                        rec.insert("securebits".to_string(), Value::Str(val.to_string()));
                    }
                    "uid" => {
                        if let Ok(uid) = val.parse::<i64>() {
                            rec.insert("uid".to_string(), Value::Int(uid));
                        } else {
                            rec.insert("uid".to_string(), Value::Str(val.to_string()));
                        }
                    }
                    "gid" => {
                        if let Ok(gid) = val.parse::<i64>() {
                            rec.insert("gid".to_string(), Value::Int(gid));
                        } else {
                            rec.insert("gid".to_string(), Value::Str(val.to_string()));
                        }
                    }
                    _ => {
                        rec.insert(key, Value::Str(val.to_string()));
                    }
                }
            }
        }
        rec.insert("raw".to_string(), Value::Str(text));
        return Ok(Value::Record(rec));
    }
    Ok(Value::Null)
}

// ============================================================================
// 370-389: Package Management
// ============================================================================

fn detect_package_manager() -> &'static str {
    #[cfg(target_os = "windows")]
    {
        "winget"
    }
    #[cfg(target_os = "macos")]
    {
        return "brew";
    }
    #[cfg(target_os = "linux")]
    {
        if std::path::Path::new("/usr/bin/apt").exists() {
            return "apt";
        }
        if std::path::Path::new("/usr/bin/dnf").exists() {
            return "dnf";
        }
        if std::path::Path::new("/usr/bin/yum").exists() {
            return "yum";
        }
        if std::path::Path::new("/usr/bin/pacman").exists() {
            return "pacman";
        }
        return "apt";
    }
}

fn bi_pkg_list(_args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let pm = detect_package_manager();

    let output = match pm {
        "apt" => std::process::Command::new("dpkg").args(["-l"]).output()?,
        "dnf" | "yum" => std::process::Command::new(pm)
            .args(["list", "installed"])
            .output()?,
        "pacman" => std::process::Command::new("pacman").args(["-Q"]).output()?,
        "brew" => std::process::Command::new("brew")
            .args(["list", "--versions"])
            .output()?,
        "winget" => std::process::Command::new("winget")
            .args(["list"])
            .output()?,
        _ => return Ok(Value::Array(vec![])),
    };

    let text = String::from_utf8_lossy(&output.stdout);
    let packages: Vec<Value> = match pm {
        "apt" => {
            // dpkg -l: skip header lines (first 5), parse "ii  name  version  arch  description"
            text.lines()
                .filter(|l| l.starts_with("ii") || l.starts_with("rc"))
                .filter_map(|l| {
                    let parts: Vec<&str> = l.split_whitespace().collect();
                    if parts.len() >= 4 {
                        let mut rec = std::collections::BTreeMap::new();
                        rec.insert("status".to_string(), Value::Str(parts[0].to_string()));
                        rec.insert("name".to_string(), Value::Str(parts[1].to_string()));
                        rec.insert("version".to_string(), Value::Str(parts[2].to_string()));
                        rec.insert("arch".to_string(), Value::Str(parts[3].to_string()));
                        Some(Value::Record(rec))
                    } else {
                        None
                    }
                })
                .collect()
        }
        "pacman" => {
            // pacman -Q: "name version"
            text.lines()
                .filter(|l| !l.trim().is_empty())
                .filter_map(|l| {
                    let parts: Vec<&str> = l.splitn(2, ' ').collect();
                    if parts.len() >= 2 {
                        let mut rec = std::collections::BTreeMap::new();
                        rec.insert("name".to_string(), Value::Str(parts[0].to_string()));
                        rec.insert("version".to_string(), Value::Str(parts[1].to_string()));
                        Some(Value::Record(rec))
                    } else {
                        None
                    }
                })
                .collect()
        }
        "brew" => {
            // brew list --versions: "name version1 version2"
            text.lines()
                .filter(|l| !l.trim().is_empty())
                .filter_map(|l| {
                    let parts: Vec<&str> = l.splitn(2, ' ').collect();
                    let mut rec = std::collections::BTreeMap::new();
                    rec.insert("name".to_string(), Value::Str(parts[0].to_string()));
                    if parts.len() >= 2 {
                        rec.insert(
                            "version".to_string(),
                            Value::Str(parts[1].trim().to_string()),
                        );
                    }
                    Some(Value::Record(rec))
                })
                .collect()
        }
        _ => {
            // dnf/yum/winget: parse as whitespace-separated lines
            text.lines()
                .filter(|l| !l.trim().is_empty())
                .filter_map(|l| {
                    let parts: Vec<&str> = l.split_whitespace().collect();
                    if parts.len() >= 2 {
                        let mut rec = std::collections::BTreeMap::new();
                        rec.insert("name".to_string(), Value::Str(parts[0].to_string()));
                        rec.insert("version".to_string(), Value::Str(parts[1].to_string()));
                        Some(Value::Record(rec))
                    } else {
                        None
                    }
                })
                .collect()
        }
    };
    Ok(Value::Array(packages))
}

fn bi_pkg_search(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let query = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        _ => return Ok(Value::Array(vec![])),
    };
    let pm = detect_package_manager();

    let output = match pm {
        "apt" => std::process::Command::new("apt-cache")
            .args(["search", &query])
            .output()?,
        "dnf" | "yum" => std::process::Command::new(pm)
            .args(["search", &query])
            .output()?,
        "pacman" => std::process::Command::new("pacman")
            .args(["-Ss", &query])
            .output()?,
        "brew" => std::process::Command::new("brew")
            .args(["search", &query])
            .output()?,
        "winget" => std::process::Command::new("winget")
            .args(["search", &query])
            .output()?,
        _ => return Ok(Value::Array(vec![])),
    };

    let text = String::from_utf8_lossy(&output.stdout);
    let results: Vec<Value> = match pm {
        "apt" => {
            // apt-cache search: "name - description"
            text.lines()
                .filter(|l| !l.trim().is_empty())
                .filter_map(|l| {
                    let parts: Vec<&str> = l.splitn(2, " - ").collect();
                    let mut rec = std::collections::BTreeMap::new();
                    rec.insert("name".to_string(), Value::Str(parts[0].trim().to_string()));
                    if parts.len() >= 2 {
                        rec.insert(
                            "description".to_string(),
                            Value::Str(parts[1].trim().to_string()),
                        );
                    }
                    Some(Value::Record(rec))
                })
                .collect()
        }
        "brew" => {
            // brew search: one name per line
            text.lines()
                .filter(|l| !l.trim().is_empty() && !l.starts_with("==>"))
                .map(|l| {
                    let mut rec = std::collections::BTreeMap::new();
                    rec.insert("name".to_string(), Value::Str(l.trim().to_string()));
                    Value::Record(rec)
                })
                .collect()
        }
        _ => {
            // Generic: parse as whitespace-separated
            text.lines()
                .filter(|l| !l.trim().is_empty())
                .map(|l| {
                    let mut rec = std::collections::BTreeMap::new();
                    rec.insert("name".to_string(), Value::Str(l.trim().to_string()));
                    Value::Record(rec)
                })
                .collect()
        }
    };
    Ok(Value::Array(results))
}

fn bi_pkg_info(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let package = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        _ => return Ok(Value::Null),
    };
    let pm = detect_package_manager();

    let output = match pm {
        "apt" => std::process::Command::new("apt-cache")
            .args(["show", &package])
            .output()?,
        "dnf" | "yum" => std::process::Command::new(pm)
            .args(["info", &package])
            .output()?,
        "pacman" => std::process::Command::new("pacman")
            .args(["-Qi", &package])
            .output()?,
        "brew" => std::process::Command::new("brew")
            .args(["info", &package])
            .output()?,
        "winget" => std::process::Command::new("winget")
            .args(["show", &package])
            .output()?,
        _ => return Ok(Value::Null),
    };

    // Parse key-value "Field: Value" lines into a Record (works for apt, dnf, pacman, brew, winget)
    let text = String::from_utf8_lossy(&output.stdout);
    let mut rec = std::collections::BTreeMap::new();
    for line in text.lines() {
        if let Some(colon_pos) = line.find(':') {
            let key = line[..colon_pos].trim();
            let value = line[colon_pos + 1..].trim();
            if !key.is_empty() && !key.contains(' ') || key.contains("Build Date") {
                rec.insert(
                    key.to_lowercase().replace(' ', "_"),
                    Value::Str(value.to_string()),
                );
            }
        }
    }
    if rec.is_empty() {
        Ok(Value::Str(text.to_string()))
    } else {
        Ok(Value::Record(rec))
    }
}

