// [removed duplicate] use std::collections::BTreeMap;
// [removed duplicate] use std::process::Command;
// [removed duplicate] use anyhow::{anyhow, Result};

// Assuming Value is defined in the crate root or a value module
// [removed duplicate] use crate::value::Value;

// ---------------------------------------------------------------------------
// Helper: run a command, return stdout or error
// ---------------------------------------------------------------------------
fn sec_run_cmd(program: &str, args: &[&str]) -> Result<String> {
    let output = Command::new(program)
        .args(args)
        .output()
        .map_err(|e| anyhow!("failed to run `{}`: {}", program, e))?;
    if !output.status.success() {
        let stderr = String::from_utf8_lossy(&output.stderr);
        return Err(anyhow!(
            "`{} {}` failed: {}",
            program,
            args.join(" "),
            stderr.trim()
        ));
    }
    Ok(String::from_utf8_lossy(&output.stdout).to_string())
}

fn sec_run_cmd_ok(program: &str, args: &[&str]) -> Option<String> {
    sec_run_cmd(program, args).ok()
}

fn cmd_exists(program: &str) -> bool {
    Command::new(program).arg("--version").output().is_ok()
        || Command::new("which")
            .arg(program)
            .output()
            .map(|o| o.status.success())
            .unwrap_or(false)
}

fn rec(pairs: Vec<(&str, Value)>) -> Value {
    let mut m = BTreeMap::new();
    for (k, v) in pairs {
        m.insert(k.to_string(), v);
    }
    Value::Record(m)
}

fn s(v: &str) -> Value {
    Value::Str(v.to_string())
}

// ============================================================================
// 1010: bi_openssl_cert_info
// ============================================================================
fn bi_openssl_cert_info(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    if args.is_empty() {
        return Err(anyhow!(
            "openssl_cert_info requires a certificate file path argument"
        ));
    }
    let file_path = match &args[0] {
        Value::Str(s) => s.clone(),
        other => {
            return Err(anyhow!(
                "openssl_cert_info: expected String file path, got {:?}",
                other
            ))
        }
    };

    let out = sec_run_cmd("openssl", &["x509", "-in", &file_path, "-text", "-noout"])?;
    let mut m = BTreeMap::new();
    m.insert("file".to_string(), s(&file_path));

    for line in out.lines() {
        let trimmed = line.trim();
        if trimmed.starts_with("Issuer:") {
            m.insert(
                "issuer".to_string(),
                s(trimmed.strip_prefix("Issuer:").unwrap_or("").trim()),
            );
        } else if trimmed.starts_with("Subject:") {
            m.insert(
                "subject".to_string(),
                s(trimmed.strip_prefix("Subject:").unwrap_or("").trim()),
            );
        } else if trimmed.starts_with("Not Before:") {
            m.insert(
                "not_before".to_string(),
                s(trimmed.strip_prefix("Not Before:").unwrap_or("").trim()),
            );
        } else if trimmed.starts_with("Not After :") || trimmed.starts_with("Not After:") {
            let val = trimmed
                .strip_prefix("Not After :")
                .or_else(|| trimmed.strip_prefix("Not After:"))
                .unwrap_or("")
                .trim();
            m.insert("not_after".to_string(), s(val));
        } else if trimmed.starts_with("Serial Number:") {
            m.insert(
                "serial_number".to_string(),
                s(trimmed.strip_prefix("Serial Number:").unwrap_or("").trim()),
            );
        } else if trimmed.starts_with("Signature Algorithm:") {
            m.insert(
                "signature_algorithm".to_string(),
                s(trimmed
                    .strip_prefix("Signature Algorithm:")
                    .unwrap_or("")
                    .trim()),
            );
        } else if trimmed.starts_with("Public Key Algorithm:") {
            m.insert(
                "public_key_algorithm".to_string(),
                s(trimmed
                    .strip_prefix("Public Key Algorithm:")
                    .unwrap_or("")
                    .trim()),
            );
        }
    }
    m.insert("raw".to_string(), s(out.trim()));
    Ok(Value::Record(m))
}

// ============================================================================
// 1011: bi_openssl_genrsa
// ============================================================================
fn bi_openssl_genrsa(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    if args.is_empty() {
        return Err(anyhow!(
            "openssl_genrsa requires at least a file path argument"
        ));
    }
    let file_path = match &args[0] {
        Value::Str(s) => s.clone(),
        other => {
            return Err(anyhow!(
                "openssl_genrsa: expected String file path, got {:?}",
                other
            ))
        }
    };
    let bits = if args.len() > 1 {
        match &args[1] {
            Value::Int(n) => *n,
            Value::Str(s) => s
                .parse::<i64>()
                .map_err(|_| anyhow!("openssl_genrsa: invalid bits '{}'", s))?,
            other => {
                return Err(anyhow!(
                    "openssl_genrsa: expected Int bits, got {:?}",
                    other
                ))
            }
        }
    } else {
        4096
    };

    let bits_str = bits.to_string();
    let out = sec_run_cmd("openssl", &["genrsa", "-out", &file_path, &bits_str])?;
    Ok(rec(vec![
        ("action", s("genrsa")),
        ("file", s(&file_path)),
        ("bits", Value::Int(bits)),
        ("raw", s(out.trim())),
    ]))
}

// ============================================================================
// 1012: bi_gpg_list_keys
// ============================================================================
fn bi_gpg_list_keys(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let _ = &args;

    let out = sec_run_cmd("gpg", &["--list-keys", "--with-colons"])?;
    let mut keys = Vec::new();
    let mut current: Option<BTreeMap<String, Value>> = None;

    for line in out.lines() {
        let fields: Vec<&str> = line.split(':').collect();
        if fields.is_empty() {
            continue;
        }
        match fields[0] {
            "pub" => {
                // Save previous key if any
                if let Some(k) = current.take() {
                    keys.push(Value::Record(k));
                }
                let mut m = BTreeMap::new();
                m.insert("type".to_string(), s("pub"));
                if fields.len() > 1 {
                    m.insert("validity".to_string(), s(fields[1]));
                }
                if fields.len() > 2 {
                    m.insert("key_length".to_string(), s(fields[2]));
                }
                if fields.len() > 3 {
                    m.insert("algorithm".to_string(), s(fields[3]));
                }
                if fields.len() > 4 {
                    m.insert("key_id".to_string(), s(fields[4]));
                }
                if fields.len() > 5 {
                    m.insert("creation_date".to_string(), s(fields[5]));
                }
                if fields.len() > 6 {
                    m.insert("expiration_date".to_string(), s(fields[6]));
                }
                current = Some(m);
            }
            "uid" => {
                if let Some(ref mut m) = current {
                    if fields.len() > 9 {
                        m.insert("uid".to_string(), s(fields[9]));
                    }
                }
            }
            "sub" => {
                if let Some(ref mut m) = current {
                    let mut sub_info = String::new();
                    if fields.len() > 2 {
                        sub_info.push_str(fields[2]);
                        sub_info.push('/');
                    }
                    if fields.len() > 4 {
                        sub_info.push_str(fields[4]);
                    }
                    // Append to existing subkeys or create
                    let existing = m
                        .entry("subkeys".to_string())
                        .or_insert_with(|| Value::Array(Vec::new()));
                    if let Value::Array(ref mut arr) = existing {
                        arr.push(s(&sub_info));
                    }
                }
            }
            "fpr" => {
                if let Some(ref mut m) = current {
                    if fields.len() > 9 {
                        m.insert("fingerprint".to_string(), s(fields[9]));
                    }
                }
            }
            _ => {}
        }
    }
    // Push last key
    if let Some(k) = current {
        keys.push(Value::Record(k));
    }

    Ok(Value::Array(keys))
}

// ============================================================================
// 1013: bi_gpg_encrypt
// ============================================================================
fn bi_gpg_encrypt(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    if args.len() < 2 {
        return Err(anyhow!(
            "gpg_encrypt requires two arguments: file and recipient"
        ));
    }
    let file_path = match &args[0] {
        Value::Str(s) => s.clone(),
        other => {
            return Err(anyhow!(
                "gpg_encrypt: expected String file path, got {:?}",
                other
            ))
        }
    };
    let recipient = match &args[1] {
        Value::Str(s) => s.clone(),
        other => {
            return Err(anyhow!(
                "gpg_encrypt: expected String recipient, got {:?}",
                other
            ))
        }
    };

    let out = sec_run_cmd(
        "gpg",
        &[
            "--batch",
            "--yes",
            "--encrypt",
            "--recipient",
            &recipient,
            &file_path,
        ],
    )?;
    let output_file = format!("{}.gpg", file_path);
    Ok(rec(vec![
        ("action", s("encrypt")),
        ("input_file", s(&file_path)),
        ("output_file", s(&output_file)),
        ("recipient", s(&recipient)),
        ("raw", s(out.trim())),
    ]))
}

// ============================================================================
// 1014: bi_gpg_decrypt
// ============================================================================
fn bi_gpg_decrypt(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    if args.is_empty() {
        return Err(crate::safety::arg_err(
            "gpg_decrypt requires a file path argument",
        ));
    }
    let file_path = match &args[0] {
        Value::Str(s) => s.clone(),
        other => {
            return Err(anyhow!(
                "gpg_decrypt: expected String file path, got {:?}",
                other
            ))
        }
    };

    // Determine output file (strip .gpg or .asc extension if present)
    let output_file = if file_path.ends_with(".gpg") {
        file_path.trim_end_matches(".gpg").to_string()
    } else if file_path.ends_with(".asc") {
        file_path.trim_end_matches(".asc").to_string()
    } else {
        format!("{}.decrypted", file_path)
    };

    let out = sec_run_cmd(
        "gpg",
        &[
            "--batch",
            "--yes",
            "--output",
            &output_file,
            "--decrypt",
            &file_path,
        ],
    )?;
    Ok(rec(vec![
        ("action", s("decrypt")),
        ("input_file", s(&file_path)),
        ("output_file", s(&output_file)),
        ("raw", s(out.trim())),
    ]))
}

