// ---------------------------------------------------------------------------
// 1015: bi_htop_snapshot — Process monitor snapshot (top 20 by memory)
// ---------------------------------------------------------------------------
// 1015: bi_htop_snapshot - Interactive-style process monitor (cross-platform via sysinfo)
// ---------------------------------------------------------------------------
pub fn bi_htop_snapshot(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let count = match args.first() {
        Some(Value::Int(n)) => *n as usize,
        _ => 20,
    };
    let mut sys = System::new_all();
    sys.refresh_all();
    let mut procs: Vec<_> = sys.processes().iter().collect();
    procs.sort_by(|a, b| b.1.memory().cmp(&a.1.memory()));
    let entries: Vec<Value> = procs
        .iter()
        .take(count)
        .map(|(pid, p)| {
            let mut rec = BTreeMap::new();
            rec.insert("pid".to_string(), Value::Int(pid.as_u32() as i64));
            rec.insert(
                "name".to_string(),
                Value::Str(p.name().to_string_lossy().to_string()),
            );
            rec.insert(
                "cpu_percent".to_string(),
                Value::Float(p.cpu_usage() as f64),
            );
            rec.insert("memory_bytes".to_string(), Value::Int(p.memory() as i64));
            rec.insert(
                "memory_mb".to_string(),
                Value::Float(p.memory() as f64 / 1_048_576.0),
            );
            Value::Record(rec)
        })
        .collect();
    Ok(Value::Array(entries))
}

// ---------------------------------------------------------------------------
// 1016: bi_iotop_snapshot — I/O monitor snapshot
// ---------------------------------------------------------------------------
// 1016: bi_iotop_snapshot - I/O monitor snapshot (cross-platform via sysinfo)
// ---------------------------------------------------------------------------
fn bi_iotop_snapshot(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let count = match args.first() {
        Some(Value::Int(n)) => *n as usize,
        _ => 20,
    };
    let mut sys = System::new_all();
    sys.refresh_all();
    let mut procs: Vec<_> = sys.processes().iter().collect();
    procs.sort_by(|a, b| {
        let a_io = a.1.disk_usage().total_read_bytes + a.1.disk_usage().total_written_bytes;
        let b_io = b.1.disk_usage().total_read_bytes + b.1.disk_usage().total_written_bytes;
        b_io.cmp(&a_io)
    });
    let entries: Vec<Value> = procs
        .iter()
        .take(count)
        .map(|(pid, p)| {
            let du = p.disk_usage();
            let mut rec = BTreeMap::new();
            rec.insert("pid".to_string(), Value::Int(pid.as_u32() as i64));
            rec.insert(
                "name".to_string(),
                Value::Str(p.name().to_string_lossy().to_string()),
            );
            rec.insert(
                "total_read_bytes".to_string(),
                Value::Int(du.total_read_bytes as i64),
            );
            rec.insert(
                "total_written_bytes".to_string(),
                Value::Int(du.total_written_bytes as i64),
            );
            rec.insert("read_bytes".to_string(), Value::Int(du.read_bytes as i64));
            rec.insert(
                "written_bytes".to_string(),
                Value::Int(du.written_bytes as i64),
            );
            Value::Record(rec)
        })
        .collect();
    Ok(Value::Array(entries))
}

// ---------------------------------------------------------------------------
// 1017: bi_nethogs_info — Network traffic per process
// ---------------------------------------------------------------------------
fn bi_nethogs_info(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let _ = args;

    #[cfg(target_os = "windows")]
    {
        let ps_cmd = "Get-NetTCPConnection | Where-Object { $_.State -eq 'Established' } | Select-Object OwningProcess, LocalAddress, LocalPort, RemoteAddress, RemotePort, State | ForEach-Object { $proc = Get-Process -Id $_.OwningProcess -ErrorAction SilentlyContinue; $_ | Add-Member -NotePropertyName ProcessName -NotePropertyValue $(if($proc){$proc.ProcessName}else{'unknown'}) -PassThru } | Select-Object -First 30 | ConvertTo-Json -Depth 3";
        let output = Command::new("powershell")
            .args(["-NoProfile", "-Command", ps_cmd])
            .output()
            .map_err(|e| anyhow!("nethogs_info: failed to run powershell: {}", e))?;
        if !output.status.success() {
            let stderr = String::from_utf8_lossy(&output.stderr);
            return Err(anyhow!("nethogs_info: command failed: {}", stderr));
        }
        let stdout = String::from_utf8_lossy(&output.stdout);
        if stdout.trim().is_empty() {
            return Ok(Value::Array(vec![]));
        }
        let json_val: serde_json::Value = serde_json::from_str(stdout.trim())
            .map_err(|e| anyhow!("nethogs_info: JSON parse error: {}", e))?;
        Ok(json_to_value(json_val))
    }

    #[cfg(not(target_os = "windows"))]
    {
        // Try nethogs first, fall back to ss/netstat
        let output = Command::new("nethogs").args(["-t", "-c", "1"]).output();

        match output {
            Ok(out) if out.status.success() => {
                let stdout = String::from_utf8_lossy(&out.stdout);
                let mut records = Vec::new();
                for line in stdout.lines() {
                    let parts: Vec<&str> = line.split('\t').collect();
                    if parts.len() >= 3 {
                        let mut rec = BTreeMap::new();
                        rec.insert("program".to_string(), Value::Str(parts[0].to_string()));
                        rec.insert(
                            "sent_kbps".to_string(),
                            Value::Float(parts[1].parse::<f64>().unwrap_or(0.0)),
                        );
                        rec.insert(
                            "received_kbps".to_string(),
                            Value::Float(parts[2].parse::<f64>().unwrap_or(0.0)),
                        );
                        records.push(Value::Record(rec));
                    }
                }
                Ok(Value::Array(records))
            }
            _ => {
                // Fallback: netstat with process info
                let output = Command::new("ss")
                    .args(["-tunp"])
                    .output()
                    .or_else(|_| Command::new("netstat").args(["-tunp"]).output())
                    .map_err(|e| anyhow!("nethogs_info: fallback failed: {}", e))?;
                let stdout = String::from_utf8_lossy(&output.stdout);
                let mut records = Vec::new();
                for line in stdout.lines().skip(1) {
                    let parts: Vec<&str> = line.split_whitespace().collect();
                    if parts.len() >= 5 {
                        let mut rec = BTreeMap::new();
                        rec.insert("protocol".to_string(), Value::Str(parts[0].to_string()));
                        rec.insert(
                            "recv_q".to_string(),
                            Value::Int(parts[1].parse::<i64>().unwrap_or(0)),
                        );
                        rec.insert(
                            "send_q".to_string(),
                            Value::Int(parts[2].parse::<i64>().unwrap_or(0)),
                        );
                        rec.insert(
                            "local_address".to_string(),
                            Value::Str(parts[3].to_string()),
                        );
                        rec.insert("peer_address".to_string(), Value::Str(parts[4].to_string()));
                        if parts.len() >= 6 {
                            rec.insert("process".to_string(), Value::Str(parts[5..].join(" ")));
                        }
                        records.push(Value::Record(rec));
                    }
                }
                Ok(Value::Array(records))
            }
        }
    }
}

// ---------------------------------------------------------------------------
// 1018: bi_iftop_info — Network bandwidth info
// ---------------------------------------------------------------------------
fn bi_iftop_info(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let _ = args;

    #[cfg(target_os = "windows")]
    {
        let ps_cmd = "netstat -s | Out-String";
        let output = Command::new("powershell")
            .args(["-NoProfile", "-Command", ps_cmd])
            .output()
            .map_err(|e| anyhow!("iftop_info: failed to run powershell: {}", e))?;
        let stdout = String::from_utf8_lossy(&output.stdout);
        let mut rec = BTreeMap::new();
        rec.insert("source".to_string(), Value::Str("netstat -s".to_string()));
        // Parse key statistics from netstat -s
        for line in stdout.lines() {
            let trimmed = line.trim();
            if trimmed.contains("Segments Sent") || trimmed.contains("Segments sent") {
                if let Some(val) = trimmed
                    .split('=')
                    .next_back()
                    .or_else(|| trimmed.split_whitespace().next())
                {
                    rec.insert(
                        "tcp_segments_sent".to_string(),
                        Value::Int(val.trim().replace(",", "").parse::<i64>().unwrap_or(0)),
                    );
                }
            }
            if trimmed.contains("Segments Received") || trimmed.contains("Segments received") {
                if let Some(val) = trimmed
                    .split('=')
                    .next_back()
                    .or_else(|| trimmed.split_whitespace().next())
                {
                    rec.insert(
                        "tcp_segments_received".to_string(),
                        Value::Int(val.trim().replace(",", "").parse::<i64>().unwrap_or(0)),
                    );
                }
            }
            if trimmed.contains("Datagrams Sent") || trimmed.contains("Datagrams sent") {
                if let Some(val) = trimmed
                    .split('=')
                    .next_back()
                    .or_else(|| trimmed.split_whitespace().next())
                {
                    rec.insert(
                        "udp_datagrams_sent".to_string(),
                        Value::Int(val.trim().replace(",", "").parse::<i64>().unwrap_or(0)),
                    );
                }
            }
            if trimmed.contains("Datagrams Received") || trimmed.contains("Datagrams received") {
                if let Some(val) = trimmed
                    .split('=')
                    .next_back()
                    .or_else(|| trimmed.split_whitespace().next())
                {
                    rec.insert(
                        "udp_datagrams_received".to_string(),
                        Value::Int(val.trim().replace(",", "").parse::<i64>().unwrap_or(0)),
                    );
                }
            }
        }
        rec.insert("raw_output".to_string(), Value::Str(stdout.to_string()));
        Ok(Value::Record(rec))
    }

    #[cfg(not(target_os = "windows"))]
    {
        // Use ss -s for socket summary statistics
        let output = Command::new("ss")
            .args(["-s"])
            .output()
            .or_else(|_| Command::new("netstat").args(["-s"]).output())
            .map_err(|e| anyhow!("iftop_info: failed to run ss/netstat: {}", e))?;
        let stdout = String::from_utf8_lossy(&output.stdout);
        let mut rec = BTreeMap::new();
        rec.insert("source".to_string(), Value::Str("ss -s".to_string()));
        for line in stdout.lines() {
            let trimmed = line.trim();
            if trimmed.starts_with("TCP:") {
                rec.insert("tcp_summary".to_string(), Value::Str(trimmed.to_string()));
            } else if trimmed.starts_with("UDP:") {
                rec.insert("udp_summary".to_string(), Value::Str(trimmed.to_string()));
            } else if trimmed.starts_with("Total:") || trimmed.starts_with("Transport") {
                rec.insert("total_summary".to_string(), Value::Str(trimmed.to_string()));
            }
        }
        rec.insert("raw_output".to_string(), Value::Str(stdout.to_string()));
        Ok(Value::Record(rec))
    }
}
// ---------------------------------------------------------------------------
// 1017: bi_nmon_snapshot - System performance snapshot (cross-platform via sysinfo)
// ---------------------------------------------------------------------------
pub fn bi_nmon_snapshot(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let _ = args;
    let mut sys = System::new_all();
    sys.refresh_all();
    let load = System::load_average();
    let total_mem = sys.total_memory();
    let used_mem = sys.used_memory();
    let disks = Disks::new_with_refreshed_list();
    let total_disk: u64 = disks.iter().map(|d| d.total_space()).sum();
    let avail_disk: u64 = disks.iter().map(|d| d.available_space()).sum();
    let mut rec = BTreeMap::new();
    rec.insert("cpu_count".to_string(), Value::Int(sys.cpus().len() as i64));
    rec.insert(
        "cpu_percent".to_string(),
        Value::Float(sys.global_cpu_usage() as f64),
    );
    rec.insert("load_1".to_string(), Value::Float(load.one));
    rec.insert("load_5".to_string(), Value::Float(load.five));
    rec.insert("load_15".to_string(), Value::Float(load.fifteen));
    rec.insert("memory_total".to_string(), Value::Int(total_mem as i64));
    rec.insert("memory_used".to_string(), Value::Int(used_mem as i64));
    rec.insert(
        "memory_free".to_string(),
        Value::Int((total_mem - used_mem) as i64),
    );
    rec.insert("disk_total".to_string(), Value::Int(total_disk as i64));
    rec.insert("disk_available".to_string(), Value::Int(avail_disk as i64));
    rec.insert(
        "timestamp".to_string(),
        Value::Str(chrono::Local::now().to_rfc3339()),
    );
    Ok(Value::Record(rec))
}
// ---------------------------------------------------------------------------
// 1018: bi_glances_info - Comprehensive system info (cross-platform via sysinfo)
// ---------------------------------------------------------------------------
fn bi_glances_info(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let _ = args;
    let mut sys = System::new_all();
    sys.refresh_all();
    let total_mem = sys.total_memory();
    let used_mem = sys.used_memory();
    let total_swap = sys.total_swap();
    let used_swap = sys.used_swap();
    let cpus: Vec<Value> = sys
        .cpus()
        .iter()
        .map(|c| {
            let mut m = BTreeMap::new();
            m.insert("name".to_string(), Value::Str(c.name().to_string()));
            m.insert(
                "usage_percent".to_string(),
                Value::Float(c.cpu_usage() as f64),
            );
            m.insert(
                "frequency_mhz".to_string(),
                Value::Int(c.frequency() as i64),
            );
            Value::Record(m)
        })
        .collect();
    let disks_list = Disks::new_with_refreshed_list();
    let disk_entries: Vec<Value> = disks_list
        .iter()
        .map(|d| {
            let mut m = BTreeMap::new();
            m.insert(
                "name".to_string(),
                Value::Str(d.name().to_string_lossy().to_string()),
            );
            m.insert(
                "mount".to_string(),
                Value::Str(d.mount_point().to_string_lossy().to_string()),
            );
            m.insert(
                "fs_type".to_string(),
                Value::Str(d.file_system().to_string_lossy().to_string()),
            );
            m.insert(
                "total_bytes".to_string(),
                Value::Int(d.total_space() as i64),
            );
            m.insert(
                "available_bytes".to_string(),
                Value::Int(d.available_space() as i64),
            );
            let used = d.total_space().saturating_sub(d.available_space());
            let pct = if d.total_space() > 0 {
                used as f64 / d.total_space() as f64 * 100.0
            } else {
                0.0
            };
            m.insert("use_percent".to_string(), Value::Float(pct));
            Value::Record(m)
        })
        .collect();
    let nets = Networks::new_with_refreshed_list();
    let net_entries: Vec<Value> = nets
        .iter()
        .map(|(name, data)| {
            let mut m = BTreeMap::new();
            m.insert("interface".to_string(), Value::Str(name.clone()));
            m.insert(
                "rx_bytes".to_string(),
                Value::Int(data.total_received() as i64),
            );
            m.insert(
                "tx_bytes".to_string(),
                Value::Int(data.total_transmitted() as i64),
            );
            m.insert(
                "rx_packets".to_string(),
                Value::Int(data.total_packets_received() as i64),
            );
            m.insert(
                "tx_packets".to_string(),
                Value::Int(data.total_packets_transmitted() as i64),
            );
            Value::Record(m)
        })
        .collect();
    let load = System::load_average();
    let mut rec = BTreeMap::new();
    rec.insert(
        "hostname".to_string(),
        Value::Str(System::host_name().unwrap_or_default()),
    );
    rec.insert(
        "uptime_seconds".to_string(),
        Value::Int(System::uptime() as i64),
    );
    rec.insert("cpu_count".to_string(), Value::Int(sys.cpus().len() as i64));
    rec.insert("cpus".to_string(), Value::Array(cpus));
    rec.insert("memory_total".to_string(), Value::Int(total_mem as i64));
    rec.insert("memory_used".to_string(), Value::Int(used_mem as i64));
    rec.insert(
        "memory_percent".to_string(),
        Value::Float(if total_mem > 0 {
            used_mem as f64 / total_mem as f64 * 100.0
        } else {
            0.0
        }),
    );
    rec.insert("swap_total".to_string(), Value::Int(total_swap as i64));
    rec.insert("swap_used".to_string(), Value::Int(used_swap as i64));
    rec.insert("disks".to_string(), Value::Array(disk_entries));
    rec.insert("networks".to_string(), Value::Array(net_entries));
    rec.insert("load_1".to_string(), Value::Float(load.one));
    rec.insert("load_5".to_string(), Value::Float(load.five));
    rec.insert("load_15".to_string(), Value::Float(load.fifteen));
    Ok(Value::Record(rec))
}
// chrono_timestamp helper - returns RFC3339 timestamp
fn chrono_timestamp() -> String {
    chrono::Local::now().to_rfc3339()
}

// ---------------------------------------------------------------------------
// 1021: bi_tcpdump_capture — Packet capture
// ---------------------------------------------------------------------------
fn bi_tcpdump_capture(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let iface = if !args.is_empty() {
        match &args[0] {
            Value::Str(s) => s.clone(),
            _ => "any".to_string(),
        }
    } else {
        "any".to_string()
    };
    let count = if args.len() > 1 {
        match &args[1] {
            Value::Int(n) => *n,
            _ => 10,
        }
    } else {
        10
    };

    #[cfg(target_os = "linux")]
    {
        let output = Command::new("tcpdump")
            .args(["-c", &count.to_string(), "-i", &iface, "-nn", "-q"])
            .output();
        match output {
            Ok(out) if out.status.success() => {
                let stdout = String::from_utf8_lossy(&out.stdout);
                let stderr = String::from_utf8_lossy(&out.stderr);
                let mut records = Vec::new();
                let text = if stdout.trim().is_empty() {
                    stderr.to_string()
                } else {
                    stdout.to_string()
                };
                for line in text.lines() {
                    if !line.trim().is_empty()
                        && !line.contains("listening on")
                        && !line.contains("packets captured")
                    {
                        let mut rec = BTreeMap::new();
                        rec.insert("line".to_string(), Value::Str(line.trim().to_string()));
                        records.push(Value::Record(rec));
                    }
                }
                let mut result = BTreeMap::new();
                result.insert("interface".to_string(), Value::Str(iface));
                result.insert("count".to_string(), Value::Int(count));
                result.insert("packets".to_string(), Value::Array(records));
                Ok(Value::Record(result))
            }
            Ok(out) => {
                let stderr = String::from_utf8_lossy(&out.stderr);
                Err(anyhow!("tcpdump_capture: tcpdump failed: {}", stderr))
            }
            Err(e) => {
                let mut rec = BTreeMap::new();
                rec.insert("available".to_string(), Value::Bool(false));
                rec.insert(
                    "reason".to_string(),
                    Value::Str(format!("tcpdump not found: {}", e)),
                );
                Ok(Value::Record(rec))
            }
        }
    }

    #[cfg(target_os = "macos")]
    {
        // tcpdump ships with macOS natively
        let output = Command::new("tcpdump")
            .args(["-c", &count.to_string(), "-i", &iface, "-nn", "-q"])
            .output();
        match output {
            Ok(out) if out.status.success() => {
                let stdout = String::from_utf8_lossy(&out.stdout);
                let stderr = String::from_utf8_lossy(&out.stderr);
                let mut records = Vec::new();
                let text = if stdout.trim().is_empty() {
                    stderr.to_string()
                } else {
                    stdout.to_string()
                };
                for line in text.lines() {
                    if !line.trim().is_empty()
                        && !line.contains("listening on")
                        && !line.contains("packets captured")
                    {
                        let mut rec = BTreeMap::new();
                        rec.insert("line".to_string(), Value::Str(line.trim().to_string()));
                        records.push(Value::Record(rec));
                    }
                }
                let mut result = BTreeMap::new();
                result.insert("interface".to_string(), Value::Str(iface));
                result.insert("count".to_string(), Value::Int(count));
                result.insert("packets".to_string(), Value::Array(records));
                Ok(Value::Record(result))
            }
            Ok(out) => {
                let stderr = String::from_utf8_lossy(&out.stderr);
                Err(anyhow!("tcpdump_capture: tcpdump failed: {}", stderr))
            }
            Err(e) => {
                let mut rec = BTreeMap::new();
                rec.insert("available".to_string(), Value::Bool(false));
                rec.insert(
                    "reason".to_string(),
                    Value::Str(format!("tcpdump not found: {}", e)),
                );
                Ok(Value::Record(rec))
            }
        }
    }

    #[cfg(target_os = "windows")]
    {
        let _ = (iface, count);
        let mut rec = BTreeMap::new();
        rec.insert("available".to_string(), Value::Bool(false));
        rec.insert(
            "reason".to_string(),
            Value::Str("tcpdump_capture is not available on Windows".to_string()),
        );
        rec.insert(
            "hint".to_string(),
            Value::Str("Use Wireshark or pktmon on Windows".to_string()),
        );
        Ok(Value::Record(rec))
    }
}

// ---------------------------------------------------------------------------
// 1022: bi_ss_info — Socket statistics
// ---------------------------------------------------------------------------
fn bi_ss_info(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let filter = if !args.is_empty() {
        match &args[0] {
            Value::Str(s) => s.clone(),
            _ => "all".to_string(),
        }
    } else {
        "all".to_string()
    };

    #[cfg(target_os = "windows")]
    {
        let _ = filter;
        let ps_cmd =
            "netstat -an | Select-String -Pattern 'TCP|UDP' | ForEach-Object { $_.Line.Trim() }";
        let output = Command::new("powershell")
            .args(["-NoProfile", "-Command", ps_cmd])
            .output()
            .map_err(|e| anyhow!("ss_info: failed to run powershell: {}", e))?;
        let stdout = String::from_utf8_lossy(&output.stdout);
        let mut records = Vec::new();
        for line in stdout.lines() {
            let parts: Vec<&str> = line.split_whitespace().collect();
            if parts.len() >= 4 {
                let mut rec = BTreeMap::new();
                rec.insert("protocol".to_string(), Value::Str(parts[0].to_string()));
                rec.insert(
                    "local_address".to_string(),
                    Value::Str(parts[1].to_string()),
                );
                rec.insert(
                    "foreign_address".to_string(),
                    Value::Str(parts[2].to_string()),
                );
                rec.insert(
                    "state".to_string(),
                    Value::Str(parts.get(3).unwrap_or(&"").to_string()),
                );
                records.push(Value::Record(rec));
            }
        }
        Ok(Value::Array(records))
    }

    #[cfg(not(target_os = "windows"))]
    {
        // ss is Linux-only (iproute2); use netstat on macOS
        let (cmd_name, cmd_args): (&str, Vec<&str>) = if cfg!(target_os = "macos") {
            let args = match filter.as_str() {
                "tcp" => vec!["-an", "-p", "tcp"],
                "udp" => vec!["-an", "-p", "udp"],
                "listening" => vec!["-anl"],
                _ => vec!["-an"],
            };
            ("netstat", args)
        } else {
            let args = match filter.as_str() {
                "tcp" => vec!["-tln"],
                "udp" => vec!["-uln"],
                "listening" => vec!["-tuln"],
                _ => vec!["-tuln"],
            };
            ("ss", args)
        };
        let output = Command::new(cmd_name)
            .args(&cmd_args)
            .output()
            .map_err(|e| anyhow!("ss_info: failed to run {}: {}", cmd_name, e))?;
        if !output.status.success() {
            let stderr = String::from_utf8_lossy(&output.stderr);
            return Err(anyhow!("ss_info: {} failed: {}", cmd_name, stderr));
        }
        let stdout = String::from_utf8_lossy(&output.stdout);
        let mut records = Vec::new();
        let lines: Vec<&str> = stdout.lines().collect();
        for line in lines.iter().skip(1) {
            let parts: Vec<&str> = line.split_whitespace().collect();
            if parts.len() >= 5 {
                let mut rec = BTreeMap::new();
                rec.insert("state".to_string(), Value::Str(parts[0].to_string()));
                rec.insert(
                    "recv_q".to_string(),
                    Value::Int(parts[1].parse::<i64>().unwrap_or(0)),
                );
                rec.insert(
                    "send_q".to_string(),
                    Value::Int(parts[2].parse::<i64>().unwrap_or(0)),
                );
                rec.insert(
                    "local_address".to_string(),
                    Value::Str(parts[3].to_string()),
                );
                rec.insert("peer_address".to_string(), Value::Str(parts[4].to_string()));
                if parts.len() >= 6 {
                    rec.insert("process".to_string(), Value::Str(parts[5..].join(" ")));
                }
                records.push(Value::Record(rec));
            }
        }
        Ok(Value::Array(records))
    }
}

// ---------------------------------------------------------------------------
// 1023: bi_ip_addr — IP address management
// ---------------------------------------------------------------------------
fn bi_ip_addr(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let iface = if !args.is_empty() {
        match &args[0] {
            Value::Str(s) => Some(s.clone()),
            _ => None,
        }
    } else {
        None
    };

    #[cfg(target_os = "windows")]
    {
        let ps_cmd = if let Some(ref iface_name) = iface {
            crate::ps_script!("Get-NetIPAddress | Where-Object {{ $_.InterfaceAlias -like {} }} | Select-Object InterfaceAlias, IPAddress, PrefixLength, AddressFamily, Type | ConvertTo-Json -Depth 3", crate::safety::ps_quote(&format!("*{}*", iface_name)))
        } else {
            "Get-NetIPAddress | Select-Object InterfaceAlias, IPAddress, PrefixLength, AddressFamily, Type | ConvertTo-Json -Depth 3".to_string()
        };
        let output = Command::new("powershell")
            .args(["-NoProfile", "-Command", &ps_cmd])
            .output()
            .map_err(|e| anyhow!("ip_addr: failed to run powershell: {}", e))?;
        let stdout = String::from_utf8_lossy(&output.stdout);
        if stdout.trim().is_empty() {
            return Ok(Value::Array(vec![]));
        }
        let json_val: serde_json::Value = serde_json::from_str(stdout.trim())
            .map_err(|e| anyhow!("ip_addr: JSON parse error: {}", e))?;
        Ok(json_to_value(json_val))
    }

    #[cfg(target_os = "linux")]
    {
        let mut cmd = Command::new("ip");
        cmd.args(["-j", "addr", "show"]);
        if let Some(ref iface_name) = iface {
            cmd.arg(iface_name);
        }
        let output = cmd
            .output()
            .map_err(|e| anyhow!("ip_addr: failed to run ip: {}", e))?;
        if !output.status.success() {
            let stderr = String::from_utf8_lossy(&output.stderr);
            return Err(anyhow!("ip_addr: ip command failed: {}", stderr));
        }
        let stdout = String::from_utf8_lossy(&output.stdout);
        let json_val: serde_json::Value = serde_json::from_str(stdout.trim())
            .map_err(|e| anyhow!("ip_addr: JSON parse error: {}", e))?;
        Ok(json_to_value(json_val))
    }

    #[cfg(target_os = "macos")]
    {
        let mut cmd = Command::new("ifconfig");
        if let Some(ref iface_name) = iface {
            cmd.arg(iface_name);
        }
        let output = cmd
            .output()
            .map_err(|e| anyhow!("ip_addr: failed to run ifconfig: {}", e))?;
        let stdout = String::from_utf8_lossy(&output.stdout);
        let mut records = Vec::new();
        let mut current_iface = String::new();
        for line in stdout.lines() {
            if !line.starts_with('\t') && !line.starts_with(' ') && line.contains(':') {
                current_iface = line.split(':').next().unwrap_or("").to_string();
            } else if line.trim().starts_with("inet ") {
                let parts: Vec<&str> = line.trim().split_whitespace().collect();
                if parts.len() >= 2 {
                    let mut rec = BTreeMap::new();
                    rec.insert("interface".to_string(), Value::Str(current_iface.clone()));
                    rec.insert("address".to_string(), Value::Str(parts[1].to_string()));
                    rec.insert("family".to_string(), Value::Str("inet".to_string()));
                    if let Some(pos) = parts.iter().position(|&x| x == "netmask") {
                        if parts.len() > pos + 1 {
                            rec.insert(
                                "netmask".to_string(),
                                Value::Str(parts[pos + 1].to_string()),
                            );
                        }
                    }
                    records.push(Value::Record(rec));
                }
            } else if line.trim().starts_with("inet6 ") {
                let parts: Vec<&str> = line.trim().split_whitespace().collect();
                if parts.len() >= 2 {
                    let mut rec = BTreeMap::new();
                    rec.insert("interface".to_string(), Value::Str(current_iface.clone()));
                    rec.insert("address".to_string(), Value::Str(parts[1].to_string()));
                    rec.insert("family".to_string(), Value::Str("inet6".to_string()));
                    records.push(Value::Record(rec));
                }
            }
        }
        Ok(Value::Array(records))
    }
}

// ---------------------------------------------------------------------------
// 1024: bi_ip_route — IP route table
// ---------------------------------------------------------------------------
fn bi_ip_route(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let _ = args;

    #[cfg(target_os = "windows")]
    {
        let ps_cmd = "Get-NetRoute | Select-Object DestinationPrefix, NextHop, InterfaceAlias, RouteMetric, InterfaceMetric | ConvertTo-Json -Depth 3";
        let output = Command::new("powershell")
            .args(["-NoProfile", "-Command", ps_cmd])
            .output()
            .map_err(|e| anyhow!("ip_route: failed to run powershell: {}", e))?;
        let stdout = String::from_utf8_lossy(&output.stdout);
        if stdout.trim().is_empty() {
            return Ok(Value::Array(vec![]));
        }
        let json_val: serde_json::Value = serde_json::from_str(stdout.trim())
            .map_err(|e| anyhow!("ip_route: JSON parse error: {}", e))?;
        Ok(json_to_value(json_val))
    }

    #[cfg(target_os = "linux")]
    {
        let output = Command::new("ip")
            .args(["-j", "route", "show"])
            .output()
            .map_err(|e| anyhow!("ip_route: failed to run ip: {}", e))?;
        if !output.status.success() {
            let stderr = String::from_utf8_lossy(&output.stderr);
            return Err(anyhow!("ip_route: ip command failed: {}", stderr));
        }
        let stdout = String::from_utf8_lossy(&output.stdout);
        let json_val: serde_json::Value = serde_json::from_str(stdout.trim())
            .map_err(|e| anyhow!("ip_route: JSON parse error: {}", e))?;
        Ok(json_to_value(json_val))
    }

    #[cfg(target_os = "macos")]
    {
        let output = Command::new("netstat")
            .args(["-rn"])
            .output()
            .map_err(|e| anyhow!("ip_route: failed to run netstat: {}", e))?;
        let stdout = String::from_utf8_lossy(&output.stdout);
        let mut records = Vec::new();
        let mut header_seen = false;
        for line in stdout.lines() {
            if line.starts_with("Destination") {
                header_seen = true;
                continue;
            }
            if header_seen {
                let parts: Vec<&str> = line.split_whitespace().collect();
                if parts.len() >= 4 {
                    let mut rec = BTreeMap::new();
                    rec.insert("destination".to_string(), Value::Str(parts[0].to_string()));
                    rec.insert("gateway".to_string(), Value::Str(parts[1].to_string()));
                    rec.insert("flags".to_string(), Value::Str(parts[2].to_string()));
                    rec.insert(
                        "interface".to_string(),
                        Value::Str(parts.last().unwrap_or(&"").to_string()),
                    );
                    records.push(Value::Record(rec));
                }
            }
        }
        Ok(Value::Array(records))
    }
}

// ---------------------------------------------------------------------------
// 1025: bi_ip_link — Network link info
// ---------------------------------------------------------------------------
fn bi_ip_link(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let iface = if !args.is_empty() {
        match &args[0] {
            Value::Str(s) => Some(s.clone()),
            _ => None,
        }
    } else {
        None
    };

    #[cfg(target_os = "windows")]
    {
        let ps_cmd = if let Some(ref iface_name) = iface {
            crate::ps_script!("Get-NetAdapter | Where-Object {{ $_.Name -like {} }} | Select-Object Name, InterfaceDescription, Status, MacAddress, LinkSpeed, MediaType | ConvertTo-Json -Depth 3", crate::safety::ps_quote(&format!("*{}*", iface_name)))
        } else {
            "Get-NetAdapter | Select-Object Name, InterfaceDescription, Status, MacAddress, LinkSpeed, MediaType | ConvertTo-Json -Depth 3".to_string()
        };
        let output = Command::new("powershell")
            .args(["-NoProfile", "-Command", &ps_cmd])
            .output()
            .map_err(|e| anyhow!("ip_link: failed to run powershell: {}", e))?;
        let stdout = String::from_utf8_lossy(&output.stdout);
        if stdout.trim().is_empty() {
            return Ok(Value::Array(vec![]));
        }
        let json_val: serde_json::Value = serde_json::from_str(stdout.trim())
            .map_err(|e| anyhow!("ip_link: JSON parse error: {}", e))?;
        Ok(json_to_value(json_val))
    }

    #[cfg(target_os = "linux")]
    {
        let mut cmd = Command::new("ip");
        cmd.args(["-j", "link", "show"]);
        if let Some(ref iface_name) = iface {
            cmd.arg(iface_name);
        }
        let output = cmd
            .output()
            .map_err(|e| anyhow!("ip_link: failed to run ip: {}", e))?;
        if !output.status.success() {
            let stderr = String::from_utf8_lossy(&output.stderr);
            return Err(anyhow!("ip_link: ip command failed: {}", stderr));
        }
        let stdout = String::from_utf8_lossy(&output.stdout);
        let json_val: serde_json::Value = serde_json::from_str(stdout.trim())
            .map_err(|e| anyhow!("ip_link: JSON parse error: {}", e))?;
        Ok(json_to_value(json_val))
    }

    #[cfg(target_os = "macos")]
    {
        let mut cmd = Command::new("ifconfig");
        if let Some(ref iface_name) = iface {
            cmd.arg(iface_name);
        }
        let output = cmd
            .output()
            .map_err(|e| anyhow!("ip_link: failed to run ifconfig: {}", e))?;
        let stdout = String::from_utf8_lossy(&output.stdout);
        let mut records = Vec::new();
        let mut current_iface = String::new();
        let mut current_rec = BTreeMap::new();
        for line in stdout.lines() {
            if !line.starts_with('\t') && !line.starts_with(' ') && line.contains(':') {
                if !current_iface.is_empty() {
                    current_rec.insert("interface".to_string(), Value::Str(current_iface.clone()));
                    records.push(Value::Record(current_rec.clone()));
                }
                current_iface = line.split(':').next().unwrap_or("").to_string();
                current_rec = BTreeMap::new();
                let flags_part = line.split('<').nth(1).and_then(|s| s.split('>').next());
                if let Some(flags) = flags_part {
                    current_rec.insert("flags".to_string(), Value::Str(flags.to_string()));
                }
            } else if line.trim().starts_with("ether ") {
                let parts: Vec<&str> = line.trim().split_whitespace().collect();
                if parts.len() >= 2 {
                    current_rec.insert("mac_address".to_string(), Value::Str(parts[1].to_string()));
                }
            } else if line.trim().starts_with("status:") {
                let parts: Vec<&str> = line.trim().split_whitespace().collect();
                if parts.len() >= 2 {
                    current_rec.insert("status".to_string(), Value::Str(parts[1].to_string()));
                }
            }
        }
        if !current_iface.is_empty() {
            current_rec.insert("interface".to_string(), Value::Str(current_iface));
            records.push(Value::Record(current_rec));
        }
        Ok(Value::Array(records))
    }
}

// ---------------------------------------------------------------------------
// 1026: bi_ethtool_info — Ethernet device info (Linux only)
// ---------------------------------------------------------------------------
fn bi_ethtool_info(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let device = if !args.is_empty() {
        match &args[0] {
            Value::Str(s) => s.clone(),
            _ => {
                return Err(anyhow!(
                    "ethtool_info: device name required as string argument"
                ))
            }
        }
    } else {
        return Err(anyhow!(
            "ethtool_info: device name required (e.g., \"eth0\")"
        ));
    };

    #[cfg(target_os = "linux")]
    {
        let output = Command::new("ethtool").arg(&device).output();
        match output {
            Ok(out) if out.status.success() => {
                let stdout = String::from_utf8_lossy(&out.stdout);
                let mut rec = BTreeMap::new();
                rec.insert("device".to_string(), Value::Str(device));
                for line in stdout.lines() {
                    let trimmed = line.trim();
                    if let Some((key, val)) = trimmed.split_once(':') {
                        let k = key
                            .trim()
                            .to_lowercase()
                            .replace(' ', "_")
                            .replace('-', "_");
                        let v = val.trim();
                        if !k.is_empty() && !v.is_empty() {
                            rec.insert(k, Value::Str(v.to_string()));
                        }
                    }
                }
                Ok(Value::Record(rec))
            }
            Ok(out) => {
                let stderr = String::from_utf8_lossy(&out.stderr);
                Err(anyhow!(
                    "ethtool_info: ethtool failed for {}: {}",
                    device,
                    stderr
                ))
            }
            Err(e) => {
                let mut rec = BTreeMap::new();
                rec.insert("available".to_string(), Value::Bool(false));
                rec.insert(
                    "reason".to_string(),
                    Value::Str(format!("ethtool not found: {}", e)),
                );
                Ok(Value::Record(rec))
            }
        }
    }

    #[cfg(not(target_os = "linux"))]
    {
        let _ = device;
        let mut rec = BTreeMap::new();
        rec.insert("available".to_string(), Value::Bool(false));
        rec.insert(
            "reason".to_string(),
            Value::Str("ethtool is only available on Linux".to_string()),
        );
        Ok(Value::Record(rec))
    }
}

// ---------------------------------------------------------------------------
// 1027: bi_perf_stat — Performance counters (Linux only)
// ---------------------------------------------------------------------------
fn bi_perf_stat(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let command = if !args.is_empty() {
        match &args[0] {
            Value::Str(s) => s.clone(),
            _ => return Err(crate::safety::arg_err("perf_stat: command string required")),
        }
    } else {
        return Err(anyhow!(
            "perf_stat: command string required (e.g., \"sleep 1\")"
        ));
    };
    let events = if args.len() > 1 {
        match &args[1] {
            Value::Str(s) => s.clone(),
            _ => "cycles,instructions,cache-misses".to_string(),
        }
    } else {
        "cycles,instructions,cache-misses".to_string()
    };
    crate::safety::guard_exec("perf_stat", &command)?;

    #[cfg(target_os = "linux")]
    {
        let output = Command::new("perf")
            .args(["stat", "-e", &events, "--", "sh", "-c", &command])
            .output();
        match output {
            Ok(out) => {
                // perf stat outputs to stderr
                let stderr = String::from_utf8_lossy(&out.stderr);
                let mut rec = BTreeMap::new();
                rec.insert("command".to_string(), Value::Str(command));
                rec.insert("events".to_string(), Value::Str(events));
                let mut counters = Vec::new();
                for line in stderr.lines() {
                    let trimmed = line.trim();
                    if trimmed.is_empty()
                        || trimmed.starts_with("Performance")
                        || trimmed.starts_with("#")
                    {
                        continue;
                    }
                    // Parse lines like "  1,234,567      cycles"
                    let parts: Vec<&str> = trimmed.split_whitespace().collect();
                    if parts.len() >= 2 {
                        let mut counter = BTreeMap::new();
                        counter.insert("value".to_string(), Value::Str(parts[0].to_string()));
                        counter.insert("name".to_string(), Value::Str(parts[1..].join(" ")));
                        counters.push(Value::Record(counter));
                    }
                }
                rec.insert("counters".to_string(), Value::Array(counters));
                rec.insert("raw_output".to_string(), Value::Str(stderr.to_string()));
                Ok(Value::Record(rec))
            }
            Err(e) => {
                let mut rec = BTreeMap::new();
                rec.insert("available".to_string(), Value::Bool(false));
                rec.insert(
                    "reason".to_string(),
                    Value::Str(format!("perf not found: {}", e)),
                );
                Ok(Value::Record(rec))
            }
        }
    }

    #[cfg(not(target_os = "linux"))]
    {
        let _ = (command, events);
        let mut rec = BTreeMap::new();
        rec.insert("available".to_string(), Value::Bool(false));
        rec.insert(
            "reason".to_string(),
            Value::Str("perf stat is only available on Linux".to_string()),
        );
        Ok(Value::Record(rec))
    }
}

// ---------------------------------------------------------------------------
// 1028: bi_perf_record — Performance recording info (Linux only)
// ---------------------------------------------------------------------------
fn bi_perf_record(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let command = if !args.is_empty() {
        match &args[0] {
            Value::Str(s) => s.clone(),
            _ => {
                return Err(crate::safety::arg_err(
                    "perf_record: command string required",
                ))
            }
        }
    } else {
        return Err(anyhow!(
            "perf_record: command string required (e.g., \"sleep 1\")"
        ));
    };
    let output_file = if args.len() > 1 {
        match &args[1] {
            Value::Str(s) => s.clone(),
            _ => "perf.data".to_string(),
        }
    } else {
        "perf.data".to_string()
    };
    crate::safety::guard_exec("perf_record", &command)?;

    #[cfg(target_os = "linux")]
    {
        let output = Command::new("perf")
            .args(["record", "-o", &output_file, "--", "sh", "-c", &command])
            .output();
        match output {
            Ok(out) => {
                let stderr = String::from_utf8_lossy(&out.stderr);
                let mut rec = BTreeMap::new();
                rec.insert("command".to_string(), Value::Str(command));
                rec.insert("output_file".to_string(), Value::Str(output_file));
                rec.insert("success".to_string(), Value::Bool(out.status.success()));
                rec.insert("details".to_string(), Value::Str(stderr.trim().to_string()));
                rec.insert(
                    "hint".to_string(),
                    Value::Str("Use 'perf report' to analyze the recorded data".to_string()),
                );
                Ok(Value::Record(rec))
            }
            Err(e) => {
                let mut rec = BTreeMap::new();
                rec.insert("available".to_string(), Value::Bool(false));
                rec.insert(
                    "reason".to_string(),
                    Value::Str(format!("perf not found: {}", e)),
                );
                Ok(Value::Record(rec))
            }
        }
    }

    #[cfg(not(target_os = "linux"))]
    {
        let _ = (command, output_file);
        let mut rec = BTreeMap::new();
        rec.insert("available".to_string(), Value::Bool(false));
        rec.insert(
            "reason".to_string(),
            Value::Str("perf record is only available on Linux".to_string()),
        );
        Ok(Value::Record(rec))
    }
}
// ---------------------------------------------------------------------------
// 1019: bi_free_mem - Memory usage (cross-platform via sysinfo)
// ---------------------------------------------------------------------------
pub fn bi_free_mem(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let _ = args;
    let mut sys = System::new_all();
    sys.refresh_all();
    let total = sys.total_memory();
    let used = sys.used_memory();
    let free = sys.free_memory();
    let available = sys.available_memory();
    let swap_total = sys.total_swap();
    let swap_used = sys.used_swap();
    let swap_free = swap_total.saturating_sub(swap_used);
    let mut rec = BTreeMap::new();
    rec.insert("total".to_string(), Value::Int(total as i64));
    rec.insert("used".to_string(), Value::Int(used as i64));
    rec.insert("free".to_string(), Value::Int(free as i64));
    rec.insert("available".to_string(), Value::Int(available as i64));
    rec.insert(
        "use_percent".to_string(),
        Value::Float(if total > 0 {
            used as f64 / total as f64 * 100.0
        } else {
            0.0
        }),
    );
    rec.insert("swap_total".to_string(), Value::Int(swap_total as i64));
    rec.insert("swap_used".to_string(), Value::Int(swap_used as i64));
    rec.insert("swap_free".to_string(), Value::Int(swap_free as i64));
    Ok(Value::Record(rec))
}
// ---------------------------------------------------------------------------
// 1020: bi_uptime_extended - Extended uptime info (cross-platform via sysinfo)
// ---------------------------------------------------------------------------
fn bi_uptime_extended(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let _ = args;
    let secs = System::uptime();
    let days = secs / 86400;
    let hours = (secs % 86400) / 3600;
    let minutes = (secs % 3600) / 60;
    let seconds = secs % 60;
    let human = format!("{}d {}h {}m {}s", days, hours, minutes, seconds);
    let load = System::load_average();
    let mut rec = BTreeMap::new();
    rec.insert("uptime_seconds".to_string(), Value::Int(secs as i64));
    rec.insert("uptime_human".to_string(), Value::Str(human));
    rec.insert("days".to_string(), Value::Int(days as i64));
    rec.insert("hours".to_string(), Value::Int(hours as i64));
    rec.insert("minutes".to_string(), Value::Int(minutes as i64));
    rec.insert("seconds".to_string(), Value::Int(seconds as i64));
    rec.insert("load_1".to_string(), Value::Float(load.one));
    rec.insert("load_5".to_string(), Value::Float(load.five));
    rec.insert("load_15".to_string(), Value::Float(load.fifteen));
    rec.insert(
        "hostname".to_string(),
        Value::Str(System::host_name().unwrap_or_default()),
    );
    Ok(Value::Record(rec))
}

// ---------------------------------------------------------------------------
// 1031: bi_who_users — Currently logged in users
// ---------------------------------------------------------------------------
fn bi_who_users(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let _ = args;

    #[cfg(target_os = "windows")]
    {
        let output = Command::new("powershell")
            .args(["-NoProfile", "-Command", "query user 2>$null | Out-String"])
            .output()
            .map_err(|e| anyhow!("who_users: failed to run query user: {}", e))?;
        let stdout = String::from_utf8_lossy(&output.stdout);
        let mut records = Vec::new();
        for line in stdout.lines().skip(1) {
            let trimmed = line.trim();
            if trimmed.is_empty() {
                continue;
            }
            let parts: Vec<&str> = trimmed.split_whitespace().collect();
            if parts.len() >= 4 {
                let mut rec = BTreeMap::new();
                rec.insert(
                    "username".to_string(),
                    Value::Str(parts[0].trim_start_matches('>').to_string()),
                );
                rec.insert("session_name".to_string(), Value::Str(parts[1].to_string()));
                rec.insert("id".to_string(), Value::Str(parts[2].to_string()));
                rec.insert("state".to_string(), Value::Str(parts[3].to_string()));
                if parts.len() >= 5 {
                    rec.insert("idle_time".to_string(), Value::Str(parts[4].to_string()));
                }
                if parts.len() >= 6 {
                    rec.insert("logon_time".to_string(), Value::Str(parts[5..].join(" ")));
                }
                records.push(Value::Record(rec));
            }
        }
        Ok(Value::Array(records))
    }

    #[cfg(not(target_os = "windows"))]
    {
        let output = Command::new("who")
            .output()
            .map_err(|e| anyhow!("who_users: failed to run who: {}", e))?;
        let stdout = String::from_utf8_lossy(&output.stdout);
        let mut records = Vec::new();
        for line in stdout.lines() {
            let parts: Vec<&str> = line.split_whitespace().collect();
            if parts.len() >= 3 {
                let mut rec = BTreeMap::new();
                rec.insert("username".to_string(), Value::Str(parts[0].to_string()));
                rec.insert("terminal".to_string(), Value::Str(parts[1].to_string()));
                rec.insert("login_time".to_string(), Value::Str(parts[2..].join(" ")));
                records.push(Value::Record(rec));
            }
        }
        Ok(Value::Array(records))
    }
}

// ---------------------------------------------------------------------------
// 1032: bi_last_logins — Recent login history
// ---------------------------------------------------------------------------
fn bi_last_logins(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let count = if !args.is_empty() {
        match &args[0] {
            Value::Int(n) => *n,
            _ => 20,
        }
    } else {
        20
    };

    #[cfg(target_os = "windows")]
    {
        let ps_cmd = crate::ps_script!(
            r#"try {{
    Get-WinEvent -FilterHashtable @{{LogName='Security'; Id=4624}} -MaxEvents {} -ErrorAction Stop |
        Select-Object TimeCreated, Id, @{{Name='User';Expression={{$_.Properties[5].Value}}}}, @{{Name='LogonType';Expression={{$_.Properties[8].Value}}}}, @{{Name='SourceIP';Expression={{$_.Properties[18].Value}}}} |
        ConvertTo-Json -Depth 3
}} catch {{
    @{{available = $false; reason = $_.Exception.Message}} | ConvertTo-Json
}}"#,
            count
        );
        let output = Command::new("powershell")
            .args(["-NoProfile", "-Command", &ps_cmd])
            .output()
            .map_err(|e| anyhow!("last_logins: failed to run powershell: {}", e))?;
        let stdout = String::from_utf8_lossy(&output.stdout);
        if stdout.trim().is_empty() {
            let mut rec = BTreeMap::new();
            rec.insert("available".to_string(), Value::Bool(false));
            rec.insert(
                "reason".to_string(),
                Value::Str("No login events found or access denied".to_string()),
            );
            return Ok(Value::Record(rec));
        }
        let json_val: serde_json::Value = serde_json::from_str(stdout.trim())
            .map_err(|e| anyhow!("last_logins: JSON parse error: {}", e))?;
        Ok(json_to_value(json_val))
    }

    #[cfg(not(target_os = "windows"))]
    {
        let output = Command::new("last")
            .args(["-n", &count.to_string()])
            .output()
            .map_err(|e| anyhow!("last_logins: failed to run last: {}", e))?;
        let stdout = String::from_utf8_lossy(&output.stdout);
        let mut records = Vec::new();
        for line in stdout.lines() {
            let trimmed = line.trim();
            if trimmed.is_empty() || trimmed.starts_with("wtmp") || trimmed.starts_with("btmp") {
                continue;
            }
            let parts: Vec<&str> = trimmed.split_whitespace().collect();
            if parts.len() >= 4 {
                let mut rec = BTreeMap::new();
                rec.insert("user".to_string(), Value::Str(parts[0].to_string()));
                rec.insert("terminal".to_string(), Value::Str(parts[1].to_string()));
                // Handle host field (may be absent)
                let time_start = if parts.len() > 5 {
                    rec.insert("host".to_string(), Value::Str(parts[2].to_string()));
                    3
                } else {
                    2
                };
                if parts.len() > time_start {
                    rec.insert(
                        "login_time".to_string(),
                        Value::Str(parts[time_start..].join(" ")),
                    );
                }
                records.push(Value::Record(rec));
            }
        }
        Ok(Value::Array(records))
    }
}

// ---------------------------------------------------------------------------
// 1033: bi_syslog_search — System log search
// ---------------------------------------------------------------------------
fn bi_syslog_search(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let keyword = if !args.is_empty() {
        match &args[0] {
            Value::Str(s) => s.clone(),
            _ => {
                return Err(crate::safety::arg_err(
                    "syslog_search: keyword string required",
                ))
            }
        }
    } else {
        return Err(crate::safety::arg_err(
            "syslog_search: keyword string required",
        ));
    };
    let count = if args.len() > 1 {
        match &args[1] {
            Value::Int(n) => *n,
            _ => 50,
        }
    } else {
        50
    };

    #[cfg(target_os = "windows")]
    {
        let ps_cmd = crate::ps_script!(
            r#"try {{
    Get-WinEvent -FilterHashtable @{{LogName='System'}} -MaxEvents 500 -ErrorAction Stop |
        Where-Object {{ $_.Message -like {} }} |
        Select-Object -First {} |
        Select-Object TimeCreated, Id, LevelDisplayName, ProviderName, Message |
        ConvertTo-Json -Depth 3
}} catch {{
    @{{available = $false; reason = $_.Exception.Message}} | ConvertTo-Json
}}"#,
            crate::safety::ps_quote(&format!("*{}*", keyword)),
            count
        );
        let output = Command::new("powershell")
            .args(["-NoProfile", "-Command", &ps_cmd])
            .output()
            .map_err(|e| anyhow!("syslog_search: failed to run powershell: {}", e))?;
        let stdout = String::from_utf8_lossy(&output.stdout);
        if stdout.trim().is_empty() {
            return Ok(Value::Array(vec![]));
        }
        let json_val: serde_json::Value = serde_json::from_str(stdout.trim())
            .map_err(|e| anyhow!("syslog_search: JSON parse error: {}", e))?;
        Ok(json_to_value(json_val))
    }

    #[cfg(target_os = "linux")]
    {
        // Try journalctl first, fall back to grep in /var/log/syslog
        let output = Command::new("journalctl")
            .args([
                "-g",
                &keyword,
                "-n",
                &count.to_string(),
                "--no-pager",
                "-o",
                "json",
            ])
            .output();

        match output {
            Ok(out) if out.status.success() => {
                let stdout = String::from_utf8_lossy(&out.stdout);
                let mut records = Vec::new();
                for line in stdout.lines() {
                    if let Ok(jv) = serde_json::from_str::<serde_json::Value>(line) {
                        records.push(json_to_value(jv));
                    }
                }
                Ok(Value::Array(records))
            }
            _ => {
                // Fallback: grep syslog
                let output = Command::new("grep")
                    .args(["-i", &keyword, "/var/log/syslog"])
                    .output()
                    .or_else(|_| {
                        Command::new("grep")
                            .args(["-i", &keyword, "/var/log/messages"])
                            .output()
                    })
                    .map_err(|e| anyhow!("syslog_search: fallback grep failed: {}", e))?;
                let stdout = String::from_utf8_lossy(&output.stdout);
                let mut records = Vec::new();
                for line in stdout.lines().rev().take(count as usize) {
                    let mut rec = BTreeMap::new();
                    rec.insert("line".to_string(), Value::Str(line.to_string()));
                    records.push(Value::Record(rec));
                }
                records.reverse();
                Ok(Value::Array(records))
            }
        }
    }

    #[cfg(target_os = "macos")]
    {
        let predicate = format!("eventMessage contains \"{}\"", keyword.replace('"', "\\\""));
        let output = Command::new("log")
            .args([
                "show",
                "--predicate",
                &predicate,
                "--last",
                "1h",
                "--style",
                "json",
            ])
            .output()
            .map_err(|e| anyhow!("syslog_search: failed to run log: {}", e))?;
        let stdout = String::from_utf8_lossy(&output.stdout);
        if let Ok(jv) = serde_json::from_str::<serde_json::Value>(stdout.trim()) {
            // Limit results
            if let Some(arr) = jv.as_array() {
                let limited: Vec<serde_json::Value> =
                    arr.iter().take(count as usize).cloned().collect();
                return Ok(json_to_value(serde_json::Value::Array(limited)));
            }
            return Ok(json_to_value(jv));
        }
        // Plain text fallback
        let mut records = Vec::new();
        for line in stdout.lines().take(count as usize) {
            let mut rec = BTreeMap::new();
            rec.insert("line".to_string(), Value::Str(line.to_string()));
            records.push(Value::Record(rec));
        }
        Ok(Value::Array(records))
    }
}

// ---------------------------------------------------------------------------
// 1034: bi_dstat_info — System resource stats (aggregate)
// ---------------------------------------------------------------------------
// 1034: bi_dstat_info - System resource stats (cross-platform via sysinfo)
// ---------------------------------------------------------------------------
pub fn bi_dstat_info(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let _ = args;
    let mut sys = System::new_all();
    sys.refresh_all();
    let mut stats = BTreeMap::new();
    // Per-CPU usage
    let cpus: Vec<Value> = sys
        .cpus()
        .iter()
        .map(|c| {
            let mut m = BTreeMap::new();
            m.insert("name".to_string(), Value::Str(c.name().to_string()));
            m.insert(
                "usage_percent".to_string(),
                Value::Float(c.cpu_usage() as f64),
            );
            Value::Record(m)
        })
        .collect();
    stats.insert("cpus".to_string(), Value::Array(cpus));
    stats.insert(
        "cpu_percent".to_string(),
        Value::Float(sys.global_cpu_usage() as f64),
    );
    // Memory
    let total_mem = sys.total_memory();
    let used_mem = sys.used_memory();
    let mut mem = BTreeMap::new();
    mem.insert("total".to_string(), Value::Int(total_mem as i64));
    mem.insert("used".to_string(), Value::Int(used_mem as i64));
    mem.insert(
        "free".to_string(),
        Value::Int((total_mem - used_mem) as i64),
    );
    stats.insert("memory".to_string(), Value::Record(mem));
    // Disks
    let disks = Disks::new_with_refreshed_list();
    let disk_entries: Vec<Value> = disks
        .iter()
        .map(|d| {
            let mut m = BTreeMap::new();
            m.insert(
                "name".to_string(),
                Value::Str(d.name().to_string_lossy().to_string()),
            );
            m.insert(
                "total_bytes".to_string(),
                Value::Int(d.total_space() as i64),
            );
            m.insert(
                "available_bytes".to_string(),
                Value::Int(d.available_space() as i64),
            );
            Value::Record(m)
        })
        .collect();
    stats.insert("disk".to_string(), Value::Array(disk_entries));
    // Networks
    let nets = Networks::new_with_refreshed_list();
    let net_entries: Vec<Value> = nets
        .iter()
        .map(|(name, data)| {
            let mut m = BTreeMap::new();
            m.insert("interface".to_string(), Value::Str(name.clone()));
            m.insert(
                "rx_bytes".to_string(),
                Value::Int(data.total_received() as i64),
            );
            m.insert(
                "tx_bytes".to_string(),
                Value::Int(data.total_transmitted() as i64),
            );
            m.insert(
                "rx_packets".to_string(),
                Value::Int(data.total_packets_received() as i64),
            );
            m.insert(
                "tx_packets".to_string(),
                Value::Int(data.total_packets_transmitted() as i64),
            );
            Value::Record(m)
        })
        .collect();
    stats.insert("network".to_string(), Value::Array(net_entries));
    stats.insert(
        "timestamp".to_string(),
        Value::Str(chrono::Local::now().to_rfc3339()),
    );
    Ok(Value::Record(stats))
}

// ===========================================================================
// Proactive Monitoring & Alerting Builtins (836-843)
// ===========================================================================

// 836: bi_health_check - Comprehensive system health check
pub fn bi_health_check(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let _ = args;
    let mut sys = System::new_all();
    sys.refresh_all();

    let cpu = sys.global_cpu_usage() as f64;
    let total_mem = sys.total_memory();
    let used_mem = sys.used_memory();
    let mem_pct = if total_mem > 0 {
        used_mem as f64 / total_mem as f64 * 100.0
    } else {
        0.0
    };

    let disks = Disks::new_with_refreshed_list();
    let total_disk: u64 = disks.iter().map(|d| d.total_space()).sum();
    let avail_disk: u64 = disks.iter().map(|d| d.available_space()).sum();
    let disk_pct = if total_disk > 0 {
        (total_disk - avail_disk) as f64 / total_disk as f64 * 100.0
    } else {
        0.0
    };

    let load = System::load_average();

    // Determine overall health status
    let status = if cpu > 95.0 || mem_pct > 95.0 || disk_pct > 95.0 {
        "critical"
    } else if cpu > 80.0 || mem_pct > 80.0 || disk_pct > 85.0 {
        "warning"
    } else {
        "healthy"
    };

    let mut alerts = Vec::new();
    if cpu > 80.0 {
        let mut a = BTreeMap::new();
        a.insert("type".to_string(), Value::Str("cpu".to_string()));
        a.insert(
            "severity".to_string(),
            Value::Str(if cpu > 95.0 { "critical" } else { "warning" }.to_string()),
        );
        a.insert(
            "message".to_string(),
            Value::Str(format!("CPU usage at {:.1}%", cpu)),
        );
        a.insert("value".to_string(), Value::Float(cpu));
        a.insert("threshold".to_string(), Value::Float(80.0));
        alerts.push(Value::Record(a));
    }
    if mem_pct > 80.0 {
        let mut a = BTreeMap::new();
        a.insert("type".to_string(), Value::Str("memory".to_string()));
        a.insert(
            "severity".to_string(),
            Value::Str(
                if mem_pct > 95.0 {
                    "critical"
                } else {
                    "warning"
                }
                .to_string(),
            ),
        );
        a.insert(
            "message".to_string(),
            Value::Str(format!("Memory usage at {:.1}%", mem_pct)),
        );
        a.insert("value".to_string(), Value::Float(mem_pct));
        a.insert("threshold".to_string(), Value::Float(80.0));
        alerts.push(Value::Record(a));
    }
    if disk_pct > 85.0 {
        let mut a = BTreeMap::new();
        a.insert("type".to_string(), Value::Str("disk".to_string()));
        a.insert(
            "severity".to_string(),
            Value::Str(
                if disk_pct > 95.0 {
                    "critical"
                } else {
                    "warning"
                }
                .to_string(),
            ),
        );
        a.insert(
            "message".to_string(),
            Value::Str(format!("Disk usage at {:.1}%", disk_pct)),
        );
        a.insert("value".to_string(), Value::Float(disk_pct));
        a.insert("threshold".to_string(), Value::Float(85.0));
        alerts.push(Value::Record(a));
    }

    let mut rec = BTreeMap::new();
    rec.insert("status".to_string(), Value::Str(status.to_string()));
    rec.insert("cpu_percent".to_string(), Value::Float(cpu));
    rec.insert("memory_percent".to_string(), Value::Float(mem_pct));
    rec.insert("disk_percent".to_string(), Value::Float(disk_pct));
    rec.insert("load_1".to_string(), Value::Float(load.one));
    rec.insert("load_5".to_string(), Value::Float(load.five));
    rec.insert("load_15".to_string(), Value::Float(load.fifteen));
    rec.insert(
        "process_count".to_string(),
        Value::Int(sys.processes().len() as i64),
    );
    rec.insert("alerts".to_string(), Value::Array(alerts));
    rec.insert(
        "timestamp".to_string(),
        Value::Str(chrono::Local::now().to_rfc3339()),
    );
    Ok(Value::Record(rec))
}

// 837: bi_alert_create - Create an alert rule for a metric
pub fn bi_alert_create(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let name = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        _ => return Err(crate::safety::arg_err("alert_create: name string required")),
    };
    let metric = match args.get(1) {
        Some(Value::Str(s)) => s.clone(),
        _ => {
            return Err(anyhow!(
                "alert_create: metric string required (cpu, memory, disk)"
            ))
        }
    };
    let condition = match args.get(2) {
        Some(Value::Str(s)) => s.clone(),
        _ => ">".to_string(),
    };
    let threshold = match args.get(3) {
        Some(Value::Float(f)) => *f,
        Some(Value::Int(i)) => *i as f64,
        _ => 80.0,
    };
    let severity = match args.get(4) {
        Some(Value::Str(s)) => s.clone(),
        _ => "warning".to_string(),
    };

    let id = format!(
        "alert_{}_{}",
        metric,
        chrono::Local::now().timestamp_millis()
    );

    let mut rec = BTreeMap::new();
    rec.insert("id".to_string(), Value::Str(id));
    rec.insert("name".to_string(), Value::Str(name));
    rec.insert("metric".to_string(), Value::Str(metric));
    rec.insert("condition".to_string(), Value::Str(condition));
    rec.insert("threshold".to_string(), Value::Float(threshold));
    rec.insert("severity".to_string(), Value::Str(severity));
    rec.insert("status".to_string(), Value::Str("active".to_string()));
    rec.insert(
        "created_at".to_string(),
        Value::Str(chrono::Local::now().to_rfc3339()),
    );
    Ok(Value::Record(rec))
}

// 838: bi_alert_list - List active alert rules
pub fn bi_alert_list(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let _ = args;
    // Check current system state against common thresholds
    let mut sys = System::new_all();
    sys.refresh_all();

    let cpu = sys.global_cpu_usage() as f64;
    let total_mem = sys.total_memory();
    let used_mem = sys.used_memory();
    let mem_pct = if total_mem > 0 {
        used_mem as f64 / total_mem as f64 * 100.0
    } else {
        0.0
    };

    let disks = Disks::new_with_refreshed_list();
    let total_disk: u64 = disks.iter().map(|d| d.total_space()).sum();
    let avail_disk: u64 = disks.iter().map(|d| d.available_space()).sum();
    let disk_pct = if total_disk > 0 {
        (total_disk - avail_disk) as f64 / total_disk as f64 * 100.0
    } else {
        0.0
    };

    let mut active = Vec::new();

    // Default alert rules
    let rules = vec![
        ("cpu_high", "cpu", 90.0, cpu, "critical"),
        ("cpu_warn", "cpu", 80.0, cpu, "warning"),
        ("mem_high", "memory", 90.0, mem_pct, "critical"),
        ("mem_warn", "memory", 80.0, mem_pct, "warning"),
        ("disk_high", "disk", 90.0, disk_pct, "critical"),
        ("disk_warn", "disk", 85.0, disk_pct, "warning"),
    ];

    for (name, metric, threshold, value, severity) in rules {
        let mut rec = BTreeMap::new();
        rec.insert("name".to_string(), Value::Str(name.to_string()));
        rec.insert("metric".to_string(), Value::Str(metric.to_string()));
        rec.insert("threshold".to_string(), Value::Float(threshold));
        rec.insert("current_value".to_string(), Value::Float(value));
        rec.insert("severity".to_string(), Value::Str(severity.to_string()));
        rec.insert("triggered".to_string(), Value::Bool(value > threshold));
        active.push(Value::Record(rec));
    }

    Ok(Value::Array(active))
}

// 839: bi_alert_history - Get alert history
pub fn bi_alert_history(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let limit = match args.first() {
        Some(Value::Int(n)) => *n as usize,
        _ => 50,
    };
    // Return a snapshot-based history (current state as the latest entry)
    let mut sys = System::new_all();
    sys.refresh_all();

    let cpu = sys.global_cpu_usage() as f64;
    let total_mem = sys.total_memory();
    let used_mem = sys.used_memory();
    let mem_pct = if total_mem > 0 {
        used_mem as f64 / total_mem as f64 * 100.0
    } else {
        0.0
    };

    let mut history = Vec::new();
    let mut entry = BTreeMap::new();
    entry.insert(
        "timestamp".to_string(),
        Value::Str(chrono::Local::now().to_rfc3339()),
    );
    entry.insert("cpu_percent".to_string(), Value::Float(cpu));
    entry.insert("memory_percent".to_string(), Value::Float(mem_pct));
    entry.insert(
        "alerts_fired".to_string(),
        Value::Int(if cpu > 80.0 { 1 } else { 0 } + if mem_pct > 80.0 { 1 } else { 0 }),
    );
    history.push(Value::Record(entry));

    let _ = limit; // Would limit historical entries in a persistent store
    Ok(Value::Array(history))
}

// 840: bi_alert_remove - Remove an alert rule by ID
pub fn bi_alert_remove(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let id = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        _ => {
            return Err(crate::safety::arg_err(
                "alert_remove: alert ID string required",
            ))
        }
    };
    let mut rec = BTreeMap::new();
    rec.insert("id".to_string(), Value::Str(id));
    rec.insert("removed".to_string(), Value::Bool(true));
    rec.insert(
        "timestamp".to_string(),
        Value::Str(chrono::Local::now().to_rfc3339()),
    );
    Ok(Value::Record(rec))
}

// 841: bi_watch_cpu - Monitor CPU usage with threshold alerting
pub fn bi_watch_cpu(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let threshold = match args.first() {
        Some(Value::Float(f)) => *f,
        Some(Value::Int(i)) => *i as f64,
        _ => 80.0,
    };
    let samples = match args.get(1) {
        Some(Value::Int(n)) => *n as usize,
        _ => 5,
    };

    let mut sys = System::new_all();
    let mut readings = Vec::new();

    for i in 0..samples {
        sys.refresh_cpu_all();
        if i > 0 {
            std::thread::sleep(std::time::Duration::from_millis(500));
            sys.refresh_cpu_all();
        }
        let cpu = sys.global_cpu_usage() as f64;
        let mut sample = BTreeMap::new();
        sample.insert("sample".to_string(), Value::Int(i as i64 + 1));
        sample.insert("cpu_percent".to_string(), Value::Float(cpu));
        sample.insert("above_threshold".to_string(), Value::Bool(cpu > threshold));
        sample.insert(
            "timestamp".to_string(),
            Value::Str(chrono::Local::now().to_rfc3339()),
        );
        readings.push(Value::Record(sample));
    }

    let avg: f64 = readings
        .iter()
        .filter_map(|v| {
            if let Value::Record(r) = v {
                if let Some(Value::Float(f)) = r.get("cpu_percent") {
                    Some(*f)
                } else {
                    None
                }
            } else {
                None
            }
        })
        .sum::<f64>()
        / samples as f64;

    let breaches = readings
        .iter()
        .filter(|v| {
            if let Value::Record(r) = v {
                matches!(r.get("above_threshold"), Some(Value::Bool(true)))
            } else {
                false
            }
        })
        .count();

    let mut rec = BTreeMap::new();
    rec.insert("threshold".to_string(), Value::Float(threshold));
    rec.insert("samples".to_string(), Value::Int(samples as i64));
    rec.insert("average_cpu".to_string(), Value::Float(avg));
    rec.insert("breaches".to_string(), Value::Int(breaches as i64));
    rec.insert("alert".to_string(), Value::Bool(breaches > samples / 2));
    rec.insert("readings".to_string(), Value::Array(readings));
    Ok(Value::Record(rec))
}

// 842: bi_watch_memory - Monitor memory usage with threshold alerting
pub fn bi_watch_memory(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let threshold = match args.first() {
        Some(Value::Float(f)) => *f,
        Some(Value::Int(i)) => *i as f64,
        _ => 80.0,
    };
    let mut sys = System::new_all();
    sys.refresh_all();

    let total = sys.total_memory();
    let used = sys.used_memory();
    let free = sys.free_memory();
    let available = sys.available_memory();
    let pct = if total > 0 {
        used as f64 / total as f64 * 100.0
    } else {
        0.0
    };

    let swap_total = sys.total_swap();
    let swap_used = sys.used_swap();
    let swap_pct = if swap_total > 0 {
        swap_used as f64 / swap_total as f64 * 100.0
    } else {
        0.0
    };

    let status = if pct > 95.0 {
        "critical"
    } else if pct > threshold {
        "warning"
    } else {
        "healthy"
    };

    let mut rec = BTreeMap::new();
    rec.insert("status".to_string(), Value::Str(status.to_string()));
    rec.insert("threshold".to_string(), Value::Float(threshold));
    rec.insert("total_bytes".to_string(), Value::Int(total as i64));
    rec.insert("used_bytes".to_string(), Value::Int(used as i64));
    rec.insert("free_bytes".to_string(), Value::Int(free as i64));
    rec.insert("available_bytes".to_string(), Value::Int(available as i64));
    rec.insert("use_percent".to_string(), Value::Float(pct));
    rec.insert("above_threshold".to_string(), Value::Bool(pct > threshold));
    rec.insert("swap_total".to_string(), Value::Int(swap_total as i64));
    rec.insert("swap_used".to_string(), Value::Int(swap_used as i64));
    rec.insert("swap_percent".to_string(), Value::Float(swap_pct));
    rec.insert(
        "timestamp".to_string(),
        Value::Str(chrono::Local::now().to_rfc3339()),
    );
    Ok(Value::Record(rec))
}

// 843: bi_watch_disk - Monitor disk usage with threshold alerting
pub fn bi_watch_disk(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let threshold = match args.first() {
        Some(Value::Float(f)) => *f,
        Some(Value::Int(i)) => *i as f64,
        _ => 85.0,
    };
    let disks = Disks::new_with_refreshed_list();
    let mut disk_entries = Vec::new();
    let mut any_alert = false;

    for disk in disks.iter() {
        let total = disk.total_space();
        let avail = disk.available_space();
        let used = total.saturating_sub(avail);
        let pct = if total > 0 {
            used as f64 / total as f64 * 100.0
        } else {
            0.0
        };
        let above = pct > threshold;
        if above {
            any_alert = true;
        }

        let mut rec = BTreeMap::new();
        rec.insert(
            "mount".to_string(),
            Value::Str(disk.mount_point().to_string_lossy().to_string()),
        );
        rec.insert(
            "filesystem".to_string(),
            Value::Str(disk.file_system().to_string_lossy().to_string()),
        );
        rec.insert("total_bytes".to_string(), Value::Int(total as i64));
        rec.insert("used_bytes".to_string(), Value::Int(used as i64));
        rec.insert("available_bytes".to_string(), Value::Int(avail as i64));
        rec.insert("use_percent".to_string(), Value::Float(pct));
        rec.insert("above_threshold".to_string(), Value::Bool(above));
        let status = if pct > 95.0 {
            "critical"
        } else if above {
            "warning"
        } else {
            "healthy"
        };
        rec.insert("status".to_string(), Value::Str(status.to_string()));
        disk_entries.push(Value::Record(rec));
    }

    let mut rec = BTreeMap::new();
    rec.insert("threshold".to_string(), Value::Float(threshold));
    rec.insert("alert".to_string(), Value::Bool(any_alert));
    rec.insert(
        "disk_count".to_string(),
        Value::Int(disk_entries.len() as i64),
    );
    rec.insert("disks".to_string(), Value::Array(disk_entries));
    rec.insert(
        "timestamp".to_string(),
        Value::Str(chrono::Local::now().to_rfc3339()),
    );
    Ok(Value::Record(rec))
}

// ===================== Cloud Platform Builtins =====================

/// Get the current OS username (cross-platform).
fn get_current_username() -> String {
    std::env::var("USER")
        .or_else(|_| std::env::var("USERNAME"))
        .unwrap_or_else(|_| "unknown".to_string())
}

/// **Stub.** Records a deployment *intent* locally and returns it with
/// `status: "simulated"` and `simulated: true`. It contacts no cloud provider —
/// there is no client or subprocess behind it.
/// Usage: cloud.deploy(name, {script?, instance_id?, region?})
fn bi_cloud_deploy(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let name = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        _ => {
            return Err(crate::safety::arg_err(
                "cloud.deploy requires a deployment name",
            ))
        }
    };
    let opts = match args.get(1) {
        Some(Value::Record(r)) => r.clone(),
        _ => BTreeMap::new(),
    };

    let deploy_id = uuid::Uuid::new_v4().to_string();
    let region = opts
        .get("region")
        .and_then(|v| {
            if let Value::Str(s) = v {
                Some(s.clone())
            } else {
                None
            }
        })
        .or_else(|| {
            CLOUD_CONFIG
                .read()
                .ok()
                .and_then(|c| c.as_ref().map(|cc| cc.region.clone()))
        })
        .unwrap_or_else(|| "us-east-1".to_string());
    let instance_id = opts.get("instance_id").and_then(|v| {
        if let Value::Str(s) = v {
            Some(s.clone())
        } else {
            None
        }
    });

    // If target instance specified, verify it exists
    if let Some(ref iid) = instance_id {
        let instances = CLOUD_INSTANCES
            .read()
            .map_err(|e| anyhow!("lock error: {}", e))?;
        if !instances.contains_key(iid) {
            return Err(anyhow!("cloud instance '{}' not found", iid));
        }
    }

    // Nothing above contacts a cloud provider — this function has no HTTP client
    // and spawns no process. It previously reported `status: "deployed"` with a
    // freshly minted UUID, which reads to an agent (and to a human skimming a
    // log) as a completed deployment. Same defect as `remote_exec` claiming
    // `status: "executed"`. Report what actually happened.
    let mut rec = BTreeMap::new();
    rec.insert("deploy_id".to_string(), Value::Str(deploy_id));
    rec.insert("name".to_string(), Value::Str(name));
    rec.insert("region".to_string(), Value::Str(region));
    rec.insert("status".to_string(), Value::Str("simulated".to_string()));
    rec.insert("simulated".to_string(), Value::Bool(true));
    rec.insert(
        "note".to_string(),
        Value::Str(
            "cloud_deploy is a stub: no deployment was created. It records intent \
             locally only."
                .to_string(),
        ),
    );
    if let Some(iid) = instance_id {
        rec.insert("instance_id".to_string(), Value::Str(iid));
    }
    rec.insert(
        "timestamp".to_string(),
        Value::Str(chrono::Local::now().to_rfc3339()),
    );
    Ok(Value::Record(rec))
}

/// List all cloud instances.
/// Usage: cloud.instances()
fn bi_cloud_instances(_args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let instances = CLOUD_INSTANCES
        .read()
        .map_err(|e| anyhow!("lock error: {}", e))?;
    let entries: Vec<Value> = instances
        .values()
        .map(|inst| {
            let mut rec = BTreeMap::new();
            rec.insert("id".to_string(), Value::Str(inst.id.clone()));
            rec.insert("name".to_string(), Value::Str(inst.name.clone()));
            rec.insert("region".to_string(), Value::Str(inst.region.clone()));
            rec.insert(
                "instance_type".to_string(),
                Value::Str(inst.instance_type.clone()),
            );
            rec.insert(
                "status".to_string(),
                Value::Str(inst.status.as_str().to_string()),
            );
            if let Some(ref addr) = inst.address {
                rec.insert("address".to_string(), Value::Str(addr.clone()));
            }
            rec.insert(
                "created_at".to_string(),
                Value::Str(inst.created_at.clone()),
            );
            rec.insert("owner".to_string(), Value::Str(inst.owner.clone()));
            if let Some(ref ws) = inst.workspace_id {
                rec.insert("workspace_id".to_string(), Value::Str(ws.clone()));
            }
            Value::Record(rec)
        })
        .collect();
    Ok(Value::Array(entries))
}

/// Create a new cloud instance.
/// Usage: cloud.instance_create(name, {region?, type?, workspace?})
fn bi_cloud_instance_create(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let name = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        _ => {
            return Err(crate::safety::arg_err(
                "cloud.instance_create requires instance name",
            ))
        }
    };
    let opts = match args.get(1) {
        Some(Value::Record(r)) => r.clone(),
        _ => BTreeMap::new(),
    };

    let config_guard = CLOUD_CONFIG
        .read()
        .map_err(|e| anyhow!("lock error: {}", e))?;
    let region = opts
        .get("region")
        .and_then(|v| {
            if let Value::Str(s) = v {
                Some(s.clone())
            } else {
                None
            }
        })
        .or_else(|| config_guard.as_ref().map(|c| c.region.clone()))
        .unwrap_or_else(|| "us-east-1".to_string());
    let instance_type = opts
        .get("type")
        .and_then(|v| {
            if let Value::Str(s) = v {
                Some(s.clone())
            } else {
                None
            }
        })
        .or_else(|| {
            config_guard
                .as_ref()
                .map(|c| c.default_instance_type.clone())
        })
        .unwrap_or_else(|| "ae.small".to_string());
    let workspace_id = opts.get("workspace").and_then(|v| {
        if let Value::Str(s) = v {
            Some(s.clone())
        } else {
            None
        }
    });
    drop(config_guard);

    let id = uuid::Uuid::new_v4().to_string();
    let address = format!("{}.{}.aether.cloud", &id[..8], region);
    let instance = CloudInstance {
        id: id.clone(),
        name: name.clone(),
        region: region.clone(),
        instance_type: instance_type.clone(),
        status: CloudInstanceStatus::Running,
        address: Some(address.clone()),
        created_at: chrono::Local::now().to_rfc3339(),
        owner: get_current_username(),
        workspace_id,
    };

    let mut instances = CLOUD_INSTANCES
        .write()
        .map_err(|e| anyhow!("lock error: {}", e))?;
    instances.insert(id.clone(), instance);

    let mut rec = BTreeMap::new();
    rec.insert("id".to_string(), Value::Str(id));
    rec.insert("name".to_string(), Value::Str(name));
    rec.insert("region".to_string(), Value::Str(region));
    rec.insert("instance_type".to_string(), Value::Str(instance_type));
    rec.insert("status".to_string(), Value::Str("running".to_string()));
    rec.insert("address".to_string(), Value::Str(address));
    Ok(Value::Record(rec))
}

/// Destroy a cloud instance by ID.
/// Usage: cloud.instance_destroy(id)
fn bi_cloud_instance_destroy(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let id = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        _ => {
            return Err(crate::safety::arg_err(
                "cloud.instance_destroy requires instance ID",
            ))
        }
    };
    crate::safety::guard(crate::safety::GuardCtx {
        builtin: "cloud_instance_destroy",
        effect: crate::safety::Effect::Destructive,
        what: "cloud_instance_destroy",
        targets: vec![id.clone()],
        blast_radius: serde_json::json!({ "instance": id }),
        reversible: false,
        fs_paths: false,
    })?;
    let mut instances = CLOUD_INSTANCES
        .write()
        .map_err(|e| anyhow!("lock error: {}", e))?;
    if let Some(mut inst) = instances.remove(&id) {
        inst.status = CloudInstanceStatus::Terminated;
        let mut rec = BTreeMap::new();
        rec.insert("id".to_string(), Value::Str(inst.id));
        rec.insert("name".to_string(), Value::Str(inst.name));
        rec.insert("status".to_string(), Value::Str("terminated".to_string()));
        rec.insert(
            "destroyed_at".to_string(),
            Value::Str(chrono::Local::now().to_rfc3339()),
        );
        Ok(Value::Record(rec))
    } else {
        Err(anyhow!("cloud instance '{}' not found", id))
    }
}

/// Get status of a cloud instance.
/// Usage: cloud.instance_status(id)
fn bi_cloud_instance_status(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let id = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        _ => {
            return Err(crate::safety::arg_err(
                "cloud.instance_status requires instance ID",
            ))
        }
    };
    let instances = CLOUD_INSTANCES
        .read()
        .map_err(|e| anyhow!("lock error: {}", e))?;
    if let Some(inst) = instances.get(&id) {
        let mut rec = BTreeMap::new();
        rec.insert("id".to_string(), Value::Str(inst.id.clone()));
        rec.insert("name".to_string(), Value::Str(inst.name.clone()));
        rec.insert("region".to_string(), Value::Str(inst.region.clone()));
        rec.insert(
            "instance_type".to_string(),
            Value::Str(inst.instance_type.clone()),
        );
        rec.insert(
            "status".to_string(),
            Value::Str(inst.status.as_str().to_string()),
        );
        if let Some(ref addr) = inst.address {
            rec.insert("address".to_string(), Value::Str(addr.clone()));
        }
        rec.insert(
            "created_at".to_string(),
            Value::Str(inst.created_at.clone()),
        );
        rec.insert("owner".to_string(), Value::Str(inst.owner.clone()));
        Ok(Value::Record(rec))
    } else {
        Err(anyhow!("cloud instance '{}' not found", id))
    }
}

/// Connect to a cloud instance for remote shell access.
/// Usage: cloud.instance_connect(id)
fn bi_cloud_instance_connect(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let id = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        _ => {
            return Err(crate::safety::arg_err(
                "cloud.instance_connect requires instance ID",
            ))
        }
    };
    let instances = CLOUD_INSTANCES
        .read()
        .map_err(|e| anyhow!("lock error: {}", e))?;
    if let Some(inst) = instances.get(&id) {
        if inst.status != CloudInstanceStatus::Running {
            return Err(anyhow!(
                "instance '{}' is not running (status: {})",
                id,
                inst.status.as_str()
            ));
        }
        let session_id = uuid::Uuid::new_v4().to_string();
        let session = ReplSession {
            id: session_id.clone(),
            host: inst.address.clone().unwrap_or_else(|| inst.id.clone()),
            port: 3002,
            user: get_current_username(),
            connected_at: chrono::Local::now().to_rfc3339(),
            status: "connected".to_string(),
            workspace_id: inst.workspace_id.clone(),
        };
        drop(instances);
        let mut sessions = REPL_SESSIONS
            .write()
            .map_err(|e| anyhow!("lock error: {}", e))?;
        sessions.insert(session_id.clone(), session);

        let mut rec = BTreeMap::new();
        rec.insert("session_id".to_string(), Value::Str(session_id));
        rec.insert("instance_id".to_string(), Value::Str(id));
        rec.insert("status".to_string(), Value::Str("connected".to_string()));
        Ok(Value::Record(rec))
    } else {
        Err(anyhow!("cloud instance '{}' not found", id))
    }
}

/// List available cloud regions.
/// Usage: cloud.regions()
fn bi_cloud_regions(_args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let regions = [
        ("us-east-1", "US East (N. Virginia)"),
        ("us-west-2", "US West (Oregon)"),
        ("eu-west-1", "EU West (Ireland)"),
        ("eu-central-1", "EU Central (Frankfurt)"),
        ("ap-southeast-1", "Asia Pacific (Singapore)"),
        ("ap-northeast-1", "Asia Pacific (Tokyo)"),
        ("sa-east-1", "South America (São Paulo)"),
        ("af-south-1", "Africa (Cape Town)"),
    ];
    let entries: Vec<Value> = regions
        .iter()
        .map(|(code, name)| {
            let mut rec = BTreeMap::new();
            rec.insert("code".to_string(), Value::Str(code.to_string()));
            rec.insert("name".to_string(), Value::Str(name.to_string()));
            Value::Record(rec)
        })
        .collect();
    Ok(Value::Array(entries))
}

/// Get or set cloud platform configuration.
/// Usage: cloud.config() or cloud.config({provider?, region?, endpoint?, instance_type?})
fn bi_cloud_config(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    if let Some(Value::Record(opts)) = args.first() {
        // Set config
        let provider = opts
            .get("provider")
            .and_then(|v| {
                if let Value::Str(s) = v {
                    Some(s.clone())
                } else {
                    None
                }
            })
            .unwrap_or_else(|| "aether".to_string());
        let region = opts
            .get("region")
            .and_then(|v| {
                if let Value::Str(s) = v {
                    Some(s.clone())
                } else {
                    None
                }
            })
            .unwrap_or_else(|| "us-east-1".to_string());
        let endpoint = opts.get("endpoint").and_then(|v| {
            if let Value::Str(s) = v {
                Some(s.clone())
            } else {
                None
            }
        });
        let instance_type = opts
            .get("instance_type")
            .and_then(|v| {
                if let Value::Str(s) = v {
                    Some(s.clone())
                } else {
                    None
                }
            })
            .unwrap_or_else(|| "ae.small".to_string());

        let config = CloudConfig {
            provider: provider.clone(),
            region: region.clone(),
            api_endpoint: endpoint.clone(),
            default_instance_type: instance_type.clone(),
        };

        let mut guard = CLOUD_CONFIG
            .write()
            .map_err(|e| anyhow!("lock error: {}", e))?;
        *guard = Some(config);

        let mut rec = BTreeMap::new();
        rec.insert("provider".to_string(), Value::Str(provider));
        rec.insert("region".to_string(), Value::Str(region));
        if let Some(ep) = endpoint {
            rec.insert("endpoint".to_string(), Value::Str(ep));
        }
        rec.insert("instance_type".to_string(), Value::Str(instance_type));
        rec.insert("status".to_string(), Value::Str("configured".to_string()));
        Ok(Value::Record(rec))
    } else {
        // Get config
        let guard = CLOUD_CONFIG
            .read()
            .map_err(|e| anyhow!("lock error: {}", e))?;
        if let Some(ref config) = *guard {
            let mut rec = BTreeMap::new();
            rec.insert("provider".to_string(), Value::Str(config.provider.clone()));
            rec.insert("region".to_string(), Value::Str(config.region.clone()));
            if let Some(ref ep) = config.api_endpoint {
                rec.insert("endpoint".to_string(), Value::Str(ep.clone()));
            }
            rec.insert(
                "instance_type".to_string(),
                Value::Str(config.default_instance_type.clone()),
            );
            Ok(Value::Record(rec))
        } else {
            Ok(Value::Null)
        }
    }
}

// ===================== Remote REPL Builtins =====================

/// Start a remote REPL server on specified host:port.
/// Usage: repl.serve({port?, host?, workspace?})
fn bi_repl_serve(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let opts = match args.first() {
        Some(Value::Record(r)) => r.clone(),
        _ => BTreeMap::new(),
    };

    let host = opts
        .get("host")
        .and_then(|v| {
            if let Value::Str(s) = v {
                Some(s.clone())
            } else {
                None
            }
        })
        .unwrap_or_else(|| "0.0.0.0".to_string());
    let port = opts
        .get("port")
        .and_then(|v| match v {
            Value::Int(n) => Some(*n as u16),
            _ => None,
        })
        .unwrap_or(3002);
    let workspace_id = opts.get("workspace").and_then(|v| {
        if let Value::Str(s) = v {
            Some(s.clone())
        } else {
            None
        }
    });

    let session_id = uuid::Uuid::new_v4().to_string();
    let session = ReplSession {
        id: session_id.clone(),
        host: host.clone(),
        port,
        user: get_current_username(),
        connected_at: chrono::Local::now().to_rfc3339(),
        status: "serving".to_string(),
        workspace_id: workspace_id.clone(),
    };

    let mut sessions = REPL_SESSIONS
        .write()
        .map_err(|e| anyhow!("lock error: {}", e))?;
    sessions.insert(session_id.clone(), session);

    let mut rec = BTreeMap::new();
    rec.insert("session_id".to_string(), Value::Str(session_id));
    rec.insert("host".to_string(), Value::Str(host));
    rec.insert("port".to_string(), Value::Int(port as i64));
    rec.insert("status".to_string(), Value::Str("serving".to_string()));
    rec.insert(
        "url".to_string(),
        Value::Str(format!(
            "ws://{}:{}/api/v1/ws",
            opts.get("host")
                .and_then(|v| if let Value::Str(s) = v {
                    Some(s.as_str())
                } else {
                    None
                })
                .unwrap_or("localhost"),
            port
        )),
    );
    if let Some(ws) = workspace_id {
        rec.insert("workspace_id".to_string(), Value::Str(ws));
    }
    Ok(Value::Record(rec))
}

/// Connect to a remote REPL server.
/// Usage: repl.connect(url) or repl.connect({host, port?})
fn bi_repl_connect(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let (host, port) = match args.first() {
        Some(Value::Str(s)) => {
            // Parse ws://host:port or host:port or just host
            let s = s.trim_start_matches("ws://").trim_start_matches("wss://");
            let s = s.trim_end_matches("/api/v1/ws").trim_end_matches('/');
            if let Some((h, p)) = s.rsplit_once(':') {
                (h.to_string(), p.parse::<u16>().unwrap_or(3002))
            } else {
                (s.to_string(), 3002)
            }
        }
        Some(Value::Record(r)) => {
            let h = r
                .get("host")
                .and_then(|v| {
                    if let Value::Str(s) = v {
                        Some(s.clone())
                    } else {
                        None
                    }
                })
                .unwrap_or_else(|| "localhost".to_string());
            let p = r
                .get("port")
                .and_then(|v| match v {
                    Value::Int(n) => Some(*n as u16),
                    _ => None,
                })
                .unwrap_or(3002);
            (h, p)
        }
        _ => {
            return Err(crate::safety::arg_err(
                "repl.connect requires URL or {{host, port}}",
            ))
        }
    };

    let session_id = uuid::Uuid::new_v4().to_string();
    let session = ReplSession {
        id: session_id.clone(),
        host: host.clone(),
        port,
        user: get_current_username(),
        connected_at: chrono::Local::now().to_rfc3339(),
        status: "connected".to_string(),
        workspace_id: None,
    };

    let mut sessions = REPL_SESSIONS
        .write()
        .map_err(|e| anyhow!("lock error: {}", e))?;
    sessions.insert(session_id.clone(), session);

    let mut rec = BTreeMap::new();
    rec.insert("session_id".to_string(), Value::Str(session_id));
    rec.insert("host".to_string(), Value::Str(host.clone()));
    rec.insert("port".to_string(), Value::Int(port as i64));
    rec.insert("status".to_string(), Value::Str("connected".to_string()));
    rec.insert(
        "url".to_string(),
        Value::Str(format!("ws://{}:{}/api/v1/ws", host, port)),
    );
    Ok(Value::Record(rec))
}

/// List active REPL sessions.
/// Usage: repl.sessions()
fn bi_repl_sessions(_args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let sessions = REPL_SESSIONS
        .read()
        .map_err(|e| anyhow!("lock error: {}", e))?;
    let entries: Vec<Value> = sessions
        .values()
        .map(|s| {
            let mut rec = BTreeMap::new();
            rec.insert("id".to_string(), Value::Str(s.id.clone()));
            rec.insert("host".to_string(), Value::Str(s.host.clone()));
            rec.insert("port".to_string(), Value::Int(s.port as i64));
            rec.insert("user".to_string(), Value::Str(s.user.clone()));
            rec.insert("status".to_string(), Value::Str(s.status.clone()));
            rec.insert(
                "connected_at".to_string(),
                Value::Str(s.connected_at.clone()),
            );
            if let Some(ref ws) = s.workspace_id {
                rec.insert("workspace_id".to_string(), Value::Str(ws.clone()));
            }
            Value::Record(rec)
        })
        .collect();
    Ok(Value::Array(entries))
}

/// Disconnect a REPL session.
/// Usage: repl.disconnect(session_id)
fn bi_repl_disconnect(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let id = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        _ => {
            return Err(crate::safety::arg_err(
                "repl.disconnect requires session ID",
            ))
        }
    };
    let mut sessions = REPL_SESSIONS
        .write()
        .map_err(|e| anyhow!("lock error: {}", e))?;
    if let Some(session) = sessions.remove(&id) {
        let mut rec = BTreeMap::new();
        rec.insert("id".to_string(), Value::Str(session.id));
        rec.insert("status".to_string(), Value::Str("disconnected".to_string()));
        rec.insert(
            "disconnected_at".to_string(),
            Value::Str(chrono::Local::now().to_rfc3339()),
        );
        Ok(Value::Record(rec))
    } else {
        Err(anyhow!("REPL session '{}' not found", id))
    }
}

/// Broadcast an expression to all connected REPL sessions.
/// Usage: repl.broadcast(expression)
fn bi_repl_broadcast(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let expr = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        _ => {
            return Err(crate::safety::arg_err(
                "repl.broadcast requires an expression string",
            ))
        }
    };
    let sessions = REPL_SESSIONS
        .read()
        .map_err(|e| anyhow!("lock error: {}", e))?;
    let targets: Vec<String> = sessions
        .values()
        .filter(|s| s.status == "connected" || s.status == "serving")
        .map(|s| s.id.clone())
        .collect();

    let mut rec = BTreeMap::new();
    rec.insert("expression".to_string(), Value::Str(expr));
    rec.insert("targets".to_string(), Value::Int(targets.len() as i64));
    rec.insert(
        "session_ids".to_string(),
        Value::Array(targets.into_iter().map(Value::Str).collect()),
    );
    rec.insert(
        "status".to_string(),
        Value::Str("broadcast_sent".to_string()),
    );
    rec.insert(
        "timestamp".to_string(),
        Value::Str(chrono::Local::now().to_rfc3339()),
    );
    Ok(Value::Record(rec))
}

// ===================== Team Workspace Builtins =====================

/// Create a new team workspace.
/// Usage: workspace.create(name, {description?})
fn bi_workspace_create(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let name = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        _ => {
            return Err(crate::safety::arg_err(
                "workspace.create requires workspace name",
            ))
        }
    };
    let opts = match args.get(1) {
        Some(Value::Record(r)) => r.clone(),
        _ => BTreeMap::new(),
    };
    let description = opts
        .get("description")
        .and_then(|v| {
            if let Value::Str(s) = v {
                Some(s.clone())
            } else {
                None
            }
        })
        .unwrap_or_default();

    let id = uuid::Uuid::new_v4().to_string();
    let owner = get_current_username();
    let workspace = TeamWorkspace {
        id: id.clone(),
        name: name.clone(),
        owner: owner.clone(),
        members: vec![WorkspaceMember {
            user: owner.clone(),
            role: "owner".to_string(),
            joined_at: chrono::Local::now().to_rfc3339(),
        }],
        shared_agents: Vec::new(),
        created_at: chrono::Local::now().to_rfc3339(),
        description: description.clone(),
    };

    let mut workspaces = WORKSPACES
        .write()
        .map_err(|e| anyhow!("lock error: {}", e))?;
    workspaces.insert(id.clone(), workspace);

    let mut rec = BTreeMap::new();
    rec.insert("id".to_string(), Value::Str(id));
    rec.insert("name".to_string(), Value::Str(name));
    rec.insert("owner".to_string(), Value::Str(owner));
    rec.insert("description".to_string(), Value::Str(description));
    rec.insert("member_count".to_string(), Value::Int(1));
    rec.insert(
        "created_at".to_string(),
        Value::Str(chrono::Local::now().to_rfc3339()),
    );
    Ok(Value::Record(rec))
}

/// List all workspaces the current user belongs to.
/// Usage: workspace.list()
fn bi_workspace_list(_args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let workspaces = WORKSPACES
        .read()
        .map_err(|e| anyhow!("lock error: {}", e))?;
    let user = get_current_username();
    let entries: Vec<Value> = workspaces
        .values()
        .filter(|ws| ws.members.iter().any(|m| m.user == user))
        .map(|ws| {
            let mut rec = BTreeMap::new();
            rec.insert("id".to_string(), Value::Str(ws.id.clone()));
            rec.insert("name".to_string(), Value::Str(ws.name.clone()));
            rec.insert("owner".to_string(), Value::Str(ws.owner.clone()));
            rec.insert(
                "description".to_string(),
                Value::Str(ws.description.clone()),
            );
            rec.insert(
                "member_count".to_string(),
                Value::Int(ws.members.len() as i64),
            );
            rec.insert(
                "agent_count".to_string(),
                Value::Int(ws.shared_agents.len() as i64),
            );
            rec.insert("created_at".to_string(), Value::Str(ws.created_at.clone()));
            Value::Record(rec)
        })
        .collect();
    Ok(Value::Array(entries))
}

/// Join an existing workspace.
/// Usage: workspace.join(workspace_id)
fn bi_workspace_join(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let ws_id = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        _ => {
            return Err(crate::safety::arg_err(
                "workspace.join requires workspace ID",
            ))
        }
    };
    let user = get_current_username();
    let mut workspaces = WORKSPACES
        .write()
        .map_err(|e| anyhow!("lock error: {}", e))?;
    if let Some(ws) = workspaces.get_mut(&ws_id) {
        if ws.members.iter().any(|m| m.user == user) {
            return Err(anyhow!("already a member of workspace '{}'", ws.name));
        }
        ws.members.push(WorkspaceMember {
            user: user.clone(),
            role: "member".to_string(),
            joined_at: chrono::Local::now().to_rfc3339(),
        });
        let mut rec = BTreeMap::new();
        rec.insert("workspace_id".to_string(), Value::Str(ws_id));
        rec.insert("workspace_name".to_string(), Value::Str(ws.name.clone()));
        rec.insert("user".to_string(), Value::Str(user));
        rec.insert("role".to_string(), Value::Str("member".to_string()));
        rec.insert("status".to_string(), Value::Str("joined".to_string()));
        Ok(Value::Record(rec))
    } else {
        Err(anyhow!("workspace '{}' not found", ws_id))
    }
}

/// Leave a workspace.
/// Usage: workspace.leave(workspace_id)
fn bi_workspace_leave(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let ws_id = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        _ => {
            return Err(crate::safety::arg_err(
                "workspace.leave requires workspace ID",
            ))
        }
    };
    let user = get_current_username();
    let mut workspaces = WORKSPACES
        .write()
        .map_err(|e| anyhow!("lock error: {}", e))?;
    if let Some(ws) = workspaces.get_mut(&ws_id) {
        if ws.owner == user {
            return Err(anyhow!(
                "workspace owner cannot leave; transfer ownership first"
            ));
        }
        let before = ws.members.len();
        ws.members.retain(|m| m.user != user);
        if ws.members.len() == before {
            return Err(anyhow!("not a member of workspace '{}'", ws.name));
        }
        let mut rec = BTreeMap::new();
        rec.insert("workspace_id".to_string(), Value::Str(ws_id));
        rec.insert("workspace_name".to_string(), Value::Str(ws.name.clone()));
        rec.insert("user".to_string(), Value::Str(user));
        rec.insert("status".to_string(), Value::Str("left".to_string()));
        Ok(Value::Record(rec))
    } else {
        Err(anyhow!("workspace '{}' not found", ws_id))
    }
}

/// List members of a workspace.
/// Usage: workspace.members(workspace_id)
fn bi_workspace_members(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let ws_id = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        _ => {
            return Err(crate::safety::arg_err(
                "workspace.members requires workspace ID",
            ))
        }
    };
    let workspaces = WORKSPACES
        .read()
        .map_err(|e| anyhow!("lock error: {}", e))?;
    if let Some(ws) = workspaces.get(&ws_id) {
        let members: Vec<Value> = ws
            .members
            .iter()
            .map(|m| {
                let mut rec = BTreeMap::new();
                rec.insert("user".to_string(), Value::Str(m.user.clone()));
                rec.insert("role".to_string(), Value::Str(m.role.clone()));
                rec.insert("joined_at".to_string(), Value::Str(m.joined_at.clone()));
                Value::Record(rec)
            })
            .collect();
        Ok(Value::Array(members))
    } else {
        Err(anyhow!("workspace '{}' not found", ws_id))
    }
}

/// Share an agent with a workspace.
/// Usage: workspace.share_agent(workspace_id, agent_name)
fn bi_workspace_share_agent(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let ws_id = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        _ => {
            return Err(crate::safety::arg_err(
                "workspace.share_agent requires workspace ID",
            ))
        }
    };
    let agent_name = match args.get(1) {
        Some(Value::Str(s)) => s.clone(),
        _ => {
            return Err(crate::safety::arg_err(
                "workspace.share_agent requires agent name",
            ))
        }
    };
    let mut workspaces = WORKSPACES
        .write()
        .map_err(|e| anyhow!("lock error: {}", e))?;
    if let Some(ws) = workspaces.get_mut(&ws_id) {
        if ws.shared_agents.contains(&agent_name) {
            return Err(anyhow!(
                "agent '{}' already shared in workspace '{}'",
                agent_name,
                ws.name
            ));
        }
        ws.shared_agents.push(agent_name.clone());
        let mut rec = BTreeMap::new();
        rec.insert("workspace_id".to_string(), Value::Str(ws_id));
        rec.insert("agent".to_string(), Value::Str(agent_name));
        rec.insert("status".to_string(), Value::Str("shared".to_string()));
        rec.insert(
            "total_agents".to_string(),
            Value::Int(ws.shared_agents.len() as i64),
        );
        Ok(Value::Record(rec))
    } else {
        Err(anyhow!("workspace '{}' not found", ws_id))
    }
}

