/// Sync workspace state with remote peers.
/// Usage: workspace.sync(workspace_id)
fn bi_workspace_sync(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let ws_id = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        _ => {
            return Err(crate::safety::arg_err(
                "workspace.sync requires workspace ID",
            ))
        }
    };
    let workspaces = WORKSPACES
        .read()
        .map_err(|e| anyhow!("lock error: {}", e))?;
    if let Some(ws) = workspaces.get(&ws_id) {
        let mut rec = BTreeMap::new();
        rec.insert("workspace_id".to_string(), Value::Str(ws_id));
        rec.insert("workspace_name".to_string(), Value::Str(ws.name.clone()));
        rec.insert(
            "members_synced".to_string(),
            Value::Int(ws.members.len() as i64),
        );
        rec.insert(
            "agents_synced".to_string(),
            Value::Int(ws.shared_agents.len() as i64),
        );
        rec.insert("status".to_string(), Value::Str("synced".to_string()));
        rec.insert(
            "timestamp".to_string(),
            Value::Str(chrono::Local::now().to_rfc3339()),
        );
        Ok(Value::Record(rec))
    } else {
        Err(anyhow!("workspace '{}' not found", ws_id))
    }
}

// ===================== Marketplace Builtins =====================

/// Publish a plugin or agent to the marketplace.
/// Publishes to packages.nervosys.ai registry if auth token is set, otherwise local-only.
/// Usage: marketplace.publish({name, version, description, category?, keywords?, path?})
fn bi_marketplace_publish(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let opts = match args.first() {
        Some(Value::Record(r)) => r.clone(),
        _ => {
            return Err(anyhow!(
                "marketplace.publish requires a Record with name, version, description"
            ))
        }
    };
    let name = opts
        .get("name")
        .and_then(|v| {
            if let Value::Str(s) = v {
                Some(s.clone())
            } else {
                None
            }
        })
        .ok_or_else(|| crate::safety::arg_err("marketplace.publish requires 'name'"))?;
    let version = opts
        .get("version")
        .and_then(|v| {
            if let Value::Str(s) = v {
                Some(s.clone())
            } else {
                None
            }
        })
        .ok_or_else(|| crate::safety::arg_err("marketplace.publish requires 'version'"))?;
    let description = opts
        .get("description")
        .and_then(|v| {
            if let Value::Str(s) = v {
                Some(s.clone())
            } else {
                None
            }
        })
        .unwrap_or_default();
    let category = opts
        .get("category")
        .and_then(|v| {
            if let Value::Str(s) = v {
                Some(s.clone())
            } else {
                None
            }
        })
        .unwrap_or_else(|| "general".to_string());
    let keywords = opts
        .get("keywords")
        .and_then(|v| {
            if let Value::Array(arr) = v {
                Some(
                    arr.iter()
                        .filter_map(|v| {
                            if let Value::Str(s) = v {
                                Some(s.clone())
                            } else {
                                None
                            }
                        })
                        .collect::<Vec<_>>(),
                )
            } else {
                None
            }
        })
        .unwrap_or_default();

    let package = MarketplacePackage {
        name: name.clone(),
        version: version.clone(),
        author: get_current_username(),
        description: description.clone(),
        category: category.clone(),
        downloads: 0,
        rating: 0.0,
        rating_count: 0,
        published_at: chrono::Local::now().to_rfc3339(),
        installed: false,
        keywords,
    };

    let mut packages = MARKETPLACE_PACKAGES
        .write()
        .map_err(|e| anyhow!("lock error: {}", e))?;
    packages.insert(name.clone(), package);

    // Try publishing to remote registry if auth token is available
    let mut publish_target = "local".to_string();
    if let Some(tarball_path) = opts.get("path").and_then(|v| {
        if let Value::Str(s) = v {
            Some(std::path::PathBuf::from(s))
        } else {
            None
        }
    }) {
        let manifest = crate::packages::PackageManifest {
            package: crate::packages::PackageInfo {
                name: name.clone(),
                version: version.clone(),
                description: description.clone(),
                authors: vec![get_current_username()],
                license: None,
                repository: None,
                main: "main.ae".to_string(),
            },
            dependencies: std::collections::HashMap::new(),
        };
        let client = crate::packages::RegistryClient::default();
        match client.publish(&tarball_path, &manifest) {
            Ok(()) => publish_target = "registry".to_string(),
            Err(e) => eprintln!("registry publish skipped: {}", e),
        }
    }

    let mut rec = BTreeMap::new();
    rec.insert("name".to_string(), Value::Str(name));
    rec.insert("version".to_string(), Value::Str(version));
    rec.insert("description".to_string(), Value::Str(description));
    rec.insert("category".to_string(), Value::Str(category));
    rec.insert("status".to_string(), Value::Str("published".to_string()));
    rec.insert("target".to_string(), Value::Str(publish_target));
    rec.insert(
        "published_at".to_string(),
        Value::Str(chrono::Local::now().to_rfc3339()),
    );
    Ok(Value::Record(rec))
}

/// Search the marketplace for packages.
/// Searches the remote registry at packages.nervosys.ai, falls back to local cache.
/// Usage: marketplace.search(query) or marketplace.search({q?, category?})
fn bi_marketplace_search(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let (query, category) = match args.first() {
        Some(Value::Str(s)) => (s.to_lowercase(), None),
        Some(Value::Record(r)) => {
            let q = r
                .get("q")
                .or_else(|| r.get("query"))
                .and_then(|v| {
                    if let Value::Str(s) = v {
                        Some(s.to_lowercase())
                    } else {
                        None
                    }
                })
                .unwrap_or_default();
            let cat = r.get("category").and_then(|v| {
                if let Value::Str(s) = v {
                    Some(s.clone())
                } else {
                    None
                }
            });
            (q, cat)
        }
        _ => (String::new(), None),
    };

    // Try remote registry first
    let client = crate::packages::RegistryClient::default();
    if let Ok(remote_pkgs) = client.search(&query, category.as_deref()) {
        if !remote_pkgs.is_empty() {
            let results: Vec<Value> = remote_pkgs
                .iter()
                .map(crate::packages::RegistryClient::package_to_value)
                .collect();
            return Ok(Value::Array(results));
        }
    }

    // Fall back to local cache
    let packages = MARKETPLACE_PACKAGES
        .read()
        .map_err(|e| anyhow!("lock error: {}", e))?;
    let results: Vec<Value> = packages
        .values()
        .filter(|pkg| {
            let matches_query = query.is_empty()
                || pkg.name.to_lowercase().contains(&query)
                || pkg.description.to_lowercase().contains(&query)
                || pkg
                    .keywords
                    .iter()
                    .any(|k| k.to_lowercase().contains(&query));
            let matches_category = category
                .as_ref()
                .map(|c| pkg.category.to_lowercase() == c.to_lowercase())
                .unwrap_or(true);
            matches_query && matches_category
        })
        .map(marketplace_package_to_value)
        .collect();

    Ok(Value::Array(results))
}

fn marketplace_package_to_value(pkg: &MarketplacePackage) -> Value {
    let mut rec = BTreeMap::new();
    rec.insert("name".to_string(), Value::Str(pkg.name.clone()));
    rec.insert("version".to_string(), Value::Str(pkg.version.clone()));
    rec.insert("author".to_string(), Value::Str(pkg.author.clone()));
    rec.insert(
        "description".to_string(),
        Value::Str(pkg.description.clone()),
    );
    rec.insert("category".to_string(), Value::Str(pkg.category.clone()));
    rec.insert("downloads".to_string(), Value::Int(pkg.downloads));
    rec.insert("rating".to_string(), Value::Float(pkg.rating));
    rec.insert("rating_count".to_string(), Value::Int(pkg.rating_count));
    rec.insert(
        "published_at".to_string(),
        Value::Str(pkg.published_at.clone()),
    );
    rec.insert("installed".to_string(), Value::Bool(pkg.installed));
    if !pkg.keywords.is_empty() {
        rec.insert(
            "keywords".to_string(),
            Value::Array(pkg.keywords.iter().map(|k| Value::Str(k.clone())).collect()),
        );
    }
    Value::Record(rec)
}

/// Install a package from the marketplace.
/// Downloads from packages.nervosys.ai registry, falls back to local cache.
/// Usage: marketplace.install(name) or marketplace.install(name, version)
fn bi_marketplace_install(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let name = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        _ => {
            return Err(crate::safety::arg_err(
                "marketplace.install requires package name",
            ))
        }
    };
    let version = match args.get(1) {
        Some(Value::Str(s)) => Some(s.clone()),
        _ => None,
    };

    // Try remote registry first
    let client = crate::packages::RegistryClient::default();
    if let Ok(pkg_info) = client.get_package(&name) {
        let ver = version.as_deref().unwrap_or(&pkg_info.version);
        match client.download_package(&name, ver) {
            Ok(install_path) => {
                // Update local cache
                if let Ok(mut packages) = MARKETPLACE_PACKAGES.write() {
                    let existing =
                        packages
                            .entry(name.clone())
                            .or_insert_with(|| MarketplacePackage {
                                name: name.clone(),
                                version: ver.to_string(),
                                author: pkg_info.author.clone(),
                                description: pkg_info.description.clone(),
                                category: pkg_info
                                    .category
                                    .clone()
                                    .unwrap_or_else(|| "general".to_string()),
                                downloads: pkg_info.downloads,
                                rating: 0.0,
                                rating_count: 0,
                                published_at: pkg_info.created_at.clone(),
                                installed: false,
                                keywords: pkg_info.keywords.clone(),
                            });
                    existing.installed = true;
                    existing.downloads += 1;
                }
                let mut rec = BTreeMap::new();
                rec.insert("name".to_string(), Value::Str(name));
                rec.insert("version".to_string(), Value::Str(ver.to_string()));
                rec.insert("status".to_string(), Value::Str("installed".to_string()));
                rec.insert("source".to_string(), Value::Str("registry".to_string()));
                rec.insert(
                    "path".to_string(),
                    Value::Str(install_path.display().to_string()),
                );
                rec.insert(
                    "installed_at".to_string(),
                    Value::Str(chrono::Local::now().to_rfc3339()),
                );
                return Ok(Value::Record(rec));
            }
            Err(e) => {
                // Log but continue to local fallback
                eprintln!("registry download failed: {}, trying local cache", e);
            }
        }
    }

    // Fall back to local cache
    let mut packages = MARKETPLACE_PACKAGES
        .write()
        .map_err(|e| anyhow!("lock error: {}", e))?;
    if let Some(pkg) = packages.get_mut(&name) {
        pkg.installed = true;
        pkg.downloads += 1;
        let mut rec = BTreeMap::new();
        rec.insert("name".to_string(), Value::Str(pkg.name.clone()));
        rec.insert("version".to_string(), Value::Str(pkg.version.clone()));
        rec.insert("status".to_string(), Value::Str("installed".to_string()));
        rec.insert("source".to_string(), Value::Str("local_cache".to_string()));
        rec.insert(
            "installed_at".to_string(),
            Value::Str(chrono::Local::now().to_rfc3339()),
        );
        Ok(Value::Record(rec))
    } else {
        Err(anyhow!(
            "package '{}' not found in marketplace or registry",
            name
        ))
    }
}

/// Uninstall a marketplace package.
/// Usage: marketplace.uninstall(name)
fn bi_marketplace_uninstall(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let name = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        _ => {
            return Err(crate::safety::arg_err(
                "marketplace.uninstall requires package name",
            ))
        }
    };
    let mut packages = MARKETPLACE_PACKAGES
        .write()
        .map_err(|e| anyhow!("lock error: {}", e))?;
    if let Some(pkg) = packages.get_mut(&name) {
        pkg.installed = false;
        let mut rec = BTreeMap::new();
        rec.insert("name".to_string(), Value::Str(pkg.name.clone()));
        rec.insert("status".to_string(), Value::Str("uninstalled".to_string()));
        rec.insert(
            "uninstalled_at".to_string(),
            Value::Str(chrono::Local::now().to_rfc3339()),
        );
        Ok(Value::Record(rec))
    } else {
        Err(anyhow!("package '{}' not found", name))
    }
}

/// List installed marketplace packages.
/// Usage: marketplace.list()
fn bi_marketplace_list(_args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let packages = MARKETPLACE_PACKAGES
        .read()
        .map_err(|e| anyhow!("lock error: {}", e))?;
    let installed: Vec<Value> = packages
        .values()
        .filter(|pkg| pkg.installed)
        .map(marketplace_package_to_value)
        .collect();
    Ok(Value::Array(installed))
}

/// Get detailed info about a marketplace package.
/// Checks remote registry first, falls back to local cache.
/// Usage: marketplace.info(name)
fn bi_marketplace_info(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let name = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        _ => {
            return Err(crate::safety::arg_err(
                "marketplace.info requires package name",
            ))
        }
    };

    // Try remote registry first
    let client = crate::packages::RegistryClient::default();
    if let Ok(pkg) = client.get_package(&name) {
        return Ok(crate::packages::RegistryClient::package_to_value(&pkg));
    }

    // Fall back to local cache
    let packages = MARKETPLACE_PACKAGES
        .read()
        .map_err(|e| anyhow!("lock error: {}", e))?;
    if let Some(pkg) = packages.get(&name) {
        Ok(marketplace_package_to_value(pkg))
    } else {
        Err(anyhow!(
            "package '{}' not found in marketplace or registry",
            name
        ))
    }
}

/// Rate a marketplace package.
/// Usage: marketplace.rate(name, score) — score 1-5
fn bi_marketplace_rate(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let name = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        _ => {
            return Err(crate::safety::arg_err(
                "marketplace.rate requires package name",
            ))
        }
    };
    let score = match args.get(1) {
        Some(Value::Int(n)) => *n as f64,
        Some(Value::Float(f)) => *f,
        _ => {
            return Err(crate::safety::arg_err(
                "marketplace.rate requires a score (1-5)",
            ))
        }
    };
    if !(1.0..=5.0).contains(&score) {
        return Err(anyhow!("rating must be between 1 and 5"));
    }
    let mut packages = MARKETPLACE_PACKAGES
        .write()
        .map_err(|e| anyhow!("lock error: {}", e))?;
    if let Some(pkg) = packages.get_mut(&name) {
        // Compute new weighted average
        let total = pkg.rating * pkg.rating_count as f64 + score;
        pkg.rating_count += 1;
        pkg.rating = total / pkg.rating_count as f64;
        let mut rec = BTreeMap::new();
        rec.insert("name".to_string(), Value::Str(pkg.name.clone()));
        rec.insert("rating".to_string(), Value::Float(pkg.rating));
        rec.insert("rating_count".to_string(), Value::Int(pkg.rating_count));
        rec.insert("your_rating".to_string(), Value::Float(score));
        Ok(Value::Record(rec))
    } else {
        Err(anyhow!("package '{}' not found in marketplace", name))
    }
}

/// Update an installed marketplace package to the latest version.
/// Checks the remote registry for newer versions.
/// Usage: marketplace.update(name) or marketplace.update() for all
fn bi_marketplace_update(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let client = crate::packages::RegistryClient::default();
    let packages = MARKETPLACE_PACKAGES
        .read()
        .map_err(|e| anyhow!("lock error: {}", e))?;
    if let Some(Value::Str(name)) = args.first() {
        // Update single package
        if let Some(pkg) = packages.get(name) {
            if !pkg.installed {
                return Err(anyhow!("package '{}' is not installed", name));
            }
            // Check remote for newer version
            let mut remote_version = None;
            if let Ok(remote_pkg) = client.get_package(name) {
                if remote_pkg.version != pkg.version {
                    remote_version = Some(remote_pkg.version);
                }
            }
            let mut rec = BTreeMap::new();
            rec.insert("name".to_string(), Value::Str(pkg.name.clone()));
            rec.insert("version".to_string(), Value::Str(pkg.version.clone()));
            if let Some(new_ver) = remote_version {
                rec.insert("latest".to_string(), Value::Str(new_ver));
                rec.insert(
                    "status".to_string(),
                    Value::Str("update_available".to_string()),
                );
            } else {
                rec.insert("status".to_string(), Value::Str("up_to_date".to_string()));
            }
            rec.insert(
                "checked_at".to_string(),
                Value::Str(chrono::Local::now().to_rfc3339()),
            );
            Ok(Value::Record(rec))
        } else {
            Err(anyhow!("package '{}' not found", name))
        }
    } else {
        // Update all installed
        let results: Vec<Value> = packages
            .values()
            .filter(|pkg| pkg.installed)
            .map(|pkg| {
                let mut rec = BTreeMap::new();
                rec.insert("name".to_string(), Value::Str(pkg.name.clone()));
                rec.insert("version".to_string(), Value::Str(pkg.version.clone()));
                rec.insert("status".to_string(), Value::Str("up_to_date".to_string()));
                Value::Record(rec)
            })
            .collect();
        Ok(Value::Array(results))
    }
}

// ===================== Telemetry & Analytics Builtins =====================

/// Enable opt-in telemetry.
/// Usage: telemetry.enable()
fn bi_telemetry_enable(_args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let mut enabled = TELEMETRY_ENABLED
        .write()
        .map_err(|e| anyhow!("lock error: {}", e))?;
    *enabled = true;

    // Record the opt-in event
    let event = TelemetryEvent {
        id: uuid::Uuid::new_v4().to_string(),
        event_type: "telemetry_enabled".to_string(),
        category: "system".to_string(),
        data: HashMap::new(),
        timestamp: chrono::Local::now().to_rfc3339(),
        session_id: uuid::Uuid::new_v4().to_string(),
    };
    if let Ok(mut events) = TELEMETRY_EVENTS.write() {
        events.push(event);
    }

    let mut rec = BTreeMap::new();
    rec.insert("enabled".to_string(), Value::Bool(true));
    rec.insert(
        "status".to_string(),
        Value::Str("telemetry enabled (opt-in)".to_string()),
    );
    rec.insert(
        "note".to_string(),
        Value::Str("Data is stored locally. Use telemetry.report() to view.".to_string()),
    );
    Ok(Value::Record(rec))
}

/// Disable telemetry.
/// Usage: telemetry.disable()
fn bi_telemetry_disable(_args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let mut enabled = TELEMETRY_ENABLED
        .write()
        .map_err(|e| anyhow!("lock error: {}", e))?;
    *enabled = false;

    let mut rec = BTreeMap::new();
    rec.insert("enabled".to_string(), Value::Bool(false));
    rec.insert(
        "status".to_string(),
        Value::Str("telemetry disabled".to_string()),
    );
    Ok(Value::Record(rec))
}

/// Get current telemetry status.
/// Usage: telemetry.status()
fn bi_telemetry_status(_args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let enabled = TELEMETRY_ENABLED
        .read()
        .map_err(|e| anyhow!("lock error: {}", e))?;
    let events = TELEMETRY_EVENTS
        .read()
        .map_err(|e| anyhow!("lock error: {}", e))?;

    let mut rec = BTreeMap::new();
    rec.insert("enabled".to_string(), Value::Bool(*enabled));
    rec.insert("event_count".to_string(), Value::Int(events.len() as i64));
    rec.insert("storage".to_string(), Value::Str("local".to_string()));
    rec.insert(
        "privacy".to_string(),
        Value::Str("All data stored locally. No external transmission.".to_string()),
    );
    Ok(Value::Record(rec))
}

/// Generate a telemetry usage report.
/// Usage: telemetry.report() or telemetry.report({category?, since?})
fn bi_telemetry_report(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let opts = match args.first() {
        Some(Value::Record(r)) => r.clone(),
        _ => BTreeMap::new(),
    };
    let category_filter = opts.get("category").and_then(|v| {
        if let Value::Str(s) = v {
            Some(s.clone())
        } else {
            None
        }
    });

    let events = TELEMETRY_EVENTS
        .read()
        .map_err(|e| anyhow!("lock error: {}", e))?;

    // Group by category
    let mut by_category: HashMap<String, i64> = HashMap::new();
    let mut by_type: HashMap<String, i64> = HashMap::new();
    let mut filtered_count = 0i64;

    for event in events.iter() {
        let include = category_filter
            .as_ref()
            .map(|c| event.category == *c)
            .unwrap_or(true);
        if include {
            filtered_count += 1;
            *by_category.entry(event.category.clone()).or_insert(0) += 1;
            *by_type.entry(event.event_type.clone()).or_insert(0) += 1;
        }
    }

    let categories: Vec<Value> = by_category
        .iter()
        .map(|(k, v)| {
            let mut rec = BTreeMap::new();
            rec.insert("category".to_string(), Value::Str(k.clone()));
            rec.insert("count".to_string(), Value::Int(*v));
            Value::Record(rec)
        })
        .collect();

    let types: Vec<Value> = by_type
        .iter()
        .map(|(k, v)| {
            let mut rec = BTreeMap::new();
            rec.insert("event_type".to_string(), Value::Str(k.clone()));
            rec.insert("count".to_string(), Value::Int(*v));
            Value::Record(rec)
        })
        .collect();

    let mut rec = BTreeMap::new();
    rec.insert("total_events".to_string(), Value::Int(filtered_count));
    rec.insert("by_category".to_string(), Value::Array(categories));
    rec.insert("by_type".to_string(), Value::Array(types));
    rec.insert(
        "generated_at".to_string(),
        Value::Str(chrono::Local::now().to_rfc3339()),
    );
    Ok(Value::Record(rec))
}

/// Get raw telemetry events.
/// Usage: telemetry.events() or telemetry.events(limit)
fn bi_telemetry_events(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let limit = match args.first() {
        Some(Value::Int(n)) => *n as usize,
        _ => 100,
    };
    let events = TELEMETRY_EVENTS
        .read()
        .map_err(|e| anyhow!("lock error: {}", e))?;
    let entries: Vec<Value> = events
        .iter()
        .rev()
        .take(limit)
        .map(|e| {
            let mut rec = BTreeMap::new();
            rec.insert("id".to_string(), Value::Str(e.id.clone()));
            rec.insert("event_type".to_string(), Value::Str(e.event_type.clone()));
            rec.insert("category".to_string(), Value::Str(e.category.clone()));
            rec.insert("timestamp".to_string(), Value::Str(e.timestamp.clone()));
            rec.insert("session_id".to_string(), Value::Str(e.session_id.clone()));
            if !e.data.is_empty() {
                let data_rec: BTreeMap<String, Value> = e
                    .data
                    .iter()
                    .map(|(k, v)| (k.clone(), Value::Str(v.clone())))
                    .collect();
                rec.insert("data".to_string(), Value::Record(data_rec));
            }
            Value::Record(rec)
        })
        .collect();
    Ok(Value::Array(entries))
}

/// Reset (clear) all telemetry data.
/// Usage: telemetry.reset()
fn bi_telemetry_reset(_args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let mut events = TELEMETRY_EVENTS
        .write()
        .map_err(|e| anyhow!("lock error: {}", e))?;
    let count = events.len();
    events.clear();

    let mut rec = BTreeMap::new();
    rec.insert("cleared".to_string(), Value::Int(count as i64));
    rec.insert(
        "status".to_string(),
        Value::Str("all telemetry data cleared".to_string()),
    );
    rec.insert(
        "timestamp".to_string(),
        Value::Str(chrono::Local::now().to_rfc3339()),
    );
    Ok(Value::Record(rec))
}

