// --- pytest (1102) ---

/// pytest — Run Python tests.
fn bi_pytest_run(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let extra: Vec<String> = args
        .iter()
        .filter_map(|a| match a {
            Value::Str(s) => Some(s.clone()),
            _ => None,
        })
        .collect();
    let mut cmd = std::process::Command::new("pytest");
    cmd.arg("-v");
    for a in &extra {
        cmd.arg(a);
    }
    let output = cmd.output();
    match output {
        Ok(o) => {
            let mut rec = BTreeMap::new();
            rec.insert(
                "exit_code".to_string(),
                Value::Int(o.status.code().unwrap_or(-1) as i64),
            );
            rec.insert("success".to_string(), Value::Bool(o.status.success()));
            rec.insert(
                "stdout".to_string(),
                Value::Str(String::from_utf8_lossy(&o.stdout).trim().to_string()),
            );
            rec.insert(
                "stderr".to_string(),
                Value::Str(String::from_utf8_lossy(&o.stderr).trim().to_string()),
            );
            Ok(Value::Record(rec))
        }
        Err(e) => Err(anyhow!("pytest not found: {}", e)),
    }
}

// --- nodemon (1103) ---

/// nodemon — Auto-restart Node.js app on changes.
fn bi_nodemon_run(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let script = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        _ => return Err(crate::safety::arg_err("nodemon requires a script path")),
    };
    let mut rec = BTreeMap::new();
    rec.insert("script".to_string(), Value::Str(script.clone()));
    rec.insert(
        "info".to_string(),
        Value::Str(format!(
            "Use `nodemon {}` to start watching. This is a long-running command.",
            script
        )),
    );
    Ok(Value::Record(rec))
}

#[cfg(test)]
mod fips_tests {
    use super::*;

    /// The FIPS posture (`safety::require_fips_hash`) had no test coverage at
    /// all, despite being the enforcement point the compliance claim rests on.
    /// This pins it: MD5 and SHA-1 are refused under `AETHER_FIPS`, SHA-256
    /// still works, and MD5 stays available for legacy interop when FIPS is off.
    #[test]
    fn file_checksum_honors_the_fips_gate() {
        let _env = crate::safety::ENV_LOCK
            .lock()
            .unwrap_or_else(|e| e.into_inner());

        let dir = std::env::temp_dir().join("ae_fips_checksum_test");
        std::fs::create_dir_all(&dir).unwrap();
        let path = dir.join("sample.txt");
        std::fs::write(&path, b"aethershell").unwrap();
        // Repointed from `bi_file_checksum` to `bi_crypto_hash_file` when the
        // former was deleted as unreachable: it duplicated this one and nothing
        // dispatched to it, so the only coverage of the FIPS gate was pointed at
        // a builtin no caller could reach. Argument order here is (path, algo).
        let call = |algo: &str| {
            bi_crypto_hash_file(
                vec![
                    Value::Str(path.to_string_lossy().to_string()),
                    Value::Str(algo.to_string()),
                ],
                None,
            )
        };

        std::env::remove_var("AETHER_FIPS");
        assert!(
            call("md5").is_ok(),
            "MD5 stays available for legacy interop when FIPS is off"
        );

        std::env::set_var("AETHER_FIPS", "1");
        for weak in ["md5", "sha1"] {
            let err = call(weak).unwrap_err().to_string();
            assert!(
                err.contains("E_FIPS_DISALLOWED"),
                "FIPS mode must refuse {weak} with a machine-readable code; got: {err}"
            );
        }
        assert!(call("sha256").is_ok(), "sha256 is FIPS-approved");

        std::env::remove_var("AETHER_FIPS");
        let _ = std::fs::remove_dir_all(&dir);
    }
}
